  .do(e, r"---(act_map <- .tmp[[2]])---")
  .do(e, r"---(sndx <- .tmp[[3]])---")
  .do(e, r"---(gen <- .tmp[[4]])---")
  expect_equal(.run(e, r"---(actual)---"), r"---([X(i0)])---")
  expect_equal(.run(e, r"---(act_map)---"), r"---({i0: 0})---")
  .do(e, r"---(expected <- list(XGate(i0), YGate(i0), ZGate(i0), HadamardGate(i0)))---")
  .do(e, r"---(exp_map <- .qdict(list(i0), list(Integer(S(0)))))---")
  .do(e, r"---(.tmp <- convert_to_symbolic_indices(list(x, y, z, h)))---")
  .do(e, r"---(actual <- .tmp[[1]])---")
  .do(e, r"---(act_map <- .tmp[[2]])---")
