  expect_equal(.run(e, r"---(actual)---"), r"---([X(i0), Y(i0), Z(i0), H(i0)])---")
  expect_equal(.run(e, r"---(act_map)---"), r"---({i0: 1})---")
  .do(e, r"---(expected <- list(XGate(i0), YGate(i0), ZGate(i0), HadamardGate(i0), XGate(i1), YGate(i1), ZGate(i1), HadamardGate(i1)))---")
  .do(e, r"---(exp_map <- .qdict(list(i0, i1), list(Integer(S(0)), Integer(S(1)))))---")
  .do(e, r"---(.tmp <- convert_to_symbolic_indices(list(x, y, z, h, x1, y1, z1, h1)))---")
  .do(e, r"---(actual <- .tmp[[1]])---")
  .do(e, r"---(act_map <- .tmp[[2]])---")
  .do(e, r"---(sndx <- .tmp[[3]])---")
  .do(e, r"---(gen <- .tmp[[4]])---")
  expect_equal(.run(e, r"---(actual)---"), r"---([X(i0), Y(i0), Z(i0), H(i0), X(i1), Y(i1), Z(i1), H(i1)])---")
  expect_equal(.run(e, r"---(act_map)---"), r"---({i0: 0, i1: 1})---")
  .do(e, r"---(exp_map <- .qdict(list(i0, i1), list(Integer(S(1)), Integer(S(0)))))---")
  .do(e, r"---(.tmp <- convert_to_symbolic_indices(Mul(x1, y1, z1, h1, x, y, z, h)))---")
