  .do(e, r"---(gen <- .tmp[[4]])---")
  expect_equal(.run(e, r"---(actual)---"), r"---([X(i0), Y(i0), Z(i0), H(i0), X(i1), Y(i1), Z(i1), H(i1)])---")
  expect_equal(.run(e, r"---(act_map)---"), r"---({i0: 1, i1: 0})---")
  .do(e, r"---(expected <- list(XGate(i0), XGate(i1), YGate(i0), YGate(i1), ZGate(i0), ZGate(i1), HadamardGate(i0), HadamardGate(i1)))---")
  .do(e, r"---(exp_map <- .qdict(list(i0, i1), list(Integer(S(0)), Integer(S(1)))))---")
