  .do(e, r"---(gen <- .tmp[[4]])---")
  expect_equal(.run(e, r"---(actual)---"), r"---([X(i0), X(i1), Y(i0), Y(i1), Z(i0), Z(i1), H(i0), H(i1)])---")
  expect_equal(.run(e, r"---(act_map)---"), r"---({i0: 0, i1: 1})---")
  .do(e, r"---(exp_map <- .qdict(list(i0, i1), list(Integer(S(1)), Integer(S(0)))))---")
