  .do(e, r"---(expected <- list(XGate(i0), XGate(i1), YGate(i0), YGate(i1), ZGate(i0), ZGate(i1), HadamardGate(i0), HadamardGate(i1), CNotGate(i0, i1), CNotGate(i1, i0), CGate(i0, ZGate(i1)), CGate(i1, ZGate(i0))))---")
  .do(e, r"---(exp_map <- .qdict(list(i0, i1), list(Integer(S(1)), Integer(S(0)))))---")
  .do(e, r"---(.tmp <- convert_to_symbolic_indices(args))---")
  .do(e, r"---(actual <- .tmp[[1]])---")
  .do(e, r"---(act_map <- .tmp[[2]])---")
  .do(e, r"---(sndx <- .tmp[[3]])---")
  .do(e, r"---(gen <- .tmp[[4]])---")
  expect_equal(.run(e, r"---(actual)---"), r"---([X(i0), X(i1), Y(i0), Y(i1), Z(i0), Z(i1), H(i0), H(i1), CNOT(i0,i1), CNOT(i1,i0), C((i0),Z(i1)), C((i1),Z(i0))])---")
  expect_equal(.run(e, r"---(act_map)---"), r"---({i0: 1, i1: 0})---")
  .do(e, r"---(args <- list(cnot_10, h, cgate_z_01, h))---")
  .do(e, r"---(expected <- list(CNotGate(i0, i1), HadamardGate(i1), CGate(i1, ZGate(i0)), HadamardGate(i1)))---")
  .do(e, r"---(exp_map <- .qdict(list(i0, i1), list(Integer(S(1)), Integer(S(0)))))---")
  .do(e, r"---(.tmp <- convert_to_symbolic_indices(args))---")
  .do(e, r"---(actual <- .tmp[[1]])---")
  .do(e, r"---(act_map <- .tmp[[2]])---")
  .do(e, r"---(sndx <- .tmp[[3]])---")
  .do(e, r"---(gen <- .tmp[[4]])---")
  expect_equal(.run(e, r"---(actual)---"), r"---([CNOT(i0,i1), H(i1), C((i1),Z(i0)), H(i1)])---")
  expect_equal(.run(e, r"---(act_map)---"), r"---({i0: 1, i1: 0})---")
  .do(e, r"---(args <- list(cnot_01, h1, cgate_z_10, h1))---")
  .do(e, r"---(exp_map <- .qdict(list(i0, i1), list(Integer(S(0)), Integer(S(1)))))---")
  .do(e, r"---(.tmp <- convert_to_symbolic_indices(args))---")
  .do(e, r"---(actual <- .tmp[[1]])---")
  .do(e, r"---(act_map <- .tmp[[2]])---")
  .do(e, r"---(sndx <- .tmp[[3]])---")
  .do(e, r"---(gen <- .tmp[[4]])---")
  expect_equal(.run(e, r"---(actual)---"), r"---([CNOT(i0,i1), H(i1), C((i1),Z(i0)), H(i1)])---")
  expect_equal(.run(e, r"---(act_map)---"), r"---({i0: 0, i1: 1})---")
  .do(e, r"---(args <- list(cnot_10, h1, cgate_z_01, h1))---")
  .do(e, r"---(expected <- list(CNotGate(i0, i1), HadamardGate(i0), CGate(i1, ZGate(i0)), HadamardGate(i0)))---")
  .do(e, r"---(exp_map <- .qdict(list(i0, i1), list(Integer(S(1)), Integer(S(0)))))---")
  .do(e, r"---(.tmp <- convert_to_symbolic_indices(args))---")
  .do(e, r"---(actual <- .tmp[[1]])---")
  .do(e, r"---(act_map <- .tmp[[2]])---")
  .do(e, r"---(sndx <- .tmp[[3]])---")
  .do(e, r"---(gen <- .tmp[[4]])---")
  expect_equal(.run(e, r"---(actual)---"), r"---([CNOT(i0,i1), H(i0), C((i1),Z(i0)), H(i0)])---")
  expect_equal(.run(e, r"---(act_map)---"), r"---({i0: 1, i1: 0})---")
  .do(e, r"---(i2 <- Symbol("i2"))---")
  .do(e, r"---(ccgate_z <- CGate(S(0), CGate(S(1), ZGate(S(2)))))---")
  .do(e, r"---(ccgate_x <- CGate(S(1), CGate(S(2), XGate(S(0)))))---")
  .do(e, r"---(args <- list(ccgate_z, ccgate_x))---")
  .do(e, r"---(expected <- list(CGate(i0, CGate(i1, ZGate(i2))), CGate(i1, CGate(i2, XGate(i0)))))---")
  .do(e, r"---(exp_map <- .qdict(list(i0, i1, i2), list(Integer(S(0)), Integer(S(1)), Integer(S(2)))))---")
  .do(e, r"---(.tmp <- convert_to_symbolic_indices(args))---")
  .do(e, r"---(actual <- .tmp[[1]])---")
  .do(e, r"---(act_map <- .tmp[[2]])---")
  .do(e, r"---(sndx <- .tmp[[3]])---")
  .do(e, r"---(gen <- .tmp[[4]])---")
  expect_equal(.run(e, r"---(actual)---"), r"---([C((i0),C((i1),Z(i2))), C((i1),C((i2),X(i0)))])---")
  expect_equal(.run(e, r"---(act_map)---"), r"---({i0: 0, i1: 1, i2: 2})---")
  .do(e, r"---(ndx_map <- .qdict(list(i0), list(Integer(S(0)))))---")
  .do(e, r"---(index_gen <- numbered_symbols(prefix = "i", start = S(1)))---")
  .do(e, r"---(.tmp <- convert_to_symbolic_indices(args, qubit_map = ndx_map, start = i0, gen = index_gen))---")
  .do(e, r"---(actual <- .tmp[[1]])---")
  .do(e, r"---(act_map <- .tmp[[2]])---")
  .do(e, r"---(sndx <- .tmp[[3]])---")
  .do(e, r"---(gen <- .tmp[[4]])---")
  expect_equal(.run(e, r"---(actual)---"), r"---([C((i0),C((i1),Z(i2))), C((i1),C((i2),X(i0)))])---")
  expect_equal(.run(e, r"---(act_map)---"), r"---({i0: 0, i1: 1, i2: 2})---")
  .do(e, r"---(i3 <- Symbol("i3"))---")
  .do(e, r"---(cgate_x0_c321 <- CGate(list(S(3), S(2), S(1)), XGate(S(0))))---")
  .do(e, r"---(exp_map <- .qdict(list(i0, i1, i2, i3), list(Integer(S(3)), Integer(S(2)), Integer(S(1)), Integer(S(0)))))---")
  .do(e, r"---(expected <- list(CGate(list(i0, i1, i2), XGate(i3))))---")
  .do(e, r"---(args <- list(cgate_x0_c321))---")
  .do(e, r"---(.tmp <- convert_to_symbolic_indices(args))---")
  .do(e, r"---(actual <- .tmp[[1]])---")
  .do(e, r"---(act_map <- .tmp[[2]])---")
  .do(e, r"---(sndx <- .tmp[[3]])---")
  .do(e, r"---(gen <- .tmp[[4]])---")
  expect_equal(.run(e, r"---(actual)---"), r"---([C((i0,i1,i2),X(i3))])---")
  expect_equal(.run(e, r"---(act_map)---"), r"---({i0: 3, i1: 2, i2: 1, i3: 0})---")
})

test_that("test_circuitutils: test_convert_to_real_indices", {
  e <- .new(character(), 'test_circuitutils')
  .do(e, r"---(i0 <- Symbol("i0"))---")
  .do(e, r"---(i1 <- Symbol("i1"))---")
  .do(e, r"---(.tmp <- create_gate_sequence())---")
  .do(e, r"---(x <- .tmp[[1]])---")
  .do(e, r"---(y <- .tmp[[2]])---")
  .do(e, r"---(z <- .tmp[[3]])---")
  .do(e, r"---(h <- .tmp[[4]])---")
  .do(e, r"---(x_i0 <- XGate(i0))---")
  .do(e, r"---(y_i0 <- YGate(i0))---")
  .do(e, r"---(z_i0 <- ZGate(i0))---")
  .do(e, r"---(qubit_map <- .qdict(list(i0), list(S(0))))---")
  .do(e, r"---(args <- list(z_i0, y_i0, x_i0))---")
  .do(e, r"---(expected <- list(z, y, x))---")
  .do(e, r"---(actual <- convert_to_real_indices(args, qubit_map))---")
  expect_equal(.run(e, r"---(actual)---"), r"---([Z(0), Y(0), X(0)])---")
  .do(e, r"---(cnot_10 <- CNotGate(S(1), S(0)))---")
  .do(e, r"---(cnot_01 <- CNotGate(S(0), S(1)))---")
  .do(e, r"---(cgate_z_10 <- CGate(S(1), ZGate(S(0))))---")
  .do(e, r"---(cgate_z_01 <- CGate(S(0), ZGate(S(1))))---")
  .do(e, r"---(cnot_i1_i0 <- CNotGate(i1, i0))---")
  .do(e, r"---(cnot_i0_i1 <- CNotGate(i0, i1))---")
  .do(e, r"---(cgate_z_i1_i0 <- CGate(i1, ZGate(i0)))---")
  .do(e, r"---(qubit_map <- .qdict(list(i0, i1), list(S(0), S(1))))---")
  .do(e, r"---(args <- list(cnot_i1_i0))---")
  .do(e, r"---(expected <- list(cnot_10))---")
  .do(e, r"---(actual <- convert_to_real_indices(args, qubit_map))---")
  expect_equal(.run(e, r"---(actual)---"), r"---([CNOT(1,0)])---")
  .do(e, r"---(args <- list(cgate_z_i1_i0))---")
  .do(e, r"---(expected <- list(cgate_z_10))---")
  .do(e, r"---(actual <- convert_to_real_indices(args, qubit_map))---")
  expect_equal(.run(e, r"---(actual)---"), r"---([C((1),Z(0))])---")
  .do(e, r"---(args <- list(cnot_i0_i1))---")
  .do(e, r"---(expected <- list(cnot_01))---")
  .do(e, r"---(actual <- convert_to_real_indices(args, qubit_map))---")
  expect_equal(.run(e, r"---(actual)---"), r"---([CNOT(0,1)])---")
  .do(e, r"---(qubit_map <- .qdict(list(i0, i1), list(S(1), S(0))))---")
  .do(e, r"---(args <- list(cgate_z_i1_i0))---")
  .do(e, r"---(expected <- list(cgate_z_01))---")
  .do(e, r"---(actual <- convert_to_real_indices(args, qubit_map))---")
  expect_equal(.run(e, r"---(actual)---"), r"---([C((0),Z(1))])---")
  .do(e, r"---(i2 <- Symbol("i2"))---")
  .do(e, r"---(ccgate_z <- CGate(i0, CGate(i1, ZGate(i2))))---")
  .do(e, r"---(ccgate_x <- CGate(i1, CGate(i2, XGate(i0))))---")
  .do(e, r"---(qubit_map <- .qdict(list(i0, i1, i2), list(S(0), S(1), S(2))))---")
  .do(e, r"---(args <- list(ccgate_z, ccgate_x))---")
  .do(e, r"---(expected <- list(CGate(S(0), CGate(S(1), ZGate(S(2)))), CGate(S(1), CGate(S(2), XGate(S(0))))))---")
  .do(e, r"---(actual <- convert_to_real_indices(do.call(Mul, c(.qlist(args))), qubit_map))---")
  expect_equal(.run(e, r"---(actual)---"), r"---([C((0),C((1),Z(2))), C((1),C((2),X(0)))])---")
  .do(e, r"---(qubit_map <- .qdict(list(i0, i2, i1), list(S(1), S(0), S(2))))---")
  .do(e, r"---(args <- list(ccgate_x, ccgate_z))---")
  .do(e, r"---(expected <- list(CGate(S(2), CGate(S(0), XGate(S(1)))), CGate(S(1), CGate(S(2), ZGate(S(0))))))---")
  .do(e, r"---(actual <- convert_to_real_indices(args, qubit_map))---")
  expect_equal(.run(e, r"---(actual)---"), r"---([C((2),C((0),X(1))), C((1),C((2),Z(0)))])---")
})

test_that("test_commutator: test_commutator", {
  e <- .new(c(r"---(.tmp <- sym_symbols("a,b,c"))---", r"---(a <- .tmp[[1]])---", r"---(b <- .tmp[[2]])---", r"---(v_c <- .tmp[[3]])---", r"---(n <- sym_symbols("n", integer = TRUE))---", r"---(.tmp <- sym_symbols("A,B,C,D", commutative = FALSE))---", r"---(A <- .tmp[[1]])---", r"---(B <- .tmp[[2]])---", r"---(v_C <- .tmp[[3]])---", r"---(v_D <- .tmp[[4]])---"), 'test_commutator')
  .do(e, r"---(v_c <- Commutator(A, B))---")
  expect_equal(.run(e, r"---(qattr(v_c, "is_commutative"))---"), r"---(False)---")
  expect_equal(.run(e, r"---(qisinstance(v_c, "QCommutator"))---"), r"---(True)---")
  expect_equal(.run(e, r"---(subs(v_c, A, v_C))---"), r"---(-[B,C])---")
})

test_that("test_commutator: test_commutator_identities", {
  e <- .new(c(r"---(.tmp <- sym_symbols("a,b,c"))---", r"---(a <- .tmp[[1]])---", r"---(b <- .tmp[[2]])---", r"---(v_c <- .tmp[[3]])---", r"---(n <- sym_symbols("n", integer = TRUE))---", r"---(.tmp <- sym_symbols("A,B,C,D", commutative = FALSE))---", r"---(A <- .tmp[[1]])---", r"---(B <- .tmp[[2]])---", r"---(v_C <- .tmp[[3]])---", r"---(v_D <- .tmp[[4]])---"), 'test_commutator')
  expect_equal(.run(e, r"---(Commutator(.pymul(a, A), .pymul(b, B)))---"), r"---(a*b*[A,B])---")
  expect_equal(.run(e, r"---(Commutator(A, A))---"), r"---(0)---")
  expect_equal(.run(e, r"---(Commutator(a, b))---"), r"---(0)---")
  expect_equal(.run(e, r"---(Commutator(A, B))---"), r"---([A,B])---")
  expect_equal(.run(e, r"---(doit(Commutator(A, B)))---"), r"---(A*B - B*A)---")
  expect_equal(.run(e, r"---(expand(Commutator(A, .pymul(B, v_C)), commutator = TRUE))---"), r"---(B*[A,C] + [A,B]*C)---")
  expect_equal(.run(e, r"---(expand(Commutator(.pymul(A, B), .pymul(v_C, v_D)), commutator = TRUE))---"), r"---(A*C*[B,D] + A*[B,C]*D + C*[A,D]*B + [A,C]*D*B)---")
  expect_equal(.run(e, r"---(expand(Commutator(A, (B ^ S(2))), commutator = TRUE))---"), r"---(B*[A,B] + [A,B]*B)---")
  expect_equal(.run(e, r"---((.qbool(.qeq(expand(Commutator((A ^ S(2)), (v_C ^ S(2))), commutator = TRUE), sym_replace(sym_replace(expand(Commutator(.pymul(A, B), .pymul(v_C, v_D)), commutator = TRUE), B, A), v_D, v_C))) && .qbool(.qeq(sym_replace(sym_replace(expand(Commutator(.pymul(A, B), .pymul(v_C, v_D)), commutator = TRUE), B, A), v_D, v_C), (((.pymul(.pymul(A, v_C), Commutator(A, v_C)) + .pymul(.pymul(A, Commutator(A, v_C)), v_C)) + .pymul(.pymul(v_C, Commutator(A, v_C)), A)) + .pymul(.pymul(Commutator(A, v_C), v_C), A))))))---"), r"---(True)---")
  expect_equal(.run(e, r"---(expand(Commutator(A, (v_C ^ S(-2))), commutator = TRUE))---"), r"---(C^(-1)*[A,C^(-1)] + [A,C^(-1)]*C^(-1))---")
  expect_equal(.run(e, r"---(expand(Commutator((A + B), (v_C + v_D)), commutator = TRUE))---"), r"---([A,C] + [A,D] + [B,C] + [B,D])---")
  expect_equal(.run(e, r"---(expand(Commutator(A, (B + v_C)), commutator = TRUE))---"), r"---([A,B] + [A,C])---")
  expect_equal(.run(e, r"---(expand(Commutator((A ^ n), B), commutator = TRUE))---"), r"---(-[B,A^n])---")
  .do(e, r"---(e <- ((Commutator(A, Commutator(B, v_C)) + Commutator(B, Commutator(v_C, A))) + Commutator(v_C, Commutator(A, B))))---")
  expect_equal(.run(e, r"---(expand(doit(e)))---"), r"---(0)---")
})

test_that("test_commutator: test_commutator_dagger", {
  e <- .new(c(r"---(.tmp <- sym_symbols("a,b,c"))---", r"---(a <- .tmp[[1]])---", r"---(b <- .tmp[[2]])---", r"---(v_c <- .tmp[[3]])---", r"---(n <- sym_symbols("n", integer = TRUE))---", r"---(.tmp <- sym_symbols("A,B,C,D", commutative = FALSE))---", r"---(A <- .tmp[[1]])---", r"---(B <- .tmp[[2]])---", r"---(v_C <- .tmp[[3]])---", r"---(v_D <- .tmp[[4]])---"), 'test_commutator')
  .do(e, r"---(comm <- Commutator(.pymul(A, B), v_C))---")
  expect_equal(.run(e, r"---(expand(Dagger(comm), commutator = TRUE))---"), r"---(-Dagger(B)*[Dagger(A),Dagger(C)] - [Dagger(B),Dagger(C)]*Dagger(A))---")
})

test_that("test_commutator: test_eval_commutator", {
  e <- .new(c(r"---(.tmp <- sym_symbols("a,b,c"))---", r"---(a <- .tmp[[1]])---", r"---(b <- .tmp[[2]])---", r"---(v_c <- .tmp[[3]])---", r"---(n <- sym_symbols("n", integer = TRUE))---", r"---(.tmp <- sym_symbols("A,B,C,D", commutative = FALSE))---", r"---(A <- .tmp[[1]])---", r"---(B <- .tmp[[2]])---", r"---(v_C <- .tmp[[3]])---", r"---(v_D <- .tmp[[4]])---"), 'test_commutator')
  .do(e, r"---(v_F <- Foo("F"))---")
  .do(e, r"---(B <- Bar("B"))---")
  .do(e, r"---(v_T <- Tam("T"))---")
  expect_equal(.run(e, r"---(doit(Commutator(v_F, B)))---"), r"---(0)---")
  expect_equal(.run(e, r"---(doit(Commutator(B, v_F)))---"), r"---(0)---")
  expect_equal(.run(e, r"---(doit(Commutator(v_F, v_T)))---"), r"---(-1)---")
  expect_equal(.run(e, r"---(doit(Commutator(v_T, v_F)))---"), r"---(1)---")
  expect_equal(.run(e, r"---(doit(Commutator(B, v_T)))---"), r"---(B*T - T*B)---")
  expect_equal(.run(e, r"---(doit(expand(Commutator((v_F ^ S(2)), B), commutator = TRUE)))---"), r"---(0)---")
  expect_equal(.run(e, r"---(doit(expand(Commutator((v_F ^ S(2)), v_T), commutator = TRUE)))---"), r"---(-2*F)---")
  expect_equal(.run(e, r"---(doit(expand(Commutator(v_F, (v_T ^ S(2))), commutator = TRUE)))---"), r"---(-2*T)---")
  expect_equal(.run(e, r"---(doit(expand(Commutator((v_T ^ S(2)), v_F), commutator = TRUE)))---"), r"---(2*T)---")
  expect_equal(.run(e, r"---(doit(expand(Commutator((v_T ^ S(2)), (v_F ^ S(3))), commutator = TRUE)))---"), r"---(2*F*T*F + 2*F^2*T + 2*T*F^2)---")
})

test_that("test_constants: test_hbar", {
  e <- .new(character(), 'test_constants')
  expect_equal(.run(e, r"---(qattr(hbar, "is_commutative"))---"), r"---(True)---")
  expect_equal(.run(e, r"---(qattr(hbar, "is_real"))---"), r"---(True)---")
  expect_equal(.run(e, r"---(qattr(hbar, "is_positive"))---"), r"---(True)---")
  expect_equal(.run(e, r"---(qattr(hbar, "is_negative"))---"), r"---(False)---")
  expect_equal(.run(e, r"---(qattr(hbar, "is_irrational"))---"), r"---(True)---")
  expect_equal(.run(e, r"---(N(hbar))---"), r"---(1.05457162000000e-34)---")
})

test_that("test_dagger: test_scalars", {
  e <- .new(character(), 'test_dagger')
  .do(e, r"---(x <- sym_symbols("x", complex = TRUE))---")
  expect_equal(.run(e, r"---(Dagger(x))---"), r"---(conjugate(x))---")
  expect_equal(.run(e, r"---(Dagger(.pymul(sym_I, x)))---"), r"---(-I*conjugate(x))---")
  .do(e, r"---(i <- sym_symbols("i", real = TRUE))---")
  expect_equal(.run(e, r"---(Dagger(i))---"), r"---(i)---")
  .do(e, r"---(p <- sym_symbols("p"))---")
  expect_equal(.run(e, r"---(qisinstance(Dagger(p), "conjugate"))---"), r"---(True)---")
  .do(e, r"---(i <- Integer(S(3)))---")
  expect_equal(.run(e, r"---(Dagger(i))---"), r"---(3)---")
  .do(e, r"---(A <- sym_symbols("A", commutative = FALSE))---")
  expect_equal(.run(e, r"---(qattr(Dagger(A), "is_commutative"))---"), r"---(False)---")
})

