test_that("test_density: test_doit", {
  e <- .new(character(), 'test_density')
  .do(e, r"---(.tmp <- sym_symbols("x y"))---")
  .do(e, r"---(x <- .tmp[[1]])---")
  .do(e, r"---(y <- .tmp[[2]])---")
  .do(e, r"---(.tmp <- sym_symbols("A B C D E F", commutative = FALSE))---")
  .do(e, r"---(A <- .tmp[[1]])---")
  .do(e, r"---(B <- .tmp[[2]])---")
  .do(e, r"---(v_C <- .tmp[[3]])---")
  .do(e, r"---(v_D <- .tmp[[4]])---")
  .do(e, r"---(v_E <- .tmp[[5]])---")
  .do(e, r"---(v_F <- .tmp[[6]])---")
  .do(e, r"---(d <- Density(list(XKet(), 0.5), list(PxKet(), 0.5)))---")
  expect_equal(.run(e, r"---((.pymul(0.5, .pymul(PxKet(), Dagger(PxKet()))) + .pymul(0.5, .pymul(XKet(), Dagger(XKet())))))---"), r"---(0.5*|px><px| + 0.5*|x><x|)---")
  .do(e, r"---(d_with_sym <- Density(list(XKet(.pymul(x, y)), 0.5), list(PxKet(.pymul(x, y)), 0.5)))---")
  expect_equal(.run(e, r"---((.pymul(0.5, .pymul(PxKet(.pymul(x, y)), Dagger(PxKet(.pymul(x, y))))) + .pymul(0.5, .pymul(XKet(.pymul(x, y)), Dagger(XKet(.pymul(x, y)))))))---"), r"---(0.5*|x*y><x*y| + 0.5*|x*y><x*y|)---")
  .do(e, r"---(d <- Density(list(.pymul((A + B), v_C), Float(1.0))))---")
  expect_equal(.run(e, r"---(doit(d))---"), r"---(1.0*A*C*Dagger(C)*Dagger(A) + 1.0*A*C*Dagger(C)*Dagger(B) + 1.0*B*C*Dagger(C)*Dagger(A) + 1.0*B*C*Dagger(C)*Dagger(B))---")
  .do(e, r"---(v_t <- TensorProduct(A, B, v_C))---")
  .do(e, r"---(d <- Density(list(v_t, Float(1.0))))---")
  expect_equal(.run(e, r"---(doit(d))---"), r"---(1.0*(A*Dagger(A))x(B*Dagger(B))x(C*Dagger(C)))---")
  .do(e, r"---(t2 <- TensorProduct(A, B))---")
  .do(e, r"---(t3 <- TensorProduct(v_C, v_D))---")
  .do(e, r"---(d <- Density(list(t2, 0.5), list(t3, 0.5)))---")
  expect_equal(.run(e, r"---(doit(d))---"), r"---(0.5*(A*Dagger(A))x(B*Dagger(B)) + 0.5*(C*Dagger(C))x(D*Dagger(D)))---")
  .do(e, r"---(d <- Density(list((t2 + t3), Float(1.0))))---")
  expect_equal(.run(e, r"---(doit(d))---"), r"---(1.0*(A*Dagger(A))x(B*Dagger(B)) + 1.0*(A*Dagger(C))x(B*Dagger(D)) + 1.0*(C*Dagger(A))x(D*Dagger(B)) + 1.0*(C*Dagger(C))x(D*Dagger(D)))---")
  .do(e, r"---(tp1 <- TensorProduct(JzKet(S(1), S(1)), JzKet(S(1), S(-1))))---")
  .do(e, r"---(d <- Density(list(tp1, S(1))))---")
  .do(e, r"---(v_t <- Tr(d))---")
  expect_equal(.run(e, r"---(doit(v_t))---"), r"---(1)---")
  .do(e, r"---(v_t <- Tr(d, list(S(0))))---")
  expect_equal(.run(e, r"---(doit(v_t))---"), r"---(|1,-1><1,-1|)---")
  .do(e, r"---(v_t <- Tr(d, list(S(1))))---")
  expect_equal(.run(e, r"---(doit(v_t))---"), r"---(|1,1><1,1|)---")
  .do(e, r"---(tp2 <- TensorProduct(JzKet(S_Half, S_Half), JzKet(S_Half, Rational(S(-1), S(2)))))---")
  .do(e, r"---(d <- Density(list(tp2, S(1))))---")
  .do(e, r"---(v_t <- Tr(d))---")
  expect_equal(.run(e, r"---(doit(v_t))---"), r"---(1)---")
  .do(e, r"---(v_t <- Tr(d, list(S(0))))---")
  expect_equal(.run(e, r"---(doit(v_t))---"), r"---(|1/2,-1/2><1/2,-1/2|)---")
  .do(e, r"---(v_t <- Tr(d, list(S(1))))---")
  expect_equal(.run(e, r"---(doit(v_t))---"), r"---(|1/2,1/2><1/2,1/2|)---")
})

