test_that("test_density: test_represent", {
  e <- .new(character(), 'test_density')
  .do(e, r"---(.tmp <- sym_symbols("x y"))---")
  .do(e, r"---(x <- .tmp[[1]])---")
  .do(e, r"---(y <- .tmp[[2]])---")
  .do(e, r"---(d <- Density(list(XKet(), 0.5), list(PxKet(), 0.5)))---")
  expect_equal(.run(e, r"---((represent(.pymul(0.5, .pymul(PxKet(), Dagger(PxKet())))) + represent(.pymul(0.5, .pymul(XKet(), Dagger(XKet()))))))---"), r"---(0.5*DiracDelta(-px + px_2)*DiracDelta(px - px_3) + 0.5*DiracDelta(-x + x_2)*DiracDelta(x - x_3))---")
  .do(e, r"---(d_with_sym <- Density(list(XKet(.pymul(x, y)), 0.5), list(PxKet(.pymul(x, y)), 0.5)))---")
  expect_equal(.run(e, r"---((represent(.pymul(0.5, .pymul(PxKet(.pymul(x, y)), Dagger(PxKet(.pymul(x, y)))))) + represent(.pymul(0.5, .pymul(XKet(.pymul(x, y)), Dagger(XKet(.pymul(x, y))))))))---"), r"---(0.5*DiracDelta(px_2 - x*y)*DiracDelta(-px_3 + x*y) + 0.5*DiracDelta(-x*y + x_2)*DiracDelta(x*y - x_3))---")
  expect_equal(.run(e, r"---((represent(.pymul(0.5, .pymul(XKet(), Dagger(XKet()))), basis = PxOp()) + represent(.pymul(0.5, .pymul(PxKet(), Dagger(PxKet()))), basis = PxOp())))---"), r"---(Piecewise((0, (Abs(arg(x) - pi/2) < pi/2) & (Abs(arg(x) + pi/2) < pi/2)), (Integral(0.25*exp(I*px_2*x/hbar)*exp(-I*px_3*x/hbar)/(hbar*pi), (px_2, -oo, oo)), True)) + DiracDelta(px - px_3)/2)---")
})

