test_that("test_gate: test_one_qubit_anticommutators", {
  e <- .new(character(), 'test_gate')
  .do(e, r"---(g1 <- "IdentityGate")---")
  .do(e, r"---(g2 <- "IdentityGate")---")
  .do(e, r"---(e <- AntiCommutator(.qcallobj(g1, 0), .qcallobj(g2, 0)))---")
  .do(e, r"---(a <- matrix_to_zero(represent(e, nqubits = S(1), format = "sympy")))---")
  .do(e, r"---(b <- matrix_to_zero(represent(doit(e), nqubits = S(1), format = "sympy")))---")
  expect_equal(.run(e, r"---(a)---"), r"---(Matrix([[2, 0], [0, 2]]))---")
  .do(e, r"---(e <- AntiCommutator(.qcallobj(g1, 0), .qcallobj(g2, 1)))---")
  .do(e, r"---(a <- matrix_to_zero(represent(e, nqubits = S(2), format = "sympy")))---")
  .do(e, r"---(b <- matrix_to_zero(represent(doit(e), nqubits = S(2), format = "sympy")))---")
  expect_equal(.run(e, r"---(a)---"), r"---(Matrix([[2, 0, 0, 0], [0, 2, 0, 0], [0, 0, 2, 0], [0, 0, 0, 2]]))---")
  e <- .new(character(), 'test_gate')
  .do(e, r"---(g1 <- "IdentityGate")---")
  .do(e, r"---(g2 <- "XGate")---")
  .do(e, r"---(e <- AntiCommutator(.qcallobj(g1, 0), .qcallobj(g2, 0)))---")
  .do(e, r"---(a <- matrix_to_zero(represent(e, nqubits = S(1), format = "sympy")))---")
  .do(e, r"---(b <- matrix_to_zero(represent(doit(e), nqubits = S(1), format = "sympy")))---")
  expect_equal(.run(e, r"---(a)---"), r"---(Matrix([[0, 2], [2, 0]]))---")
  .do(e, r"---(e <- AntiCommutator(.qcallobj(g1, 0), .qcallobj(g2, 1)))---")
  .do(e, r"---(a <- matrix_to_zero(represent(e, nqubits = S(2), format = "sympy")))---")
  .do(e, r"---(b <- matrix_to_zero(represent(doit(e), nqubits = S(2), format = "sympy")))---")
  expect_equal(.run(e, r"---(a)---"), r"---(Matrix([[0, 0, 2, 0], [0, 0, 0, 2], [2, 0, 0, 0], [0, 2, 0, 0]]))---")
  e <- .new(character(), 'test_gate')
  .do(e, r"---(g1 <- "IdentityGate")---")
  .do(e, r"---(g2 <- "YGate")---")
  .do(e, r"---(e <- AntiCommutator(.qcallobj(g1, 0), .qcallobj(g2, 0)))---")
  .do(e, r"---(a <- matrix_to_zero(represent(e, nqubits = S(1), format = "sympy")))---")
  .do(e, r"---(b <- matrix_to_zero(represent(doit(e), nqubits = S(1), format = "sympy")))---")
  expect_equal(.run(e, r"---(a)---"), r"---(Matrix([[0, -2*I], [2*I, 0]]))---")
  .do(e, r"---(e <- AntiCommutator(.qcallobj(g1, 0), .qcallobj(g2, 1)))---")
  .do(e, r"---(a <- matrix_to_zero(represent(e, nqubits = S(2), format = "sympy")))---")
  .do(e, r"---(b <- matrix_to_zero(represent(doit(e), nqubits = S(2), format = "sympy")))---")
  expect_equal(.run(e, r"---(a)---"), r"---(Matrix([[0, 0, -2*I, 0], [0, 0, 0, -2*I], [2*I, 0, 0, 0], [0, 2*I, 0, 0]]))---")
  e <- .new(character(), 'test_gate')
  .do(e, r"---(g1 <- "IdentityGate")---")
  .do(e, r"---(g2 <- "ZGate")---")
  .do(e, r"---(e <- AntiCommutator(.qcallobj(g1, 0), .qcallobj(g2, 0)))---")
  .do(e, r"---(a <- matrix_to_zero(represent(e, nqubits = S(1), format = "sympy")))---")
  .do(e, r"---(b <- matrix_to_zero(represent(doit(e), nqubits = S(1), format = "sympy")))---")
  expect_equal(.run(e, r"---(a)---"), r"---(Matrix([[2, 0], [0, -2]]))---")
  .do(e, r"---(e <- AntiCommutator(.qcallobj(g1, 0), .qcallobj(g2, 1)))---")
  .do(e, r"---(a <- matrix_to_zero(represent(e, nqubits = S(2), format = "sympy")))---")
  .do(e, r"---(b <- matrix_to_zero(represent(doit(e), nqubits = S(2), format = "sympy")))---")
  expect_equal(.run(e, r"---(a)---"), r"---(Matrix([[2, 0, 0, 0], [0, 2, 0, 0], [0, 0, -2, 0], [0, 0, 0, -2]]))---")
  e <- .new(character(), 'test_gate')
  .do(e, r"---(g1 <- "IdentityGate")---")
  .do(e, r"---(g2 <- "HadamardGate")---")
  .do(e, r"---(e <- AntiCommutator(.qcallobj(g1, 0), .qcallobj(g2, 0)))---")
  .do(e, r"---(a <- matrix_to_zero(represent(e, nqubits = S(1), format = "sympy")))---")
  .do(e, r"---(b <- matrix_to_zero(represent(doit(e), nqubits = S(1), format = "sympy")))---")
  expect_equal(.run(e, r"---(a)---"), r"---(Matrix([[sqrt(2), sqrt(2)], [sqrt(2), -sqrt(2)]]))---")
  .do(e, r"---(e <- AntiCommutator(.qcallobj(g1, 0), .qcallobj(g2, 1)))---")
  .do(e, r"---(a <- matrix_to_zero(represent(e, nqubits = S(2), format = "sympy")))---")
  .do(e, r"---(b <- matrix_to_zero(represent(doit(e), nqubits = S(2), format = "sympy")))---")
  expect_equal(.run(e, r"---(a)---"), r"---(Matrix([[sqrt(2), 0, sqrt(2), 0], [0, sqrt(2), 0, sqrt(2)], [sqrt(2), 0, -sqrt(2), 0], [0, sqrt(2), 0, -sqrt(2)]]))---")
  e <- .new(character(), 'test_gate')
  .do(e, r"---(g1 <- "XGate")---")
  .do(e, r"---(g2 <- "IdentityGate")---")
  .do(e, r"---(e <- AntiCommutator(.qcallobj(g1, 0), .qcallobj(g2, 0)))---")
  .do(e, r"---(a <- matrix_to_zero(represent(e, nqubits = S(1), format = "sympy")))---")
  .do(e, r"---(b <- matrix_to_zero(represent(doit(e), nqubits = S(1), format = "sympy")))---")
  expect_equal(.run(e, r"---(a)---"), r"---(Matrix([[0, 2], [2, 0]]))---")
  .do(e, r"---(e <- AntiCommutator(.qcallobj(g1, 0), .qcallobj(g2, 1)))---")
  .do(e, r"---(a <- matrix_to_zero(represent(e, nqubits = S(2), format = "sympy")))---")
  .do(e, r"---(b <- matrix_to_zero(represent(doit(e), nqubits = S(2), format = "sympy")))---")
  expect_equal(.run(e, r"---(a)---"), r"---(Matrix([[0, 2, 0, 0], [2, 0, 0, 0], [0, 0, 0, 2], [0, 0, 2, 0]]))---")
  e <- .new(character(), 'test_gate')
  .do(e, r"---(g1 <- "XGate")---")
  .do(e, r"---(g2 <- "XGate")---")
  .do(e, r"---(e <- AntiCommutator(.qcallobj(g1, 0), .qcallobj(g2, 0)))---")
  .do(e, r"---(a <- matrix_to_zero(represent(e, nqubits = S(1), format = "sympy")))---")
  .do(e, r"---(b <- matrix_to_zero(represent(doit(e), nqubits = S(1), format = "sympy")))---")
  expect_equal(.run(e, r"---(a)---"), r"---(2)---")
  .do(e, r"---(e <- AntiCommutator(.qcallobj(g1, 0), .qcallobj(g2, 1)))---")
  .do(e, r"---(a <- matrix_to_zero(represent(e, nqubits = S(2), format = "sympy")))---")
  .do(e, r"---(b <- matrix_to_zero(represent(doit(e), nqubits = S(2), format = "sympy")))---")
  expect_equal(.run(e, r"---(a)---"), r"---(Matrix([[0, 0, 0, 2], [0, 0, 2, 0], [0, 2, 0, 0], [2, 0, 0, 0]]))---")
  e <- .new(character(), 'test_gate')
  .do(e, r"---(g1 <- "XGate")---")
  .do(e, r"---(g2 <- "YGate")---")
  .do(e, r"---(e <- AntiCommutator(.qcallobj(g1, 0), .qcallobj(g2, 0)))---")
  .do(e, r"---(a <- matrix_to_zero(represent(e, nqubits = S(1), format = "sympy")))---")
  .do(e, r"---(b <- matrix_to_zero(represent(doit(e), nqubits = S(1), format = "sympy")))---")
  expect_equal(.run(e, r"---(a)---"), r"---(0)---")
  .do(e, r"---(e <- AntiCommutator(.qcallobj(g1, 0), .qcallobj(g2, 1)))---")
  .do(e, r"---(a <- matrix_to_zero(represent(e, nqubits = S(2), format = "sympy")))---")
  .do(e, r"---(b <- matrix_to_zero(represent(doit(e), nqubits = S(2), format = "sympy")))---")
  expect_equal(.run(e, r"---(a)---"), r"---(Matrix([[0, 0, 0, -2*I], [0, 0, -2*I, 0], [0, 2*I, 0, 0], [2*I, 0, 0, 0]]))---")
  e <- .new(character(), 'test_gate')
  .do(e, r"---(g1 <- "XGate")---")
  .do(e, r"---(g2 <- "ZGate")---")
  .do(e, r"---(e <- AntiCommutator(.qcallobj(g1, 0), .qcallobj(g2, 0)))---")
  .do(e, r"---(a <- matrix_to_zero(represent(e, nqubits = S(1), format = "sympy")))---")
  .do(e, r"---(b <- matrix_to_zero(represent(doit(e), nqubits = S(1), format = "sympy")))---")
  expect_equal(.run(e, r"---(a)---"), r"---(0)---")
  .do(e, r"---(e <- AntiCommutator(.qcallobj(g1, 0), .qcallobj(g2, 1)))---")
  .do(e, r"---(a <- matrix_to_zero(represent(e, nqubits = S(2), format = "sympy")))---")
  .do(e, r"---(b <- matrix_to_zero(represent(doit(e), nqubits = S(2), format = "sympy")))---")
  expect_equal(.run(e, r"---(a)---"), r"---(Matrix([[0, 2, 0, 0], [2, 0, 0, 0], [0, 0, 0, -2], [0, 0, -2, 0]]))---")
  e <- .new(character(), 'test_gate')
  .do(e, r"---(g1 <- "XGate")---")
  .do(e, r"---(g2 <- "HadamardGate")---")
  .do(e, r"---(e <- AntiCommutator(.qcallobj(g1, 0), .qcallobj(g2, 0)))---")
  .do(e, r"---(a <- matrix_to_zero(represent(e, nqubits = S(1), format = "sympy")))---")
  .do(e, r"---(b <- matrix_to_zero(represent(doit(e), nqubits = S(1), format = "sympy")))---")
  expect_equal(.run(e, r"---(a)---"), r"---(Matrix([[sqrt(2), 0], [0, sqrt(2)]]))---")
  .do(e, r"---(e <- AntiCommutator(.qcallobj(g1, 0), .qcallobj(g2, 1)))---")
  .do(e, r"---(a <- matrix_to_zero(represent(e, nqubits = S(2), format = "sympy")))---")
  .do(e, r"---(b <- matrix_to_zero(represent(doit(e), nqubits = S(2), format = "sympy")))---")
  expect_equal(.run(e, r"---(a)---"), r"---(Matrix([[0, sqrt(2), 0, sqrt(2)], [sqrt(2), 0, sqrt(2), 0], [0, sqrt(2), 0, -sqrt(2)], [sqrt(2), 0, -sqrt(2), 0]]))---")
  e <- .new(character(), 'test_gate')
  .do(e, r"---(g1 <- "YGate")---")
  .do(e, r"---(g2 <- "IdentityGate")---")
  .do(e, r"---(e <- AntiCommutator(.qcallobj(g1, 0), .qcallobj(g2, 0)))---")
  .do(e, r"---(a <- matrix_to_zero(represent(e, nqubits = S(1), format = "sympy")))---")
