test_that("test_gate: test_cnot_commutators", {
  e <- .new(character(), 'test_gate')
  expect_equal(.run(e, r"---(doit(Commutator(CNotGate(S(0), S(1)), ZGate(S(0)))))---"), r"---(0)---")
  expect_equal(.run(e, r"---(doit(Commutator(CNotGate(S(0), S(1)), TGate(S(0)))))---"), r"---(0)---")
  expect_equal(.run(e, r"---(doit(Commutator(CNotGate(S(0), S(1)), PhaseGate(S(0)))))---"), r"---(0)---")
  expect_equal(.run(e, r"---(doit(Commutator(CNotGate(S(0), S(1)), XGate(S(1)))))---"), r"---(0)---")
  expect_equal(.run(e, r"---(doit(Commutator(CNotGate(S(0), S(1)), CNotGate(S(0), S(1)))))---"), r"---(0)---")
  expect_equal(.run(e, r"---(doit(Commutator(CNotGate(S(0), S(1)), CNotGate(S(0), S(2)))))---"), r"---(0)---")
  expect_equal(.run(e, r"---(doit(Commutator(CNotGate(S(0), S(2)), CNotGate(S(0), S(1)))))---"), r"---(0)---")
  expect_equal(.run(e, r"---(doit(Commutator(CNotGate(S(1), S(2)), CNotGate(S(1), S(0)))))---"), r"---(0)---")
})

test_that("test_gate: test_random_circuit", {
  e <- .new(character(), 'test_gate')
  .do(e, r"---(v_c <- random_circuit(S(10), S(3)))---")
  expect_equal(.run(e, r"---(qisinstance(v_c, "Mul"))---"), r"---(True)---")
  .do(e, r"---(m <- represent(v_c, nqubits = S(3)))---")
  expect_equal(.run(e, r"---(sym_shape(m))---"), r"---([8, 8])---")
  expect_equal(.run(e, r"---(qisinstance(m, "MutableDenseMatrix"))---"), r"---(True)---")
})

test_that("test_gate: test_hermitian_XGate", {
  e <- .new(character(), 'test_gate')
  .do(e, r"---(x <- XGate(S(1), S(2)))---")
  .do(e, r"---(x_dagger <- Dagger(x))---")
  expect_equal(.run(e, r"---(x)---"), r"---(X(1,2))---")
})

