test_that("test_grover: test_grover_iteration_2", {
  e <- .new(character(), 'test_grover')
  .do(e, r"---(numqubits <- S(4))---")
  .do(e, r"---(basis_states <- superposition_basis(numqubits))---")
  .do(e, r"---(v <- OracleGate(numqubits, return_one_on_two))---")
  .do(e, r"---(iterated <- grover_iteration(basis_states, v))---")
  .do(e, r"---(iterated <- qapply(iterated))---")
  .do(e, r"---(iterated <- grover_iteration(iterated, v))---")
  .do(e, r"---(iterated <- qapply(iterated))---")
  .do(e, r"---(iterated <- grover_iteration(iterated, v))---")
  .do(e, r"---(iterated <- qapply(iterated))---")
  .do(e, r"---(expected <- ((.pymul(S(-13), basis_states) / S(64)) + (.pymul(S(264), IntQubit(S(2), numqubits)) / S(256))))---")
  expect_equal(.run(e, r"---(qapply(expected))---"), r"---(-13*|0>/256 - 13*|1>/256 + 251*|2>/256 - 13*|3>/256 - 13*|4>/256 - 13*|5>/256 - 13*|6>/256 - 13*|7>/256 - 13*|8>/256 - 13*|9>/256 - 13*|10>/256 - 13*|11>/256 - 13*|12>/256 - 13*|13>/256 - 13*|14>/256 - 13*|15>/256)---")
})

