  expect_equal(.run(e, r"---(qisinstance(hs, "HilbertSpace"))---"), r"---(True)---")
  expect_equal(.run(e, r"---(sstr(hs))---"), r"---(H)---")
  expect_equal(.run(e, r"---(srepr(hs))---"), r"---(HilbertSpace())---")
})

test_that("test_hilbert: test_complex_space", {
  e <- .new(character(), 'test_hilbert')
  .do(e, r"---(c1 <- ComplexSpace(S(2)))---")
  expect_equal(.run(e, r"---(qisinstance(c1, "ComplexSpace"))---"), r"---(True)---")
  expect_equal(.run(e, r"---(qattr(c1, "dimension"))---"), r"---(2)---")
  expect_equal(.run(e, r"---(sstr(c1))---"), r"---(C(2))---")
  expect_equal(.run(e, r"---(srepr(c1))---"), r"---(ComplexSpace(Integer(2)))---")
  .do(e, r"---(n <- Symbol("n"))---")
  .do(e, r"---(c2 <- ComplexSpace(n))---")
  expect_equal(.run(e, r"---(qisinstance(c2, "ComplexSpace"))---"), r"---(True)---")
  expect_equal(.run(e, r"---(qattr(c2, "dimension"))---"), r"---(n)---")
  expect_equal(.run(e, r"---(sstr(c2))---"), r"---(C(n))---")
  expect_equal(.run(e, r"---(srepr(c2))---"), r"---(ComplexSpace(Symbol('n')))---")
  expect_equal(.run(e, r"---(subs(c2, n, S(2)))---"), r"---(C(2))---")
})

test_that("test_hilbert: test_L2", {
  e <- .new(character(), 'test_hilbert')
  .do(e, r"---(b1 <- L2(Interval((-oo), S(1))))---")
  expect_equal(.run(e, r"---(qisinstance(b1, "L2"))---"), r"---(True)---")
  expect_equal(.run(e, r"---(qattr(b1, "dimension"))---"), r"---(oo)---")
  expect_equal(.run(e, r"---(qattr(b1, "interval"))---"), r"---(Interval(-oo, 1))---")
  .do(e, r"---(x <- Symbol("x", real = TRUE))---")
  .do(e, r"---(y <- Symbol("y", real = TRUE))---")
  .do(e, r"---(b2 <- L2(Interval(x, y)))---")
  expect_equal(.run(e, r"---(qattr(b2, "dimension"))---"), r"---(oo)---")
  expect_equal(.run(e, r"---(qattr(b2, "interval"))---"), r"---(Interval(x, y))---")
  expect_equal(.run(e, r"---(subs(b2, x, S(-1)))---"), r"---(L2(Interval(-1, y)))---")
})

test_that("test_hilbert: test_fock_space", {
  e <- .new(character(), 'test_hilbert')
  .do(e, r"---(f1 <- FockSpace())---")
