test_that("test_hilbert: test_tensor_product", {
  e <- .new(character(), 'test_hilbert')
  .do(e, r"---(n <- Symbol("n"))---")
  .do(e, r"---(hs1 <- ComplexSpace(S(2)))---")
  .do(e, r"---(hs2 <- ComplexSpace(n))---")
  .do(e, r"---(h <- .pymul(hs1, hs2))---")
  expect_equal(.run(e, r"---(qisinstance(h, "TensorProductHilbertSpace"))---"), r"---(True)---")
  expect_equal(.run(e, r"---(qattr(h, "dimension"))---"), r"---(2*n)---")
  expect_equal(.run(e, r"---(qattr(h, "spaces"))---"), r"---([C(2), C(n)])---")
  .do(e, r"---(h <- .pymul(hs2, hs2))---")
  expect_equal(.run(e, r"---(qisinstance(h, "TensorPowerHilbertSpace"))---"), r"---(True)---")
  expect_equal(.run(e, r"---(qattr(h, "base"))---"), r"---(C(n))---")
  expect_equal(.run(e, r"---(qattr(h, "exp"))---"), r"---(2)---")
  expect_equal(.run(e, r"---(qattr(h, "dimension"))---"), r"---(n^2)---")
  .do(e, r"---(f <- FockSpace())---")
  .do(e, r"---(h <- .pymul(.pymul(hs1, hs2), f))---")
  expect_equal(.run(e, r"---(qattr(h, "dimension"))---"), r"---(oo)---")
})

test_that("test_hilbert: test_tensor_power", {
  e <- .new(character(), 'test_hilbert')
  .do(e, r"---(n <- Symbol("n"))---")
  .do(e, r"---(hs1 <- ComplexSpace(S(2)))---")
  .do(e, r"---(hs2 <- ComplexSpace(n))---")
  .do(e, r"---(h <- (hs1 ^ S(2)))---")
  expect_equal(.run(e, r"---(qisinstance(h, "TensorPowerHilbertSpace"))---"), r"---(True)---")
  expect_equal(.run(e, r"---(qattr(h, "base"))---"), r"---(C(2))---")
  expect_equal(.run(e, r"---(qattr(h, "exp"))---"), r"---(2)---")
  expect_equal(.run(e, r"---(qattr(h, "dimension"))---"), r"---(4)---")
  .do(e, r"---(h <- (hs2 ^ S(3)))---")
  expect_equal(.run(e, r"---(qisinstance(h, "TensorPowerHilbertSpace"))---"), r"---(True)---")
  expect_equal(.run(e, r"---(qattr(h, "base"))---"), r"---(C(n))---")
  expect_equal(.run(e, r"---(qattr(h, "exp"))---"), r"---(3)---")
  expect_equal(.run(e, r"---(qattr(h, "dimension"))---"), r"---(n^3)---")
})

test_that("test_hilbert: test_direct_sum", {
  e <- .new(character(), 'test_hilbert')
  .do(e, r"---(n <- Symbol("n"))---")
  .do(e, r"---(hs1 <- ComplexSpace(S(2)))---")
  .do(e, r"---(hs2 <- ComplexSpace(n))---")
  .do(e, r"---(h <- (hs1 + hs2))---")
  expect_equal(.run(e, r"---(qisinstance(h, "DirectSumHilbertSpace"))---"), r"---(True)---")
  expect_equal(.run(e, r"---(qattr(h, "dimension"))---"), r"---(n + 2)---")
  expect_equal(.run(e, r"---(qattr(h, "spaces"))---"), r"---([C(2), C(n)])---")
  .do(e, r"---(f <- FockSpace())---")
  .do(e, r"---(h <- ((hs1 + f) + hs2))---")
  expect_equal(.run(e, r"---(qattr(h, "dimension"))---"), r"---(oo)---")
  expect_equal(.run(e, r"---(qattr(h, "spaces"))---"), r"---([C(2), F, C(n)])---")
})

test_that("test_identitysearch: test_generate_gate_rules_1", {
  e <- .new(character(), 'test_identitysearch')
  .do(e, r"---(.tmp <- create_gate_sequence())---")
