  .do(e, r"---(y <- .tmp[[2]])---")
  .do(e, r"---(z <- .tmp[[3]])---")
  .do(e, r"---(h <- .tmp[[4]])---")
  .do(e, r"---(ph <- PhaseGate(S(0)))---")
  .do(e, r"---(cgate_t <- CGate(S(0), TGate(S(1))))---")
  expect_equal(.run(e, r"---(generate_gate_rules(list(x)))---"), r"---({[[X(0)], []]})---")
