  expect_equal(.run(e, r"---(generate_gate_rules(list(x, x)))---"), r"---({[[X(0), X(0)], []], [[X(0)], [X(0)]]})---")
  .do(e, r"---(gate_rules <- .qset(list(list(list(x, y, x), list()), list(list(y, x, x), list()), list(list(x, x, y), list()), list(list(y, x), list(x)), list(list(x, y), list(x)), list(list(y), list(x, x)))))---")
  expect_equal(.run(e, r"---(generate_gate_rules(list(x, y, x)))---"), r"---({[[X(0), X(0), Y(0)], []], [[X(0), Y(0), X(0)], []], [[X(0), Y(0)], [X(0)]], [[Y(0), X(0), X(0)], []], [[Y(0), X(0)], [X(0)]], [[Y(0)], [X(0), X(0)]]})---")
  .do(e, r"---(gate_rules <- .qset(list(list(list(x, y, z), list()), list(list(y, z, x), list()), list(list(z, x, y), list()), list(list(), list(x, z, y)), list(list(), list(y, x, z)), list(list(), list(z, y, x)), list(list(x), list(z, y)), list(list(y, z), list(x)), list(list(y), list(x, z)), list(list(z, x), list(y)), list(list(z), list(y, x)), list(list(x, y), list(z)))))---")
  .do(e, r"---(actual <- generate_gate_rules(list(x, y, z)))---")
  expect_equal(.run(e, r"---(actual)---"), r"---({[[X(0), Y(0), Z(0)], []], [[X(0), Y(0)], [Z(0)]], [[X(0)], [Z(0), Y(0)]], [[Y(0), Z(0), X(0)], []], [[Y(0), Z(0)], [X(0)]], [[Y(0)], [X(0), Z(0)]], [[Z(0), X(0), Y(0)], []], [[Z(0), X(0)], [Y(0)]], [[Z(0)], [Y(0), X(0)]], [[], [X(0), Z(0), Y(0)]], [[], [Y(0), X(0), Z(0)]], [[], [Z(0), Y(0), X(0)]]})---")
  .do(e, r"---(gate_rules <- .qset(list(list(list(), list(h, z, y, x)), list(list(), list(x, h, z, y)), list(list(), list(y, x, h, z)), list(list(), list(z, y, x, h)), list(list(h), list(z, y, x)), list(list(x), list(h, z, y)), list(list(y), list(x, h, z)), list(list(z), list(y, x, h)), list(list(h, x), list(z, y)), list(list(x, y), list(h, z)), list(list(y, z), list(x, h)), list(list(z, h), list(y, x)), list(list(h, x, y), list(z)), list(list(x, y, z), list(h)), list(list(y, z, h), list(x)), list(list(z, h, x), list(y)), list(list(h, x, y, z), list()), list(list(x, y, z, h), list()), list(list(y, z, h, x), list()), list(list(z, h, x, y), list()))))---")
  .do(e, r"---(actual <- generate_gate_rules(list(x, y, z, h)))---")
  expect_equal(.run(e, r"---(actual)---"), r"---({[[H(0), X(0), Y(0), Z(0)], []], [[H(0), X(0), Y(0)], [Z(0)]], [[H(0), X(0)], [Z(0), Y(0)]], [[H(0)], [Z(0), Y(0), X(0)]], [[X(0), Y(0), Z(0), H(0)], []], [[X(0), Y(0), Z(0)], [H(0)]], [[X(0), Y(0)], [H(0), Z(0)]], [[X(0)], [H(0), Z(0), Y(0)]], [[Y(0), Z(0), H(0), X(0)], []], [[Y(0), Z(0), H(0)], [X(0)]], [[Y(0), Z(0)], [X(0), H(0)]], [[Y(0)], [X(0), H(0), Z(0)]], [[Z(0), H(0), X(0), Y(0)], []], [[Z(0), H(0), X(0)], [Y(0)]], [[Z(0), H(0)], [Y(0), X(0)]], [[Z(0)], [Y(0), X(0), H(0)]], [[], [H(0), Z(0), Y(0), X(0)]], [[], [X(0), H(0), Z(0), Y(0)]], [[], [Y(0), X(0), H(0), Z(0)]], [[], [Z(0), Y(0), X(0), H(0)]]})---")
  .do(e, r"---(gate_rules <- .qset(list(list(list(), list((cgate_t ^ S(-1)), (ph ^ S(-1)), x)), list(list(), list((ph ^ S(-1)), x, (cgate_t ^ S(-1)))), list(list(), list(x, (cgate_t ^ S(-1)), (ph ^ S(-1)))), list(list(cgate_t), list((ph ^ S(-1)), x)), list(list(ph), list(x, (cgate_t ^ S(-1)))), list(list(x), list((cgate_t ^ S(-1)), (ph ^ S(-1)))), list(list(cgate_t, x), list((ph ^ S(-1)))), list(list(ph, cgate_t), list(x)), list(list(x, ph), list((cgate_t ^ S(-1)))), list(list(cgate_t, x, ph), list()), list(list(ph, cgate_t, x), list()), list(list(x, ph, cgate_t), list()))))---")
  .do(e, r"---(actual <- generate_gate_rules(list(x, ph, cgate_t)))---")
  expect_equal(.run(e, r"---(actual)---"), r"---({[[C((0),T(1)), X(0), S(0)], []], [[C((0),T(1)), X(0)], [S(0)^(-1)]], [[C((0),T(1))], [S(0)^(-1), X(0)]], [[S(0), C((0),T(1)), X(0)], []], [[S(0), C((0),T(1))], [X(0)]], [[S(0)], [X(0), C((0),T(1))^(-1)]], [[X(0), S(0), C((0),T(1))], []], [[X(0), S(0)], [C((0),T(1))^(-1)]], [[X(0)], [C((0),T(1))^(-1), S(0)^(-1)]], [[], [C((0),T(1))^(-1), S(0)^(-1), X(0)]], [[], [S(0)^(-1), X(0), C((0),T(1))^(-1)]], [[], [X(0), C((0),T(1))^(-1), S(0)^(-1)]]})---")
  .do(e, r"---(gate_rules <- .qset(list(list(Integer(S(1)), .pymul(.pymul((cgate_t ^ S(-1)), (ph ^ S(-1))), x)), list(Integer(S(1)), .pymul(.pymul((ph ^ S(-1)), x), (cgate_t ^ S(-1)))), list(Integer(S(1)), .pymul(.pymul(x, (cgate_t ^ S(-1))), (ph ^ S(-1)))), list(cgate_t, .pymul((ph ^ S(-1)), x)), list(ph, .pymul(x, (cgate_t ^ S(-1)))), list(x, .pymul((cgate_t ^ S(-1)), (ph ^ S(-1)))), list(.pymul(cgate_t, x), (ph ^ S(-1))), list(.pymul(ph, cgate_t), x), list(.pymul(x, ph), (cgate_t ^ S(-1))), list(.pymul(.pymul(cgate_t, x), ph), Integer(S(1))), list(.pymul(.pymul(ph, cgate_t), x), Integer(S(1))), list(.pymul(.pymul(x, ph), cgate_t), Integer(S(1))))))---")
  .do(e, r"---(actual <- generate_gate_rules(list(x, ph, cgate_t), return_as_muls = TRUE))---")
  expect_equal(.run(e, r"---(actual)---"), r"---({[1, C((0),T(1))^(-1)*S(0)^(-1)*X(0)], [1, S(0)^(-1)*X(0)*C((0),T(1))^(-1)], [1, X(0)*C((0),T(1))^(-1)*S(0)^(-1)], [C((0),T(1))*X(0)*S(0), 1], [C((0),T(1))*X(0), S(0)^(-1)], [C((0),T(1)), S(0)^(-1)*X(0)], [S(0)*C((0),T(1))*X(0), 1], [S(0)*C((0),T(1)), X(0)], [S(0), X(0)*C((0),T(1))^(-1)], [X(0)*S(0)*C((0),T(1)), 1], [X(0)*S(0), C((0),T(1))^(-1)], [X(0), C((0),T(1))^(-1)*S(0)^(-1)]})---")
})

test_that("test_identitysearch: test_generate_gate_rules_2", {
  e <- .new(character(), 'test_identitysearch')
  .do(e, r"---(.tmp <- create_gate_sequence())---")
  .do(e, r"---(x <- .tmp[[1]])---")
  .do(e, r"---(y <- .tmp[[2]])---")
  .do(e, r"---(z <- .tmp[[3]])---")
  .do(e, r"---(h <- .tmp[[4]])---")
  .do(e, r"---(ph <- PhaseGate(S(0)))---")
  .do(e, r"---(cgate_t <- CGate(S(0), TGate(S(1))))---")
  .do(e, r"---(expected <- .qset(list(list(x, Integer(S(1))))))---")
  expect_equal(.run(e, r"---(generate_gate_rules(list(x), return_as_muls = TRUE))---"), r"---({[X(0), 1]})---")
  .do(e, r"---(expected <- .qset(list(list(Integer(S(1)), Integer(S(1))))))---")
  expect_equal(.run(e, r"---(generate_gate_rules(.pymul(x, x), return_as_muls = TRUE))---"), r"---({[1, 1]})---")
  .do(e, r"---(expected <- .qset(list(list(list(), list()))))---")
