  .do(e, r"---(actual <- generate_gate_rules(.pymul(.pymul(.pymul(x, y), z), h), return_as_muls = TRUE))---")
  expect_equal(.run(e, r"---(actual)---"), r"---({[1, H(0)*Z(0)*Y(0)*X(0)], [1, X(0)*H(0)*Z(0)*Y(0)], [1, Y(0)*X(0)*H(0)*Z(0)], [1, Z(0)*Y(0)*X(0)*H(0)], [H(0)*X(0)*Y(0)*Z(0), 1], [H(0)*X(0)*Y(0), Z(0)], [H(0)*X(0), Z(0)*Y(0)], [H(0), Z(0)*Y(0)*X(0)], [X(0)*Y(0)*Z(0)*H(0), 1], [X(0)*Y(0)*Z(0), H(0)], [X(0)*Y(0), H(0)*Z(0)], [X(0), H(0)*Z(0)*Y(0)], [Y(0)*Z(0)*H(0)*X(0), 1], [Y(0)*Z(0)*H(0), X(0)], [Y(0)*Z(0), X(0)*H(0)], [Y(0), X(0)*H(0)*Z(0)], [Z(0)*H(0)*X(0)*Y(0), 1], [Z(0)*H(0)*X(0), Y(0)], [Z(0)*H(0), Y(0)*X(0)], [Z(0), Y(0)*X(0)*H(0)]})---")
  .do(e, r"---(gate_rules <- .qset(list(list(Integer(S(1)), .pymul(.pymul((cgate_t ^ S(-1)), (ph ^ S(-1))), x)), list(Integer(S(1)), .pymul(.pymul((ph ^ S(-1)), x), (cgate_t ^ S(-1)))), list(Integer(S(1)), .pymul(.pymul(x, (cgate_t ^ S(-1))), (ph ^ S(-1)))), list(cgate_t, .pymul((ph ^ S(-1)), x)), list(ph, .pymul(x, (cgate_t ^ S(-1)))), list(x, .pymul((cgate_t ^ S(-1)), (ph ^ S(-1)))), list(.pymul(cgate_t, x), (ph ^ S(-1))), list(.pymul(ph, cgate_t), x), list(.pymul(x, ph), (cgate_t ^ S(-1))), list(.pymul(.pymul(cgate_t, x), ph), Integer(S(1))), list(.pymul(.pymul(ph, cgate_t), x), Integer(S(1))), list(.pymul(.pymul(x, ph), cgate_t), Integer(S(1))))))---")
  .do(e, r"---(actual <- generate_gate_rules(.pymul(.pymul(x, ph), cgate_t), return_as_muls = TRUE))---")
  expect_equal(.run(e, r"---(actual)---"), r"---({[1, C((0),T(1))^(-1)*S(0)^(-1)*X(0)], [1, S(0)^(-1)*X(0)*C((0),T(1))^(-1)], [1, X(0)*C((0),T(1))^(-1)*S(0)^(-1)], [C((0),T(1))*X(0)*S(0), 1], [C((0),T(1))*X(0), S(0)^(-1)], [C((0),T(1)), S(0)^(-1)*X(0)], [S(0)*C((0),T(1))*X(0), 1], [S(0)*C((0),T(1)), X(0)], [S(0), X(0)*C((0),T(1))^(-1)], [X(0)*S(0)*C((0),T(1)), 1], [X(0)*S(0), C((0),T(1))^(-1)], [X(0), C((0),T(1))^(-1)*S(0)^(-1)]})---")
  .do(e, r"---(gate_rules <- .qset(list(list(list(), list((cgate_t ^ S(-1)), (ph ^ S(-1)), x)), list(list(), list((ph ^ S(-1)), x, (cgate_t ^ S(-1)))), list(list(), list(x, (cgate_t ^ S(-1)), (ph ^ S(-1)))), list(list(cgate_t), list((ph ^ S(-1)), x)), list(list(ph), list(x, (cgate_t ^ S(-1)))), list(list(x), list((cgate_t ^ S(-1)), (ph ^ S(-1)))), list(list(cgate_t, x), list((ph ^ S(-1)))), list(list(ph, cgate_t), list(x)), list(list(x, ph), list((cgate_t ^ S(-1)))), list(list(cgate_t, x, ph), list()), list(list(ph, cgate_t, x), list()), list(list(x, ph, cgate_t), list()))))---")
  .do(e, r"---(actual <- generate_gate_rules(.pymul(.pymul(x, ph), cgate_t)))---")
  expect_equal(.run(e, r"---(actual)---"), r"---({[[C((0),T(1)), X(0), S(0)], []], [[C((0),T(1)), X(0)], [S(0)^(-1)]], [[C((0),T(1))], [S(0)^(-1), X(0)]], [[S(0), C((0),T(1)), X(0)], []], [[S(0), C((0),T(1))], [X(0)]], [[S(0)], [X(0), C((0),T(1))^(-1)]], [[X(0), S(0), C((0),T(1))], []], [[X(0), S(0)], [C((0),T(1))^(-1)]], [[X(0)], [C((0),T(1))^(-1), S(0)^(-1)]], [[], [C((0),T(1))^(-1), S(0)^(-1), X(0)]], [[], [S(0)^(-1), X(0), C((0),T(1))^(-1)]], [[], [X(0), C((0),T(1))^(-1), S(0)^(-1)]]})---")
})

test_that("test_identitysearch: test_generate_equivalent_ids_1", {
  e <- .new(character(), 'test_identitysearch')
  .do(e, r"---(.tmp <- create_gate_sequence())---")
  .do(e, r"---(x <- .tmp[[1]])---")
  .do(e, r"---(y <- .tmp[[2]])---")
  .do(e, r"---(z <- .tmp[[3]])---")
  .do(e, r"---(h <- .tmp[[4]])---")
  expect_equal(.run(e, r"---(generate_equivalent_ids(list(x)))---"), r"---({[X(0)]})---")
  expect_equal(.run(e, r"---(generate_equivalent_ids(list(x, x)))---"), r"---({[X(0), X(0)]})---")
  expect_equal(.run(e, r"---(generate_equivalent_ids(list(x, y)))---"), r"---({[X(0), Y(0)], [Y(0), X(0)]})---")
  .do(e, r"---(gate_seq <- list(x, y, z))---")
  .do(e, r"---(gate_ids <- .qset(list(list(x, y, z), list(y, z, x), list(z, x, y), list(z, y, x), list(y, x, z), list(x, z, y))))---")
  expect_equal(.run(e, r"---(generate_equivalent_ids(gate_seq))---"), r"---({[X(0), Y(0), Z(0)], [X(0), Z(0), Y(0)], [Y(0), X(0), Z(0)], [Y(0), Z(0), X(0)], [Z(0), X(0), Y(0)], [Z(0), Y(0), X(0)]})---")
  .do(e, r"---(gate_ids <- .qset(list(Mul(x, y, z), Mul(y, z, x), Mul(z, x, y), Mul(z, y, x), Mul(y, x, z), Mul(x, z, y))))---")
  expect_equal(.run(e, r"---(generate_equivalent_ids(gate_seq, return_as_muls = TRUE))---"), r"---({X(0)*Y(0)*Z(0), X(0)*Z(0)*Y(0), Y(0)*X(0)*Z(0), Y(0)*Z(0)*X(0), Z(0)*X(0)*Y(0), Z(0)*Y(0)*X(0)})---")
  .do(e, r"---(gate_seq <- list(x, y, z, h))---")
  .do(e, r"---(gate_ids <- .qset(list(list(x, y, z, h), list(y, z, h, x), list(h, x, y, z), list(h, z, y, x), list(z, y, x, h), list(y, x, h, z), list(z, h, x, y), list(x, h, z, y))))---")
  expect_equal(.run(e, r"---(generate_equivalent_ids(gate_seq))---"), r"---({[H(0), X(0), Y(0), Z(0)], [H(0), Z(0), Y(0), X(0)], [X(0), H(0), Z(0), Y(0)], [X(0), Y(0), Z(0), H(0)], [Y(0), X(0), H(0), Z(0)], [Y(0), Z(0), H(0), X(0)], [Z(0), H(0), X(0), Y(0)], [Z(0), Y(0), X(0), H(0)]})---")
  .do(e, r"---(gate_seq <- list(x, y, x, y))---")
  .do(e, r"---(gate_ids <- .qset(list(list(x, y, x, y), list(y, x, y, x))))---")
  expect_equal(.run(e, r"---(generate_equivalent_ids(gate_seq))---"), r"---({[X(0), Y(0), X(0), Y(0)], [Y(0), X(0), Y(0), X(0)]})---")
  .do(e, r"---(cgate_y <- CGate(list(S(1)), y))---")
  .do(e, r"---(gate_seq <- list(y, cgate_y, y, cgate_y))---")
  .do(e, r"---(gate_ids <- .qset(list(list(y, cgate_y, y, cgate_y), list(cgate_y, y, cgate_y, y))))---")
  expect_equal(.run(e, r"---(generate_equivalent_ids(gate_seq))---"), r"---({[C((1),Y(0)), Y(0), C((1),Y(0)), Y(0)], [Y(0), C((1),Y(0)), Y(0), C((1),Y(0))]})---")
  .do(e, r"---(cnot <- CNotGate(S(1), S(0)))---")
  .do(e, r"---(cgate_z <- CGate(list(S(0)), ZGate(S(1))))---")
  .do(e, r"---(gate_seq <- list(cnot, h, cgate_z, h))---")
  .do(e, r"---(gate_ids <- .qset(list(list(cnot, h, cgate_z, h), list(h, cgate_z, h, cnot), list(h, cnot, h, cgate_z), list(cgate_z, h, cnot, h))))---")
  expect_equal(.run(e, r"---(generate_equivalent_ids(gate_seq))---"), r"---({[C((0),Z(1)), H(0), CNOT(1,0), H(0)], [CNOT(1,0), H(0), C((0),Z(1)), H(0)], [H(0), C((0),Z(1)), H(0), CNOT(1,0)], [H(0), CNOT(1,0), H(0), C((0),Z(1))]})---")
})

test_that("test_identitysearch: test_generate_equivalent_ids_2", {
  e <- .new(character(), 'test_identitysearch')
  .do(e, r"---(.tmp <- create_gate_sequence())---")
  .do(e, r"---(x <- .tmp[[1]])---")
  .do(e, r"---(y <- .tmp[[2]])---")
  .do(e, r"---(z <- .tmp[[3]])---")
  .do(e, r"---(h <- .tmp[[4]])---")
  expect_equal(.run(e, r"---(generate_equivalent_ids(list(x), return_as_muls = TRUE))---"), r"---({X(0)})---")
  .do(e, r"---(gate_ids <- .qset(list(Integer(S(1)))))---")
  expect_equal(.run(e, r"---(generate_equivalent_ids(.pymul(x, x), return_as_muls = TRUE))---"), r"---({1})---")
  .do(e, r"---(gate_ids <- .qset(list(.pymul(x, y), .pymul(y, x))))---")
  expect_equal(.run(e, r"---(generate_equivalent_ids(.pymul(x, y), return_as_muls = TRUE))---"), r"---({X(0)*Y(0), Y(0)*X(0)})---")
  .do(e, r"---(gate_ids <- .qset(list(list(x, y), list(y, x))))---")
  expect_equal(.run(e, r"---(generate_equivalent_ids(.pymul(x, y)))---"), r"---({[X(0), Y(0)], [Y(0), X(0)]})---")
  .do(e, r"---(circuit <- do.call(Mul, c(.qlist(list(x, y, z)))))---")
  .do(e, r"---(gate_ids <- .qset(list(.pymul(.pymul(x, y), z), .pymul(.pymul(y, z), x), .pymul(.pymul(z, x), y), .pymul(.pymul(z, y), x), .pymul(.pymul(y, x), z), .pymul(.pymul(x, z), y))))---")
  expect_equal(.run(e, r"---(generate_equivalent_ids(circuit, return_as_muls = TRUE))---"), r"---({X(0)*Y(0)*Z(0), X(0)*Z(0)*Y(0), Y(0)*X(0)*Z(0), Y(0)*Z(0)*X(0), Z(0)*X(0)*Y(0), Z(0)*Y(0)*X(0)})---")
  .do(e, r"---(circuit <- do.call(Mul, c(.qlist(list(x, y, z, h)))))---")
  .do(e, r"---(gate_ids <- .qset(list(.pymul(.pymul(.pymul(x, y), z), h), .pymul(.pymul(.pymul(y, z), h), x), .pymul(.pymul(.pymul(h, x), y), z), .pymul(.pymul(.pymul(h, z), y), x), .pymul(.pymul(.pymul(z, y), x), h), .pymul(.pymul(.pymul(y, x), h), z), .pymul(.pymul(.pymul(z, h), x), y), .pymul(.pymul(.pymul(x, h), z), y))))---")
  expect_equal(.run(e, r"---(generate_equivalent_ids(circuit, return_as_muls = TRUE))---"), r"---({H(0)*X(0)*Y(0)*Z(0), H(0)*Z(0)*Y(0)*X(0), X(0)*H(0)*Z(0)*Y(0), X(0)*Y(0)*Z(0)*H(0), Y(0)*X(0)*H(0)*Z(0), Y(0)*Z(0)*H(0)*X(0), Z(0)*H(0)*X(0)*Y(0), Z(0)*Y(0)*X(0)*H(0)})---")
  .do(e, r"---(circuit <- do.call(Mul, c(.qlist(list(x, y, x, y)))))---")
  .do(e, r"---(gate_ids <- .qset(list(.pymul(.pymul(.pymul(x, y), x), y), .pymul(.pymul(.pymul(y, x), y), x))))---")
  expect_equal(.run(e, r"---(generate_equivalent_ids(circuit, return_as_muls = TRUE))---"), r"---({X(0)*Y(0)*X(0)*Y(0), Y(0)*X(0)*Y(0)*X(0)})---")
  .do(e, r"---(cgate_y <- CGate(list(S(1)), y))---")
  .do(e, r"---(circuit <- do.call(Mul, c(.qlist(list(y, cgate_y, y, cgate_y)))))---")
  .do(e, r"---(gate_ids <- .qset(list(.pymul(.pymul(.pymul(y, cgate_y), y), cgate_y), .pymul(.pymul(.pymul(cgate_y, y), cgate_y), y))))---")
  expect_equal(.run(e, r"---(generate_equivalent_ids(circuit, return_as_muls = TRUE))---"), r"---({C((1),Y(0))*Y(0)*C((1),Y(0))*Y(0), Y(0)*C((1),Y(0))*Y(0)*C((1),Y(0))})---")
  .do(e, r"---(cnot <- CNotGate(S(1), S(0)))---")
  .do(e, r"---(cgate_z <- CGate(list(S(0)), ZGate(S(1))))---")
  .do(e, r"---(circuit <- do.call(Mul, c(.qlist(list(cnot, h, cgate_z, h)))))---")
  .do(e, r"---(gate_ids <- .qset(list(.pymul(.pymul(.pymul(cnot, h), cgate_z), h), .pymul(.pymul(.pymul(h, cgate_z), h), cnot), .pymul(.pymul(.pymul(h, cnot), h), cgate_z), .pymul(.pymul(.pymul(cgate_z, h), cnot), h))))---")
  expect_equal(.run(e, r"---(generate_equivalent_ids(circuit, return_as_muls = TRUE))---"), r"---({C((0),Z(1))*H(0)*CNOT(1,0)*H(0), CNOT(1,0)*H(0)*C((0),Z(1))*H(0), H(0)*C((0),Z(1))*H(0)*CNOT(1,0), H(0)*CNOT(1,0)*H(0)*C((0),Z(1))})---")
})

test_that("test_identitysearch: test_is_scalar_nonsparse_matrix", {
  e <- .new(character(), 'test_identitysearch')
  .do(e, r"---(numqubits <- S(2))---")
  .do(e, r"---(id_only <- FALSE)---")
  .do(e, r"---(id_gate <- list(IdentityGate(S(1))))---")
  .do(e, r"---(actual <- is_scalar_nonsparse_matrix(id_gate, numqubits, id_only))---")
  expect_equal(.run(e, r"---(actual)---"), r"---(True)---")
  .do(e, r"---(x0 <- XGate(S(0)))---")
  .do(e, r"---(xx_circuit <- list(x0, x0))---")
  .do(e, r"---(actual <- is_scalar_nonsparse_matrix(xx_circuit, numqubits, id_only))---")
  expect_equal(.run(e, r"---(actual)---"), r"---(True)---")
  .do(e, r"---(x1 <- XGate(S(1)))---")
  .do(e, r"---(y1 <- YGate(S(1)))---")
  .do(e, r"---(xy_circuit <- list(x1, y1))---")
  .do(e, r"---(actual <- is_scalar_nonsparse_matrix(xy_circuit, numqubits, id_only))---")
  expect_equal(.run(e, r"---(actual)---"), r"---(False)---")
  .do(e, r"---(z1 <- ZGate(S(1)))---")
  .do(e, r"---(xyz_circuit <- list(x1, y1, z1))---")
  .do(e, r"---(actual <- is_scalar_nonsparse_matrix(xyz_circuit, numqubits, id_only))---")
  expect_equal(.run(e, r"---(actual)---"), r"---(True)---")
  .do(e, r"---(cnot <- CNotGate(S(1), S(0)))---")
  .do(e, r"---(cnot_circuit <- list(cnot, cnot))---")
  .do(e, r"---(actual <- is_scalar_nonsparse_matrix(cnot_circuit, numqubits, id_only))---")
  expect_equal(.run(e, r"---(actual)---"), r"---(True)---")
  .do(e, r"---(h <- HadamardGate(S(0)))---")
  .do(e, r"---(hh_circuit <- list(h, h))---")
  .do(e, r"---(actual <- is_scalar_nonsparse_matrix(hh_circuit, numqubits, id_only))---")
  expect_equal(.run(e, r"---(actual)---"), r"---(True)---")
  .do(e, r"---(h1 <- HadamardGate(S(1)))---")
  .do(e, r"---(xhzh_circuit <- list(x1, h1, z1, h1))---")
  .do(e, r"---(actual <- is_scalar_nonsparse_matrix(xhzh_circuit, numqubits, id_only))---")
  expect_equal(.run(e, r"---(actual)---"), r"---(True)---")
  .do(e, r"---(id_only <- TRUE)---")
  .do(e, r"---(actual <- is_scalar_nonsparse_matrix(xhzh_circuit, numqubits, id_only))---")
  expect_equal(.run(e, r"---(actual)---"), r"---(True)---")
  .do(e, r"---(actual <- is_scalar_nonsparse_matrix(xyz_circuit, numqubits, id_only))---")
  expect_equal(.run(e, r"---(actual)---"), r"---(False)---")
  .do(e, r"---(actual <- is_scalar_nonsparse_matrix(cnot_circuit, numqubits, id_only))---")
  expect_equal(.run(e, r"---(actual)---"), r"---(True)---")
  .do(e, r"---(actual <- is_scalar_nonsparse_matrix(hh_circuit, numqubits, id_only))---")
  expect_equal(.run(e, r"---(actual)---"), r"---(True)---")
})

test_that("test_identitysearch: test_is_scalar_sparse_matrix", {
  e <- .new(character(), 'test_identitysearch')
  .do(e, r"---(numqubits <- S(2))---")
  .do(e, r"---(id_only <- FALSE)---")
  .do(e, r"---(id_gate <- list(IdentityGate(S(1))))---")
  .do(e, r"---(x0 <- XGate(S(0)))---")
  .do(e, r"---(xx_circuit <- list(x0, x0))---")
  expect_equal(.run(e, r"---(is_scalar_sparse_matrix(xx_circuit, numqubits, id_only))---"), r"---(True)---")
  .do(e, r"---(x1 <- XGate(S(1)))---")
  .do(e, r"---(y1 <- YGate(S(1)))---")
  .do(e, r"---(xy_circuit <- list(x1, y1))---")
  .do(e, r"---(z1 <- ZGate(S(1)))---")
  .do(e, r"---(xyz_circuit <- list(x1, y1, z1))---")
  .do(e, r"---(cnot <- CNotGate(S(1), S(0)))---")
  .do(e, r"---(cnot_circuit <- list(cnot, cnot))---")
  expect_equal(.run(e, r"---(is_scalar_sparse_matrix(cnot_circuit, numqubits, id_only))---"), r"---(True)---")
  .do(e, r"---(h <- HadamardGate(S(0)))---")
  .do(e, r"---(hh_circuit <- list(h, h))---")
  expect_equal(.run(e, r"---(is_scalar_sparse_matrix(hh_circuit, numqubits, id_only))---"), r"---(True)---")
  .do(e, r"---(h1 <- HadamardGate(S(1)))---")
  .do(e, r"---(xhzh_circuit <- list(x1, h1, z1, h1))---")
  .do(e, r"---(id_only <- TRUE)---")
  expect_equal(.run(e, r"---(is_scalar_sparse_matrix(cnot_circuit, numqubits, id_only))---"), r"---(True)---")
  expect_equal(.run(e, r"---(is_scalar_sparse_matrix(hh_circuit, numqubits, id_only))---"), r"---(True)---")
})

test_that("test_identitysearch: test_is_degenerate", {
  e <- .new(character(), 'test_identitysearch')
  .do(e, r"---(.tmp <- create_gate_sequence())---")
  .do(e, r"---(x <- .tmp[[1]])---")
  .do(e, r"---(y <- .tmp[[2]])---")
  .do(e, r"---(z <- .tmp[[3]])---")
  .do(e, r"---(h <- .tmp[[4]])---")
  .do(e, r"---(gate_id <- GateIdentity(x, y, z))---")
  .do(e, r"---(ids <- .qset(list(gate_id)))---")
  .do(e, r"---(another_id <- list(z, y, x))---")
  expect_equal(.run(e, r"---(is_degenerate(ids, another_id))---"), r"---(True)---")
})

test_that("test_identitysearch: test_is_reducible", {
  e <- .new(character(), 'test_identitysearch')
  .do(e, r"---(nqubits <- S(2))---")
  .do(e, r"---(.tmp <- create_gate_sequence())---")
  .do(e, r"---(x <- .tmp[[1]])---")
  .do(e, r"---(y <- .tmp[[2]])---")
  .do(e, r"---(z <- .tmp[[3]])---")
  .do(e, r"---(h <- .tmp[[4]])---")
  .do(e, r"---(circuit <- list(x, y, y))---")
  expect_equal(.run(e, r"---(is_reducible(circuit, nqubits, S(1), S(3)))---"), r"---(True)---")
  .do(e, r"---(circuit <- list(x, y, x))---")
  expect_equal(.run(e, r"---(is_reducible(circuit, nqubits, S(1), S(3)))---"), r"---(False)---")
  .do(e, r"---(circuit <- list(x, y, y, x))---")
  expect_equal(.run(e, r"---(is_reducible(circuit, nqubits, S(0), S(4)))---"), r"---(True)---")
  .do(e, r"---(circuit <- list(x, y, y, x))---")
  expect_equal(.run(e, r"---(is_reducible(circuit, nqubits, S(1), S(3)))---"), r"---(True)---")
  .do(e, r"---(circuit <- list(x, y, z, y, y))---")
  expect_equal(.run(e, r"---(is_reducible(circuit, nqubits, S(1), S(5)))---"), r"---(True)---")
})

test_that("test_identitysearch: test_bfs_identity_search", {
  e <- .new(character(), 'test_identitysearch')
  expect_equal(.run(e, r"---(bfs_identity_search(list(), S(1)))---"), r"---({})---")
  .do(e, r"---(.tmp <- create_gate_sequence())---")
  .do(e, r"---(x <- .tmp[[1]])---")
  .do(e, r"---(y <- .tmp[[2]])---")
  .do(e, r"---(z <- .tmp[[3]])---")
  .do(e, r"---(h <- .tmp[[4]])---")
  .do(e, r"---(gate_list <- list(x))---")
  .do(e, r"---(id_set <- .qset(list(GateIdentity(x, x))))---")
  expect_equal(.run(e, r"---(bfs_identity_search(gate_list, S(1), max_depth = S(2)))---"), r"---({1})---")
  .do(e, r"---(gate_list <- list(x, y, z))---")
  .do(e, r"---(id_set <- .qset(list(GateIdentity(x, x), GateIdentity(y, y), GateIdentity(z, z), GateIdentity(x, y, z))))---")
  expect_equal(.run(e, r"---(bfs_identity_search(gate_list, S(1)))---"), r"---({1, 1, 1, X(0)*Y(0)*Z(0)})---")
  .do(e, r"---(id_set <- .qset(list(GateIdentity(x, x), GateIdentity(y, y), GateIdentity(z, z), GateIdentity(x, y, z), GateIdentity(x, y, x, y), GateIdentity(x, z, x, z), GateIdentity(y, z, y, z))))---")
  expect_equal(.run(e, r"---(bfs_identity_search(gate_list, S(1), max_depth = S(4)))---"), r"---({1, 1, 1, X(0)*Y(0)*X(0)*Y(0), X(0)*Y(0)*Z(0), X(0)*Z(0)*X(0)*Z(0), Y(0)*Z(0)*Y(0)*Z(0)})---")
  expect_equal(.run(e, r"---(bfs_identity_search(gate_list, S(1), max_depth = S(5)))---"), r"---({1, 1, 1, X(0)*Y(0)*X(0)*Y(0), X(0)*Y(0)*Z(0), X(0)*Z(0)*X(0)*Z(0), Y(0)*Z(0)*Y(0)*Z(0)})---")
  .do(e, r"---(gate_list <- list(x, y, z, h))---")
  .do(e, r"---(id_set <- .qset(list(GateIdentity(x, x), GateIdentity(y, y), GateIdentity(z, z), GateIdentity(h, h), GateIdentity(x, y, z), GateIdentity(x, y, x, y), GateIdentity(x, z, x, z), GateIdentity(x, h, z, h), GateIdentity(y, z, y, z), GateIdentity(y, h, y, h))))---")
  expect_equal(.run(e, r"---(bfs_identity_search(gate_list, S(1)))---"), r"---({1, 1, 1, 1, X(0)*H(0)*Z(0)*H(0), X(0)*Y(0)*X(0)*Y(0), X(0)*Y(0)*Z(0), X(0)*Z(0)*X(0)*Z(0), Y(0)*H(0)*Y(0)*H(0), Y(0)*Z(0)*Y(0)*Z(0)})---")
  .do(e, r"---(id_set <- .qset(list(GateIdentity(x, x), GateIdentity(y, y), GateIdentity(z, z), GateIdentity(h, h))))---")
  expect_equal(.run(e, r"---(id_set)---"), r"---({1, 1, 1, 1})---")
  .do(e, r"---(id_set <- .qset(list(GateIdentity(x, x), GateIdentity(y, y), GateIdentity(z, z), GateIdentity(h, h), GateIdentity(x, y, z), GateIdentity(x, y, x, y), GateIdentity(x, z, x, z), GateIdentity(x, h, z, h), GateIdentity(y, z, y, z), GateIdentity(y, h, y, h), GateIdentity(x, y, h, x, h), GateIdentity(x, z, h, y, h), GateIdentity(y, z, h, z, h))))---")
  expect_equal(.run(e, r"---(bfs_identity_search(gate_list, S(1), max_depth = S(5)))---"), r"---({1, 1, 1, 1, X(0)*H(0)*Z(0)*H(0), X(0)*Y(0)*H(0)*X(0)*H(0), X(0)*Y(0)*X(0)*Y(0), X(0)*Y(0)*Z(0), X(0)*Z(0)*H(0)*Y(0)*H(0), X(0)*Z(0)*X(0)*Z(0), Y(0)*H(0)*Y(0)*H(0), Y(0)*Z(0)*H(0)*Z(0)*H(0), Y(0)*Z(0)*Y(0)*Z(0)})---")
  .do(e, r"---(id_set <- .qset(list(GateIdentity(x, x), GateIdentity(y, y), GateIdentity(z, z), GateIdentity(h, h), GateIdentity(x, h, z, h))))---")
  expect_equal(.run(e, r"---(id_set)---"), r"---({1, 1, 1, 1, X(0)*H(0)*Z(0)*H(0)})---")
  .do(e, r"---(cnot <- CNotGate(S(1), S(0)))---")
  .do(e, r"---(gate_list <- list(x, cnot))---")
  .do(e, r"---(id_set <- .qset(list(GateIdentity(x, x), GateIdentity(cnot, cnot), GateIdentity(x, cnot, x, cnot))))---")
  expect_equal(.run(e, r"---(bfs_identity_search(gate_list, S(2), max_depth = S(4)))---"), r"---({1, 1, X(0)*CNOT(1,0)*X(0)*CNOT(1,0)})---")
  .do(e, r"---(cgate_x <- CGate(list(S(1)), x))---")
  .do(e, r"---(gate_list <- list(x, cgate_x))---")
  .do(e, r"---(id_set <- .qset(list(GateIdentity(x, x), GateIdentity(cgate_x, cgate_x), GateIdentity(x, cgate_x, x, cgate_x))))---")
  expect_equal(.run(e, r"---(bfs_identity_search(gate_list, S(2), max_depth = S(4)))---"), r"---({1, 1, X(0)*C((1),X(0))*X(0)*C((1),X(0))})---")
  .do(e, r"---(cgate_z <- CGate(list(S(0)), ZGate(S(1))))---")
  .do(e, r"---(gate_list <- list(cnot, cgate_z, h))---")
  .do(e, r"---(id_set <- .qset(list(GateIdentity(h, h), GateIdentity(cgate_z, cgate_z), GateIdentity(cnot, cnot), GateIdentity(cnot, h, cgate_z, h))))---")
  expect_equal(.run(e, r"---(bfs_identity_search(gate_list, S(2), max_depth = S(4)))---"), r"---({1, 1, 1, CNOT(1,0)*H(0)*C((0),Z(1))*H(0)})---")
  .do(e, r"---(s <- PhaseGate(S(0)))---")
  .do(e, r"---(v_t <- TGate(S(0)))---")
  .do(e, r"---(gate_list <- list(s, v_t))---")
  .do(e, r"---(id_set <- .qset(list(GateIdentity(s, s, s, s))))---")
  expect_equal(.run(e, r"---(bfs_identity_search(gate_list, S(1), max_depth = S(4)))---"), r"---({S(0)^4})---")
})

test_that("test_identitysearch: test_bfs_identity_search_xfail", {
  e <- .new(character(), 'test_identitysearch')
  .do(e, r"---(s <- PhaseGate(S(0)))---")
