})

test_that("test_innerproduct: test_innerproduct", {
  e <- .new(character(), 'test_innerproduct')
  .do(e, r"---(k <- Ket("k"))---")
  .do(e, r"---(b <- Bra("b"))---")
  .do(e, r"---(ip <- InnerProduct(b, k))---")
  expect_equal(.run(e, r"---(qisinstance(ip, "InnerProduct"))---"), r"---(True)---")
  expect_equal(.run(e, r"---(qattr(ip, "bra"))---"), r"---(<b|)---")
  expect_equal(.run(e, r"---(qattr(ip, "ket"))---"), r"---(|k>)---")
  expect_equal(.run(e, r"---(.pymul(b, k))---"), r"---(<b|k>)---")
  expect_equal(.run(e, r"---(.pymul(.pymul(k, .pymul(b, k)), b))---"), r"---(<b|k>*|k><b|)---")
  expect_equal(.run(e, r"---(subs(InnerProduct(b, k), b, Dagger(k)))---"), r"---(<k|k>)---")
})

test_that("test_innerproduct: test_innerproduct_dagger", {
  e <- .new(character(), 'test_innerproduct')
  .do(e, r"---(k <- Ket("k"))---")
  .do(e, r"---(b <- Bra("b"))---")
  .do(e, r"---(ip <- .pymul(b, k))---")
  expect_equal(.run(e, r"---(Dagger(ip))---"), r"---(<k|b>)---")
})

test_that("test_innerproduct: test_doit", {
  e <- .new(character(), 'test_innerproduct')
  .do(e, r"---(f <- FooKet("foo"))---")
  .do(e, r"---(b <- BarBra("bar"))---")
  expect_equal(.run(e, r"---(doit(InnerProduct(b, f)))---"), r"---(I)---")
  expect_equal(.run(e, r"---(doit(InnerProduct(Dagger(f), Dagger(b))))---"), r"---(-I)---")
  expect_equal(.run(e, r"---(doit(InnerProduct(Dagger(f), f)))---"), r"---(1)---")
})

test_that("test_kind: test_bra_ket", {
