  expect_equal(.run(e, r"---(qattr(b, "kind"))---"), r"---(BraKind)---")
  expect_equal(.run(e, r"---(qattr(.pymul(b, k), "kind"))---"), r"---(NumberKind)---")
  expect_equal(.run(e, r"---(qattr(.pymul(x, k), "kind"))---"), r"---(KetKind)---")
  expect_equal(.run(e, r"---(qattr(.pymul(x, b), "kind"))---"), r"---(BraKind)---")
})

