test_that("test_kind: test_tensorproduct_kind", {
  e <- .new(c(r"---(k <- Ket("k"))---", r"---(b <- Bra("k"))---", r"---(A <- Operator("A"))---", r"---(B <- Operator("B"))---", r"---(.tmp <- sym_symbols("x y z", integer = TRUE))---", r"---(x <- .tmp[[1]])---", r"---(y <- .tmp[[2]])---", r"---(z <- .tmp[[3]])---"), 'test_kind')
  expect_equal(.run(e, r"---(qattr(TensorProduct(k, k), "kind"))---"), r"---(KetKind)---")
  expect_equal(.run(e, r"---(qattr(TensorProduct(b, b), "kind"))---"), r"---(BraKind)---")
  expect_equal(.run(e, r"---(qattr(TensorProduct(.pymul(x, k), .pymul(y, k)), "kind"))---"), r"---(KetKind)---")
  expect_equal(.run(e, r"---(qattr(TensorProduct(.pymul(x, b), .pymul(y, b)), "kind"))---"), r"---(BraKind)---")
  expect_equal(.run(e, r"---(qattr(TensorProduct(.pymul(.pymul(x, b), k), .pymul(.pymul(y, b), k)), "kind"))---"), r"---(NumberKind)---")
  expect_equal(.run(e, r"---(qattr(TensorProduct(.pymul(.pymul(x, k), b), .pymul(.pymul(y, k), b)), "kind"))---"), r"---(OperatorKind)---")
  expect_equal(.run(e, r"---(qattr(TensorProduct(A, B), "kind"))---"), r"---(OperatorKind)---")
  expect_equal(.run(e, r"---(qattr(TensorProduct(A, .pymul(x, B)), "kind"))---"), r"---(OperatorKind)---")
  expect_equal(.run(e, r"---(qattr(TensorProduct(.pymul(x, A), B), "kind"))---"), r"---(OperatorKind)---")
  expect_equal(.run(e, r"---(qattr(TensorProduct(x, k), "kind"))---"), r"---(KetKind)---")
  expect_equal(.run(e, r"---(qattr(TensorProduct(b, y), "kind"))---"), r"---(BraKind)---")
  expect_equal(.run(e, r"---(qattr(TensorProduct(x, A), "kind"))---"), r"---(OperatorKind)---")
})

