test_that("test_pauli: test_pauli_operators_multiplication", {
  e <- .new(c(r"---(.tmp <- list(SigmaX(), SigmaY(), SigmaZ()))---", r"---(sx <- .tmp[[1]])---", r"---(sy <- .tmp[[2]])---", r"---(sz <- .tmp[[3]])---", r"---(.tmp <- list(SigmaX(S(1)), SigmaY(S(1)), SigmaZ(S(1))))---", r"---(sx1 <- .tmp[[1]])---", r"---(sy1 <- .tmp[[2]])---", r"---(sz1 <- .tmp[[3]])---", r"---(.tmp <- list(SigmaX(S(2)), SigmaY(S(2)), SigmaZ(S(2))))---", r"---(sx2 <- .tmp[[1]])---", r"---(sy2 <- .tmp[[2]])---", r"---(sz2 <- .tmp[[3]])---", r"---(.tmp <- list(SigmaMinus(), SigmaPlus()))---", r"---(sm <- .tmp[[1]])---", r"---(sp <- .tmp[[2]])---", r"---(.tmp <- list(SigmaMinus(S(1)), SigmaPlus(S(1))))---", r"---(sm1 <- .tmp[[1]])---", r"---(sp1 <- .tmp[[2]])---", r"---(.tmp <- list(Operator("A"), Operator("B")))---", r"---(A <- .tmp[[1]])---", r"---(B <- .tmp[[2]])---"), 'test_pauli')
  expect_equal(.run(e, r"---(qsimplify_pauli(.pymul(sx, sx)))---"), r"---(1)---")
  expect_equal(.run(e, r"---(qsimplify_pauli(.pymul(sy, sy)))---"), r"---(1)---")
  expect_equal(.run(e, r"---(qsimplify_pauli(.pymul(sz, sz)))---"), r"---(1)---")
  expect_equal(.run(e, r"---(qsimplify_pauli(.pymul(sx, sy)))---"), r"---(I*SigmaZ())---")
  expect_equal(.run(e, r"---(qsimplify_pauli(.pymul(sy, sz)))---"), r"---(I*SigmaX())---")
  expect_equal(.run(e, r"---(qsimplify_pauli(.pymul(sz, sx)))---"), r"---(I*SigmaY())---")
  expect_equal(.run(e, r"---(qsimplify_pauli(.pymul(sy, sx)))---"), r"---(-I*SigmaZ())---")
  expect_equal(.run(e, r"---(qsimplify_pauli(.pymul(sz, sy)))---"), r"---(-I*SigmaX())---")
  expect_equal(.run(e, r"---(qsimplify_pauli(.pymul(sx, sz)))---"), r"---(-I*SigmaY())---")
})

