test_that("test_pauli: test_pauli_states", {
  e <- .new(c(r"---(.tmp <- list(SigmaX(), SigmaY(), SigmaZ()))---", r"---(sx <- .tmp[[1]])---", r"---(sy <- .tmp[[2]])---", r"---(sz <- .tmp[[3]])---", r"---(.tmp <- list(SigmaX(S(1)), SigmaY(S(1)), SigmaZ(S(1))))---", r"---(sx1 <- .tmp[[1]])---", r"---(sy1 <- .tmp[[2]])---", r"---(sz1 <- .tmp[[3]])---", r"---(.tmp <- list(SigmaX(S(2)), SigmaY(S(2)), SigmaZ(S(2))))---", r"---(sx2 <- .tmp[[1]])---", r"---(sy2 <- .tmp[[2]])---", r"---(sz2 <- .tmp[[3]])---", r"---(.tmp <- list(SigmaMinus(), SigmaPlus()))---", r"---(sm <- .tmp[[1]])---", r"---(sp <- .tmp[[2]])---", r"---(.tmp <- list(SigmaMinus(S(1)), SigmaPlus(S(1))))---", r"---(sm1 <- .tmp[[1]])---", r"---(sp1 <- .tmp[[2]])---", r"---(.tmp <- list(Operator("A"), Operator("B")))---", r"---(A <- .tmp[[1]])---", r"---(B <- .tmp[[2]])---"), 'test_pauli')
  .do(e, r"---(.tmp <- list(SigmaX(), SigmaZ()))---")
  .do(e, r"---(sx <- .tmp[[1]])---")
  .do(e, r"---(sz <- .tmp[[2]])---")
  .do(e, r"---(up <- SigmaZKet(S(0)))---")
  .do(e, r"---(down <- SigmaZKet(S(1)))---")
  expect_equal(.run(e, r"---(qapply(.pymul(sx, up)))---"), r"---(|1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(sx, down)))---"), r"---(|0>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(sz, up)))---"), r"---(|0>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(sz, down)))---"), r"---(-|1>)---")
  .do(e, r"---(up <- SigmaZBra(S(0)))---")
  .do(e, r"---(down <- SigmaZBra(S(1)))---")
  expect_equal(.run(e, r"---(qapply(.pymul(up, sx), dagger = TRUE))---"), r"---(<1|)---")
  expect_equal(.run(e, r"---(qapply(.pymul(down, sx), dagger = TRUE))---"), r"---(<0|)---")
  expect_equal(.run(e, r"---(qapply(.pymul(up, sz), dagger = TRUE))---"), r"---(<0|)---")
  expect_equal(.run(e, r"---(qapply(.pymul(down, sz), dagger = TRUE))---"), r"---(-<1|)---")
  expect_equal(.run(e, r"---(Dagger(SigmaZKet(S(0))))---"), r"---(<0|)---")
  expect_equal(.run(e, r"---(Dagger(SigmaZBra(S(1))))---"), r"---(|1>)---")
  expect_equal(.run(e, r"---(SigmaZBra(S(2)))---"), r"---(ERR ValueError: n must be 0 or 1)---")
  expect_equal(.run(e, r"---(SigmaZKet(S(2)))---"), r"---(ERR ValueError: n must be 0 or 1)---")
})

test_that("test_pauli: test_use_name", {
  e <- .new(c(r"---(.tmp <- list(SigmaX(), SigmaY(), SigmaZ()))---", r"---(sx <- .tmp[[1]])---", r"---(sy <- .tmp[[2]])---", r"---(sz <- .tmp[[3]])---", r"---(.tmp <- list(SigmaX(S(1)), SigmaY(S(1)), SigmaZ(S(1))))---", r"---(sx1 <- .tmp[[1]])---", r"---(sy1 <- .tmp[[2]])---", r"---(sz1 <- .tmp[[3]])---", r"---(.tmp <- list(SigmaX(S(2)), SigmaY(S(2)), SigmaZ(S(2))))---", r"---(sx2 <- .tmp[[1]])---", r"---(sy2 <- .tmp[[2]])---", r"---(sz2 <- .tmp[[3]])---", r"---(.tmp <- list(SigmaMinus(), SigmaPlus()))---", r"---(sm <- .tmp[[1]])---", r"---(sp <- .tmp[[2]])---", r"---(.tmp <- list(SigmaMinus(S(1)), SigmaPlus(S(1))))---", r"---(sm1 <- .tmp[[1]])---", r"---(sp1 <- .tmp[[2]])---", r"---(.tmp <- list(Operator("A"), Operator("B")))---", r"---(A <- .tmp[[1]])---", r"---(B <- .tmp[[2]])---"), 'test_pauli')
  expect_equal(.run(e, r"---(qattr(sm, "use_name"))---"), r"---(False)---")
  expect_equal(.run(e, r"---(qattr(sm1, "use_name"))---"), r"---(True)---")
  expect_equal(.run(e, r"---(qattr(sx, "use_name"))---"), r"---(False)---")
  expect_equal(.run(e, r"---(qattr(sx1, "use_name"))---"), r"---(True)---")
})

test_that("test_pauli: test_printing", {
  e <- .new(c(r"---(.tmp <- list(SigmaX(), SigmaY(), SigmaZ()))---", r"---(sx <- .tmp[[1]])---", r"---(sy <- .tmp[[2]])---", r"---(sz <- .tmp[[3]])---", r"---(.tmp <- list(SigmaX(S(1)), SigmaY(S(1)), SigmaZ(S(1))))---", r"---(sx1 <- .tmp[[1]])---", r"---(sy1 <- .tmp[[2]])---", r"---(sz1 <- .tmp[[3]])---", r"---(.tmp <- list(SigmaX(S(2)), SigmaY(S(2)), SigmaZ(S(2))))---", r"---(sx2 <- .tmp[[1]])---", r"---(sy2 <- .tmp[[2]])---", r"---(sz2 <- .tmp[[3]])---", r"---(.tmp <- list(SigmaMinus(), SigmaPlus()))---", r"---(sm <- .tmp[[1]])---", r"---(sp <- .tmp[[2]])---", r"---(.tmp <- list(SigmaMinus(S(1)), SigmaPlus(S(1))))---", r"---(sm1 <- .tmp[[1]])---", r"---(sp1 <- .tmp[[2]])---", r"---(.tmp <- list(Operator("A"), Operator("B")))---", r"---(A <- .tmp[[1]])---", r"---(B <- .tmp[[2]])---"), 'test_pauli')
  expect_equal(.run(e, r"---(latex(sx))---"), r"---({\sigma_x})---")
  expect_equal(.run(e, r"---(latex(sx1))---"), r"---({\sigma_x^{(1)}})---")
  expect_equal(.run(e, r"---(latex(sy))---"), r"---({\sigma_y})---")
  expect_equal(.run(e, r"---(latex(sy1))---"), r"---({\sigma_y^{(1)}})---")
  expect_equal(.run(e, r"---(latex(sz))---"), r"---({\sigma_z})---")
  expect_equal(.run(e, r"---(latex(sz1))---"), r"---({\sigma_z^{(1)}})---")
  expect_equal(.run(e, r"---(latex(sm))---"), r"---({\sigma_-})---")
  expect_equal(.run(e, r"---(latex(sm1))---"), r"---({\sigma_-^{(1)}})---")
  expect_equal(.run(e, r"---(latex(sp))---"), r"---({\sigma_+})---")
  expect_equal(.run(e, r"---(latex(sp1))---"), r"---({\sigma_+^{(1)}})---")
})

test_that("test_pauli: test_represent", {
  e <- .new(c(r"---(.tmp <- list(SigmaX(), SigmaY(), SigmaZ()))---", r"---(sx <- .tmp[[1]])---", r"---(sy <- .tmp[[2]])---", r"---(sz <- .tmp[[3]])---", r"---(.tmp <- list(SigmaX(S(1)), SigmaY(S(1)), SigmaZ(S(1))))---", r"---(sx1 <- .tmp[[1]])---", r"---(sy1 <- .tmp[[2]])---", r"---(sz1 <- .tmp[[3]])---", r"---(.tmp <- list(SigmaX(S(2)), SigmaY(S(2)), SigmaZ(S(2))))---", r"---(sx2 <- .tmp[[1]])---", r"---(sy2 <- .tmp[[2]])---", r"---(sz2 <- .tmp[[3]])---", r"---(.tmp <- list(SigmaMinus(), SigmaPlus()))---", r"---(sm <- .tmp[[1]])---", r"---(sp <- .tmp[[2]])---", r"---(.tmp <- list(SigmaMinus(S(1)), SigmaPlus(S(1))))---", r"---(sm1 <- .tmp[[1]])---", r"---(sp1 <- .tmp[[2]])---", r"---(.tmp <- list(Operator("A"), Operator("B")))---", r"---(A <- .tmp[[1]])---", r"---(B <- .tmp[[2]])---"), 'test_pauli')
  expect_equal(.run(e, r"---(represent(sx))---"), r"---(Matrix([[0, 1], [1, 0]]))---")
  expect_equal(.run(e, r"---(represent(sy))---"), r"---(Matrix([[0, -I], [I, 0]]))---")
  expect_equal(.run(e, r"---(represent(sz))---"), r"---(Matrix([[1, 0], [0, -1]]))---")
  expect_equal(.run(e, r"---(represent(sm))---"), r"---(Matrix([[0, 0], [1, 0]]))---")
  expect_equal(.run(e, r"---(represent(sp))---"), r"---(Matrix([[0, 1], [0, 0]]))---")
})

test_that("test_pauli: test_is_annihilation", {
  e <- .new(c(r"---(.tmp <- list(SigmaX(), SigmaY(), SigmaZ()))---", r"---(sx <- .tmp[[1]])---", r"---(sy <- .tmp[[2]])---", r"---(sz <- .tmp[[3]])---", r"---(.tmp <- list(SigmaX(S(1)), SigmaY(S(1)), SigmaZ(S(1))))---", r"---(sx1 <- .tmp[[1]])---", r"---(sy1 <- .tmp[[2]])---", r"---(sz1 <- .tmp[[3]])---", r"---(.tmp <- list(SigmaX(S(2)), SigmaY(S(2)), SigmaZ(S(2))))---", r"---(sx2 <- .tmp[[1]])---", r"---(sy2 <- .tmp[[2]])---", r"---(sz2 <- .tmp[[3]])---", r"---(.tmp <- list(SigmaMinus(), SigmaPlus()))---", r"---(sm <- .tmp[[1]])---", r"---(sp <- .tmp[[2]])---", r"---(.tmp <- list(SigmaMinus(S(1)), SigmaPlus(S(1))))---", r"---(sm1 <- .tmp[[1]])---", r"---(sp1 <- .tmp[[2]])---", r"---(.tmp <- list(Operator("A"), Operator("B")))---", r"---(A <- .tmp[[1]])---", r"---(B <- .tmp[[2]])---"), 'test_pauli')
  expect_equal(.run(e, r"---(qattr(sm, "is_annihilation"))---"), r"---(True)---")
  expect_equal(.run(e, r"---(qattr(sp, "is_annihilation"))---"), r"---(False)---")
})

test_that("test_piab: test_H", {
  e <- .new(c(r"---(.tmp <- sym_symbols("i j n x"))---", r"---(i <- .tmp[[1]])---", r"---(j <- .tmp[[2]])---", r"---(n <- .tmp[[3]])---", r"---(x <- .tmp[[4]])---"), 'test_piab')
  expect_equal(.run(e, r"---(qattr(PIABHamiltonian("H"), "hilbert_space"))---"), r"---(L2(Interval(-oo, oo)))---")
  expect_equal(.run(e, r"---(qapply(.pymul(PIABHamiltonian("H"), PIABKet(n))))---"), r"---(hbar^2*pi^2*n^2*|n>/(2*L^2*m))---")
})

test_that("test_piab: test_states", {
  e <- .new(c(r"---(.tmp <- sym_symbols("i j n x"))---", r"---(i <- .tmp[[1]])---", r"---(j <- .tmp[[2]])---", r"---(n <- .tmp[[3]])---", r"---(x <- .tmp[[4]])---"), 'test_piab')
  expect_equal(.run(e, r"---(qcall(PIABKet(n), "dual_class"))---"), r"---(PIABBra)---")
  expect_equal(.run(e, r"---(qattr(PIABKet(n), "hilbert_space"))---"), r"---(L2(Interval(-oo, oo)))---")
  expect_equal(.run(e, r"---(represent(PIABKet(n)))---"), r"---(sqrt(2)*sqrt(1/L)*sin(pi*n*x/L))---")
  expect_equal(.run(e, r"---(doit(.pymul(PIABBra(i), PIABKet(j))))---"), r"---(KroneckerDelta(i, j))---")
  expect_equal(.run(e, r"---(qcall(PIABBra(n), "dual_class"))---"), r"---(PIABKet)---")
})

test_that("test_printing: test_anticommutator", {
  e <- .new(c(r"---(MutableDenseMatrix <- "MutableDenseMatrix")---", r"---(ENV <- .qdict(list(), list()))---"), 'test_printing')
  .do(e, r"---(A <- Operator("A"))---")
  .do(e, r"---(B <- Operator("B"))---")
  .do(e, r"---(ac <- AntiCommutator(A, B))---")
  .do(e, r"---(ac_tall <- AntiCommutator((A ^ S(2)), B))---")
  expect_equal(.run(e, r"---(sstr(ac))---"), r"---({A,B})---")
  expect_equal(.run(e, r"---(latex(ac))---"), r"---(\left\{A,B\right\})---")
  expect_equal(.run(e, r"---(srepr(ac))---"), r"---(AntiCommutator(Operator(Symbol('A')),Operator(Symbol('B'))))---")
  expect_equal(.run(e, r"---(sstr(ac_tall))---"), r"---({A^2,B})---")
  .do(e, r"---(ascii_str <- "/ 2  \\\n<A ,B>\n\\    /")---")
  .do(e, r"---(ucode_str <- "\u23a7 2  \u23ab\n\u23a8A ,B\u23ac\n\u23a9    \u23ad")---")
  expect_equal(.run(e, r"---(latex(ac_tall))---"), r"---(\left\{A^{2},B\right\})---")
  expect_equal(.run(e, r"---(srepr(ac_tall))---"), r"---(AntiCommutator(Pow(Operator(Symbol('A')), Integer(2)),Operator(Symbol('B'))))---")
})

test_that("test_printing: test_cg", {
  e <- .new(c(r"---(MutableDenseMatrix <- "MutableDenseMatrix")---", r"---(ENV <- .qdict(list(), list()))---"), 'test_printing')
  .do(e, r"---(cg <- CG(S(1), S(2), S(3), S(4), S(5), S(6)))---")
  .do(e, r"---(wigner3j <- Wigner3j(S(1), S(2), S(3), S(4), S(5), S(6)))---")
  .do(e, r"---(wigner6j <- Wigner6j(S(1), S(2), S(3), S(4), S(5), S(6)))---")
  .do(e, r"---(wigner9j <- Wigner9j(S(1), S(2), S(3), S(4), S(5), S(6), S(7), S(8), S(9)))---")
  expect_equal(.run(e, r"---(sstr(cg))---"), r"---(CG(1, 2, 3, 4, 5, 6))---")
  .do(e, r"---(ascii_str <- " 5,6    \nC       \n 1,2,3,4")---")
  .do(e, r"---(ucode_str <- " 5,6    \nC       \n 1,2,3,4")---")
  expect_equal(.run(e, r"---(latex(cg))---"), r"---(C^{5,6}_{1,2,3,4})---")
  expect_equal(.run(e, r"---(latex((cg ^ S(2))))---"), r"---(\left(C^{5,6}_{1,2,3,4}\right)^{2})---")
  expect_equal(.run(e, r"---(srepr(cg))---"), r"---(CG(Integer(1), Integer(2), Integer(3), Integer(4), Integer(5), Integer(6)))---")
  expect_equal(.run(e, r"---(sstr(wigner3j))---"), r"---(Wigner3j(1, 2, 3, 4, 5, 6))---")
  .do(e, r"---(ascii_str <- "/1  3  5\\\n|       |\n\\2  4  6/")---")
  .do(e, r"---(ucode_str <- "\u239b1  3  5\u239e\n\u239c       \u239f\n\u239d2  4  6\u23a0")---")
  expect_equal(.run(e, r"---(latex(wigner3j))---"), r"---(\left(\begin{array}{ccc} 1 & 3 & 5 \\ 2 & 4 & 6 \end{array}\right))---")
  expect_equal(.run(e, r"---(srepr(wigner3j))---"), r"---(Wigner3j(Integer(1), Integer(2), Integer(3), Integer(4), Integer(5), Integer(6)))---")
  expect_equal(.run(e, r"---(sstr(wigner6j))---"), r"---(Wigner6j(1, 2, 3, 4, 5, 6))---")
  .do(e, r"---(ascii_str <- "/1  2  3\\\n<       >\n\\4  5  6/")---")
  .do(e, r"---(ucode_str <- "\u23a71  2  3\u23ab\n\u23a8       \u23ac\n\u23a94  5  6\u23ad")---")
  expect_equal(.run(e, r"---(latex(wigner6j))---"), r"---(\left\{\begin{array}{ccc} 1 & 2 & 3 \\ 4 & 5 & 6 \end{array}\right\})---")
  expect_equal(.run(e, r"---(srepr(wigner6j))---"), r"---(Wigner6j(Integer(1), Integer(2), Integer(3), Integer(4), Integer(5), Integer(6)))---")
  expect_equal(.run(e, r"---(sstr(wigner9j))---"), r"---(Wigner9j(1, 2, 3, 4, 5, 6, 7, 8, 9))---")
  .do(e, r"---(ascii_str <- "/1  2  3\\\n|       |\n<4  5  6>\n|       |\n\\7  8  9/")---")
  .do(e, r"---(ucode_str <- "\u23a71  2  3\u23ab\n\u23aa       \u23aa\n\u23a84  5  6\u23ac\n\u23aa       \u23aa\n\u23a97  8  9\u23ad")---")
  expect_equal(.run(e, r"---(latex(wigner9j))---"), r"---(\left\{\begin{array}{ccc} 1 & 2 & 3 \\ 4 & 5 & 6 \\ 7 & 8 & 9 \end{array}\right\})---")
  expect_equal(.run(e, r"---(srepr(wigner9j))---"), r"---(Wigner9j(Integer(1), Integer(2), Integer(3), Integer(4), Integer(5), Integer(6), Integer(7), Integer(8), Integer(9)))---")
})

test_that("test_printing: test_commutator", {
  e <- .new(c(r"---(MutableDenseMatrix <- "MutableDenseMatrix")---", r"---(ENV <- .qdict(list(), list()))---"), 'test_printing')
  .do(e, r"---(A <- Operator("A"))---")
  .do(e, r"---(B <- Operator("B"))---")
  .do(e, r"---(v_c <- Commutator(A, B))---")
  .do(e, r"---(c_tall <- Commutator((A ^ S(2)), B))---")
  expect_equal(.run(e, r"---(sstr(v_c))---"), r"---([A,B])---")
  expect_equal(.run(e, r"---(latex(v_c))---"), r"---(\left[A,B\right])---")
  expect_equal(.run(e, r"---(srepr(v_c))---"), r"---(Commutator(Operator(Symbol('A')),Operator(Symbol('B'))))---")
  expect_equal(.run(e, r"---(sstr(c_tall))---"), r"---([A^2,B])---")
  .do(e, r"---(ascii_str <- "[ 2  ]\n[A ,B]")---")
  .do(e, r"---(ucode_str <- "\u23a1 2  \u23a4\n\u23a3A ,B\u23a6")---")
  expect_equal(.run(e, r"---(latex(c_tall))---"), r"---(\left[A^{2},B\right])---")
  expect_equal(.run(e, r"---(srepr(c_tall))---"), r"---(Commutator(Pow(Operator(Symbol('A')), Integer(2)),Operator(Symbol('B'))))---")
})

