test_that("test_printing: test_dagger", {
  e <- .new(c(r"---(MutableDenseMatrix <- "MutableDenseMatrix")---", r"---(ENV <- .qdict(list(), list()))---"), 'test_printing')
  .do(e, r"---(x <- sym_symbols("x", commutative = FALSE))---")
  .do(e, r"---(expr <- Dagger(x))---")
  expect_equal(.run(e, r"---(sstr(expr))---"), r"---(Dagger(x))---")
  .do(e, r"---(ascii_str <- " +\nx ")---")
  .do(e, r"---(ucode_str <- " \u2020\nx ")---")
  expect_equal(.run(e, r"---(latex(expr))---"), r"---(x^{\dagger})---")
