test_that("test_printing: test_gate", {
  e <- .new(c(r"---(MutableDenseMatrix <- "MutableDenseMatrix")---", r"---(ENV <- .qdict(list(), list()))---"), 'test_printing')
  .do(e, r"---(.tmp <- sym_symbols("a,b,c,d"))---")
  .do(e, r"---(a <- .tmp[[1]])---")
  .do(e, r"---(b <- .tmp[[2]])---")
  .do(e, r"---(v_c <- .tmp[[3]])---")
  .do(e, r"---(d <- .tmp[[4]])---")
  .do(e, r"---(uMat <- Matrix(list(list(a, b), list(v_c, d))))---")
  .do(e, r"---(v_q <- Qubit(S(1), S(0), S(1), S(0), S(1)))---")
  .do(e, r"---(g1 <- IdentityGate(S(2)))---")
  .do(e, r"---(g2 <- CGate(list(S(3), S(0)), XGate(S(1))))---")
  .do(e, r"---(g3 <- CNotGate(S(1), S(0)))---")
  .do(e, r"---(g4 <- UGate(list(S(0)), uMat))---")
  expect_equal(.run(e, r"---(sstr(g1))---"), r"---(1(2))---")
  expect_equal(.run(e, r"---(latex(g1))---"), r"---(1_{2})---")
  expect_equal(.run(e, r"---(srepr(g1))---"), r"---(IdentityGate(Integer(2)))---")
  expect_equal(.run(e, r"---(sstr(.pymul(g1, v_q)))---"), r"---(1(2)*|10101>)---")
  .do(e, r"---(ascii_str <- "1 *|10101>\n 2        ")---")
  .do(e, r"---(ucode_str <- "1 \u22c5\u275810101\u27e9\n 2        ")---")
  expect_equal(.run(e, r"---(latex(.pymul(g1, v_q)))---"), r"---(1_{2} {\left|10101\right\rangle })---")
  expect_equal(.run(e, r"---(srepr(.pymul(g1, v_q)))---"), r"---(Mul(IdentityGate(Integer(2)), Qubit(Integer(1),Integer(0),Integer(1),Integer(0),Integer(1))))---")
  expect_equal(.run(e, r"---(sstr(g2))---"), r"---(C((3,0),X(1)))---")
  .do(e, r"---(ascii_str <- "C   /X \\\n 3,0\\ 1/")---")
  .do(e, r"---(ucode_str <- "C   \u239bX \u239e\n 3,0\u239d 1\u23a0")---")
  expect_equal(.run(e, r"---(latex(g2))---"), r"---(C_{3,0}{\left(X_{1}\right)})---")
  expect_equal(.run(e, r"---(srepr(g2))---"), r"---(CGate(Tuple(Integer(3), Integer(0)),XGate(Integer(1))))---")
  expect_equal(.run(e, r"---(sstr(g3))---"), r"---(CNOT(1,0))---")
  .do(e, r"---(ascii_str <- "CNOT   \n    1,0")---")
  .do(e, r"---(ucode_str <- "CNOT   \n    1,0")---")
  expect_equal(.run(e, r"---(latex(g3))---"), r"---(\text{CNOT}_{1,0})---")
  expect_equal(.run(e, r"---(srepr(g3))---"), r"---(CNotGate(Integer(1),Integer(0)))---")
  .do(e, r"---(ascii_str <- "U \n 0")---")
  .do(e, r"---(ucode_str <- "U \n 0")---")
  expect_equal(.run(e, r"---(sstr(g4))---"), r"---(U((0,),Matrix([
[a, b],
[c, d]])))---")
  expect_equal(.run(e, r"---(latex(g4))---"), r"---(U_{0})---")
  expect_equal(.run(e, r"---(srepr(g4))---"), r"---(UGate(Tuple(Integer(0)),ImmutableDenseMatrix([[Symbol('a'), Symbol('b')], [Symbol('c'), Symbol('d')]])))---")
})

test_that("test_printing: test_hilbert", {
  e <- .new(c(r"---(MutableDenseMatrix <- "MutableDenseMatrix")---", r"---(ENV <- .qdict(list(), list()))---"), 'test_printing')
  .do(e, r"---(h1 <- HilbertSpace())---")
  .do(e, r"---(h2 <- ComplexSpace(S(2)))---")
  .do(e, r"---(h3 <- FockSpace())---")
  .do(e, r"---(h4 <- L2(Interval(S(0), oo)))---")
  expect_equal(.run(e, r"---(sstr(h1))---"), r"---(H)---")
  expect_equal(.run(e, r"---(latex(h1))---"), r"---(\mathcal{H})---")
  expect_equal(.run(e, r"---(srepr(h1))---"), r"---(HilbertSpace())---")
  expect_equal(.run(e, r"---(sstr(h2))---"), r"---(C(2))---")
  .do(e, r"---(ascii_str <- " 2\nC ")---")
  .do(e, r"---(ucode_str <- " 2\nC ")---")
  expect_equal(.run(e, r"---(latex(h2))---"), r"---(\mathcal{C}^{2})---")
  expect_equal(.run(e, r"---(srepr(h2))---"), r"---(ComplexSpace(Integer(2)))---")
  expect_equal(.run(e, r"---(sstr(h3))---"), r"---(F)---")
  expect_equal(.run(e, r"---(latex(h3))---"), r"---(\mathcal{F})---")
  expect_equal(.run(e, r"---(srepr(h3))---"), r"---(FockSpace())---")
  expect_equal(.run(e, r"---(sstr(h4))---"), r"---(L2(Interval(0, oo)))---")
  .do(e, r"---(ascii_str <- " 2\nL ")---")
  .do(e, r"---(ucode_str <- " 2\nL ")---")
  expect_equal(.run(e, r"---(latex(h4))---"), r"---({\mathcal{L}^2}\left( \left[0, \infty\right) \right))---")
  expect_equal(.run(e, r"---(srepr(h4))---"), r"---(L2(Interval(Integer(0), oo, false, true)))---")
  expect_equal(.run(e, r"---(sstr((h1 + h2)))---"), r"---(H+C(2))---")
  .do(e, r"---(ascii_str <- "     2\nH + C ")---")
  .do(e, r"---(ucode_str <- "     2\nH \u2295 C ")---")
  expect_equal(.run(e, r"---(latex((h1 + h2)))---"), r"---(\mathcal{H}\oplus \mathcal{C}^{2})---")
  expect_equal(.run(e, r"---(srepr((h1 + h2)))---"), r"---(DirectSumHilbertSpace(HilbertSpace(),ComplexSpace(Integer(2))))---")
  expect_equal(.run(e, r"---(sstr(.pymul(h1, h2)))---"), r"---(H*C(2))---")
  .do(e, r"---(ascii_str <- "     2\nH x C ")---")
  .do(e, r"---(ucode_str <- "     2\nH \u2a02 C ")---")
  expect_equal(.run(e, r"---(latex(.pymul(h1, h2)))---"), r"---(\mathcal{H}\otimes \mathcal{C}^{2})---")
  expect_equal(.run(e, r"---(srepr(.pymul(h1, h2)))---"), r"---(TensorProductHilbertSpace(HilbertSpace(),ComplexSpace(Integer(2))))---")
  expect_equal(.run(e, r"---(sstr((h1 ^ S(2))))---"), r"---(H^2)---")
  .do(e, r"---(ascii_str <- " x2\nH  ")---")
  .do(e, r"---(ucode_str <- " \u2a022\nH  ")---")
  expect_equal(.run(e, r"---(latex((h1 ^ S(2))))---"), r"---({\mathcal{H}}^{\otimes 2})---")
  expect_equal(.run(e, r"---(srepr((h1 ^ S(2))))---"), r"---(TensorPowerHilbertSpace(HilbertSpace(),Integer(2)))---")
})

test_that("test_printing: test_innerproduct", {
  e <- .new(c(r"---(MutableDenseMatrix <- "MutableDenseMatrix")---", r"---(ENV <- .qdict(list(), list()))---"), 'test_printing')
  .do(e, r"---(x <- sym_symbols("x"))---")
  .do(e, r"---(ip1 <- InnerProduct(Bra(), Ket()))---")
  .do(e, r"---(ip2 <- InnerProduct(TimeDepBra(), TimeDepKet()))---")
  .do(e, r"---(ip3 <- InnerProduct(JzBra(S(1), S(1)), JzKet(S(1), S(1))))---")
  .do(e, r"---(ip4 <- InnerProduct(JzBraCoupled(S(1), S(1), list(S(1), S(1))), JzKetCoupled(S(1), S(1), list(S(1), S(1)))))---")
  .do(e, r"---(ip_tall1 <- InnerProduct(Bra((x / S(2))), Ket((x / S(2)))))---")
  .do(e, r"---(ip_tall2 <- InnerProduct(Bra(x), Ket((x / S(2)))))---")
  .do(e, r"---(ip_tall3 <- InnerProduct(Bra((x / S(2))), Ket(x)))---")
  expect_equal(.run(e, r"---(sstr(ip1))---"), r"---(<psi|psi>)---")
  expect_equal(.run(e, r"---(latex(ip1))---"), r"---(\left\langle \psi \right. {\left|\psi\right\rangle })---")
  expect_equal(.run(e, r"---(srepr(ip1))---"), r"---(InnerProduct(Bra(Symbol('psi')),Ket(Symbol('psi'))))---")
  expect_equal(.run(e, r"---(sstr(ip2))---"), r"---(<psi;t|psi;t>)---")
  expect_equal(.run(e, r"---(latex(ip2))---"), r"---(\left\langle \psi;t \right. {\left|\psi;t\right\rangle })---")
  expect_equal(.run(e, r"---(srepr(ip2))---"), r"---(InnerProduct(TimeDepBra(Symbol('psi'),Symbol('t')),TimeDepKet(Symbol('psi'),Symbol('t'))))---")
  expect_equal(.run(e, r"---(sstr(ip3))---"), r"---(<1,1|1,1>)---")
  expect_equal(.run(e, r"---(latex(ip3))---"), r"---(\left\langle 1,1 \right. {\left|1,1\right\rangle })---")
  expect_equal(.run(e, r"---(srepr(ip3))---"), r"---(InnerProduct(JzBra(Integer(1),Integer(1)),JzKet(Integer(1),Integer(1))))---")
  expect_equal(.run(e, r"---(sstr(ip4))---"), r"---(<1,1,j1=1,j2=1|1,1,j1=1,j2=1>)---")
  expect_equal(.run(e, r"---(latex(ip4))---"), r"---(\left\langle 1,1,j_{1}=1,j_{2}=1 \right. {\left|1,1,j_{1}=1,j_{2}=1\right\rangle })---")
  expect_equal(.run(e, r"---(srepr(ip4))---"), r"---(InnerProduct(JzBraCoupled(Integer(1),Integer(1),Tuple(Integer(1), Integer(1)),Tuple(Tuple(Integer(1), Integer(2), Integer(1)))),JzKetCoupled(Integer(1),Integer(1),Tuple(Integer(1), Integer(1)),Tuple(Tuple(Integer(1), Integer(2), Integer(1))))))---")
  expect_equal(.run(e, r"---(sstr(ip_tall1))---"), r"---(<x/2|x/2>)---")
  .do(e, r"---(ascii_str <- " / | \\ \n/ x|x \\\n\\ -|- /\n \\2|2/ ")---")
  .do(e, r"---(ucode_str <- " \u2571 \u2502 \u2572 \n\u2571 x\u2502x \u2572\n\u2572 \u2500\u2502\u2500 \u2571\n \u25722\u25022\u2571 ")---")
  expect_equal(.run(e, r"---(latex(ip_tall1))---"), r"---(\left\langle \frac{x}{2} \right. {\left|\frac{x}{2}\right\rangle })---")
  expect_equal(.run(e, r"---(srepr(ip_tall1))---"), r"---(InnerProduct(Bra(Mul(Rational(1, 2), Symbol('x'))),Ket(Mul(Rational(1, 2), Symbol('x')))))---")
  expect_equal(.run(e, r"---(sstr(ip_tall2))---"), r"---(<x|x/2>)---")
  .do(e, r"---(ascii_str <- " / | \\ \n/  |x \\\n\\ x|- /\n \\ |2/ ")---")
  .do(e, r"---(ucode_str <- " \u2571 \u2502 \u2572 \n\u2571  \u2502x \u2572\n\u2572 x\u2502\u2500 \u2571\n \u2572 \u25022\u2571 ")---")
  expect_equal(.run(e, r"---(latex(ip_tall2))---"), r"---(\left\langle x \right. {\left|\frac{x}{2}\right\rangle })---")
  expect_equal(.run(e, r"---(srepr(ip_tall2))---"), r"---(InnerProduct(Bra(Symbol('x')),Ket(Mul(Rational(1, 2), Symbol('x')))))---")
  expect_equal(.run(e, r"---(sstr(ip_tall3))---"), r"---(<x/2|x>)---")
  .do(e, r"---(ascii_str <- " / | \\ \n/ x|  \\\n\\ -|x /\n \\2| / ")---")
  .do(e, r"---(ucode_str <- " \u2571 \u2502 \u2572 \n\u2571 x\u2502  \u2572\n\u2572 \u2500\u2502x \u2571\n \u25722\u2502 \u2571 ")---")
  expect_equal(.run(e, r"---(latex(ip_tall3))---"), r"---(\left\langle \frac{x}{2} \right. {\left|x\right\rangle })---")
  expect_equal(.run(e, r"---(srepr(ip_tall3))---"), r"---(InnerProduct(Bra(Mul(Rational(1, 2), Symbol('x'))),Ket(Symbol('x'))))---")
})

test_that("test_printing: test_operator", {
  e <- .new(c(r"---(MutableDenseMatrix <- "MutableDenseMatrix")---", r"---(ENV <- .qdict(list(), list()))---"), 'test_printing')
  .do(e, r"---(a <- Operator("A"))---")
  .do(e, r"---(b <- Operator("B", Symbol("t"), S_Half))---")
  .do(e, r"---(inv <- qcall(a, "inv"))---")
  .do(e, r"---(f <- Function("f"))---")
  .do(e, r"---(x <- sym_symbols("x"))---")
  .do(e, r"---(d <- DifferentialOperator(Derivative(.qcallobj(f, x), x), .qcallobj(f, x)))---")
  .do(e, r"---(op <- OuterProduct(Ket(), Bra()))---")
  expect_equal(.run(e, r"---(sstr(a))---"), r"---(A)---")
  expect_equal(.run(e, r"---(latex(a))---"), r"---(A)---")
  expect_equal(.run(e, r"---(srepr(a))---"), r"---(Operator(Symbol('A')))---")
  expect_equal(.run(e, r"---(sstr(inv))---"), r"---(A^(-1))---")
  .do(e, r"---(ascii_str <- " -1\nA  ")---")
  .do(e, r"---(ucode_str <- " -1\nA  ")---")
  expect_equal(.run(e, r"---(latex(inv))---"), r"---(A^{-1})---")
  expect_equal(.run(e, r"---(srepr(inv))---"), r"---(Pow(Operator(Symbol('A')), Integer(-1)))---")
  expect_equal(.run(e, r"---(sstr(d))---"), r"---(DifferentialOperator(Derivative(f(x), x),f(x)))---")
  .do(e, r"---(ascii_str <- "                    /d            \\\nDifferentialOperator|--(f(x)),f(x)|\n                    \\dx           /")---")
  .do(e, r"---(ucode_str <- "                    \u239bd            \u239e\nDifferentialOperator\u239c\u2500\u2500(f(x)),f(x)\u239f\n                    \u239ddx           \u23a0")---")
  expect_equal(.run(e, r"---(latex(d))---"), r"---(DifferentialOperator\left(\frac{d}{d x} f{\left(x \right)},f{\left(x \right)}\right))---")
  expect_equal(.run(e, r"---(srepr(d))---"), r"---(DifferentialOperator(Derivative(Function('f')(Symbol('x')), Tuple(Symbol('x'), Integer(1))),Function('f')(Symbol('x'))))---")
  expect_equal(.run(e, r"---(sstr(b))---"), r"---(Operator(B,t,1/2))---")
  expect_equal(.run(e, r"---(latex(b))---"), r"---(Operator\left(B,t,\frac{1}{2}\right))---")
  expect_equal(.run(e, r"---(srepr(b))---"), r"---(Operator(Symbol('B'),Symbol('t'),Rational(1, 2)))---")
  expect_equal(.run(e, r"---(sstr(op))---"), r"---(|psi><psi|)---")
  expect_equal(.run(e, r"---(latex(op))---"), r"---({\left|\psi\right\rangle }{\left\langle \psi\right|})---")
  expect_equal(.run(e, r"---(srepr(op))---"), r"---(OuterProduct(Ket(Symbol('psi')),Bra(Symbol('psi'))))---")
})

