test_that("test_printing: test_spin", {
  e <- .new(c(r"---(MutableDenseMatrix <- "MutableDenseMatrix")---", r"---(ENV <- .qdict(list(), list()))---"), 'test_printing')
  .do(e, r"---(lz <- JzOp("L"))---")
  .do(e, r"---(ket <- JzKet(S(1), S(0)))---")
  .do(e, r"---(bra <- JzBra(S(1), S(0)))---")
  .do(e, r"---(cket <- JzKetCoupled(S(1), S(0), list(S(1), S(2))))---")
  .do(e, r"---(cbra <- JzBraCoupled(S(1), S(0), list(S(1), S(2))))---")
  .do(e, r"---(cket_big <- JzKetCoupled(S(1), S(0), list(S(1), S(2), S(3))))---")
  .do(e, r"---(cbra_big <- JzBraCoupled(S(1), S(0), list(S(1), S(2), S(3))))---")
  .do(e, r"---(rot <- Rotation(S(1), S(2), S(3)))---")
  .do(e, r"---(bigd <- WignerD(S(1), S(2), S(3), S(4), S(5), S(6)))---")
  .do(e, r"---(smalld <- WignerD(S(1), S(2), S(3), S(0), S(4), S(0)))---")
  expect_equal(.run(e, r"---(sstr(lz))---"), r"---(Lz)---")
  .do(e, r"---(ascii_str <- "L \n z")---")
  .do(e, r"---(ucode_str <- "L \n z")---")
  expect_equal(.run(e, r"---(latex(lz))---"), r"---(L_z)---")
  expect_equal(.run(e, r"---(srepr(lz))---"), r"---(JzOp(Symbol('L')))---")
  expect_equal(.run(e, r"---(sstr(J2Op(Symbol("J"))))---"), r"---(J2)---")
  .do(e, r"---(ascii_str <- " 2\nJ ")---")
  .do(e, r"---(ucode_str <- " 2\nJ ")---")
  expect_equal(.run(e, r"---(latex(J2Op(Symbol("J"))))---"), r"---(J^2)---")
  expect_equal(.run(e, r"---(srepr(J2Op(Symbol("J"))))---"), r"---(J2Op(Symbol('J')))---")
  expect_equal(.run(e, r"---(sstr(JzOp(Symbol("J"))))---"), r"---(Jz)---")
  .do(e, r"---(ascii_str <- "J \n z")---")
  .do(e, r"---(ucode_str <- "J \n z")---")
  expect_equal(.run(e, r"---(latex(JzOp(Symbol("J"))))---"), r"---(J_z)---")
  expect_equal(.run(e, r"---(srepr(JzOp(Symbol("J"))))---"), r"---(JzOp(Symbol('J')))---")
  expect_equal(.run(e, r"---(sstr(ket))---"), r"---(|1,0>)---")
  expect_equal(.run(e, r"---(latex(ket))---"), r"---({\left|1,0\right\rangle })---")
  expect_equal(.run(e, r"---(srepr(ket))---"), r"---(JzKet(Integer(1),Integer(0)))---")
  expect_equal(.run(e, r"---(sstr(bra))---"), r"---(<1,0|)---")
  expect_equal(.run(e, r"---(latex(bra))---"), r"---({\left\langle 1,0\right|})---")
  expect_equal(.run(e, r"---(srepr(bra))---"), r"---(JzBra(Integer(1),Integer(0)))---")
  expect_equal(.run(e, r"---(sstr(cket))---"), r"---(|1,0,j1=1,j2=2>)---")
  expect_equal(.run(e, r"---(latex(cket))---"), r"---({\left|1,0,j_{1}=1,j_{2}=2\right\rangle })---")
  expect_equal(.run(e, r"---(srepr(cket))---"), r"---(JzKetCoupled(Integer(1),Integer(0),Tuple(Integer(1), Integer(2)),Tuple(Tuple(Integer(1), Integer(2), Integer(1)))))---")
  expect_equal(.run(e, r"---(sstr(cbra))---"), r"---(<1,0,j1=1,j2=2|)---")
  expect_equal(.run(e, r"---(latex(cbra))---"), r"---({\left\langle 1,0,j_{1}=1,j_{2}=2\right|})---")
  expect_equal(.run(e, r"---(srepr(cbra))---"), r"---(JzBraCoupled(Integer(1),Integer(0),Tuple(Integer(1), Integer(2)),Tuple(Tuple(Integer(1), Integer(2), Integer(1)))))---")
  expect_equal(.run(e, r"---(sstr(cket_big))---"), r"---(|1,0,j1=1,j2=2,j3=3,j(1,2)=3>)---")
  expect_equal(.run(e, r"---(latex(cket_big))---"), r"---({\left|1,0,j_{1}=1,j_{2}=2,j_{3}=3,j_{1,2}=3\right\rangle })---")
  expect_equal(.run(e, r"---(srepr(cket_big))---"), r"---(JzKetCoupled(Integer(1),Integer(0),Tuple(Integer(1), Integer(2), Integer(3)),Tuple(Tuple(Integer(1), Integer(2), Integer(3)), Tuple(Integer(1), Integer(3), Integer(1)))))---")
  expect_equal(.run(e, r"---(sstr(cbra_big))---"), r"---(<1,0,j1=1,j2=2,j3=3,j(1,2)=3|)---")
  expect_equal(.run(e, r"---(latex(cbra_big))---"), r"---({\left\langle 1,0,j_{1}=1,j_{2}=2,j_{3}=3,j_{1,2}=3\right|})---")
  expect_equal(.run(e, r"---(srepr(cbra_big))---"), r"---(JzBraCoupled(Integer(1),Integer(0),Tuple(Integer(1), Integer(2), Integer(3)),Tuple(Tuple(Integer(1), Integer(2), Integer(3)), Tuple(Integer(1), Integer(3), Integer(1)))))---")
  expect_equal(.run(e, r"---(sstr(rot))---"), r"---(R(1,2,3))---")
  expect_equal(.run(e, r"---(latex(rot))---"), r"---(\mathcal{R}\left(1,2,3\right))---")
  expect_equal(.run(e, r"---(srepr(rot))---"), r"---(Rotation(Integer(1),Integer(2),Integer(3)))---")
  expect_equal(.run(e, r"---(sstr(bigd))---"), r"---(WignerD(1, 2, 3, 4, 5, 6))---")
  .do(e, r"---(ascii_str <- " 1         \nD   (4,5,6)\n 2,3       ")---")
  .do(e, r"---(ucode_str <- " 1         \nD   (4,5,6)\n 2,3       ")---")
  expect_equal(.run(e, r"---(latex(bigd))---"), r"---(D^{1}_{2,3}\left(4,5,6\right))---")
  expect_equal(.run(e, r"---(srepr(bigd))---"), r"---(WignerD(Integer(1), Integer(2), Integer(3), Integer(4), Integer(5), Integer(6)))---")
  expect_equal(.run(e, r"---(sstr(smalld))---"), r"---(WignerD(1, 2, 3, 0, 4, 0))---")
  .do(e, r"---(ascii_str <- " 1     \nd   (4)\n 2,3   ")---")
  .do(e, r"---(ucode_str <- " 1     \nd   (4)\n 2,3   ")---")
  expect_equal(.run(e, r"---(latex(smalld))---"), r"---(d^{1}_{2,3}\left(4\right))---")
  expect_equal(.run(e, r"---(srepr(smalld))---"), r"---(WignerD(Integer(1), Integer(2), Integer(3), Integer(0), Integer(4), Integer(0)))---")
})

test_that("test_printing: test_state", {
  e <- .new(c(r"---(MutableDenseMatrix <- "MutableDenseMatrix")---", r"---(ENV <- .qdict(list(), list()))---"), 'test_printing')
  .do(e, r"---(x <- sym_symbols("x"))---")
  .do(e, r"---(bra <- Bra())---")
  .do(e, r"---(ket <- Ket())---")
  .do(e, r"---(bra_tall <- Bra((x / S(2))))---")
  .do(e, r"---(ket_tall <- Ket((x / S(2))))---")
  .do(e, r"---(tbra <- TimeDepBra())---")
  .do(e, r"---(tket <- TimeDepKet())---")
  expect_equal(.run(e, r"---(sstr(bra))---"), r"---(<psi|)---")
  expect_equal(.run(e, r"---(latex(bra))---"), r"---({\left\langle \psi\right|})---")
  expect_equal(.run(e, r"---(srepr(bra))---"), r"---(Bra(Symbol('psi')))---")
  expect_equal(.run(e, r"---(sstr(ket))---"), r"---(|psi>)---")
  expect_equal(.run(e, r"---(latex(ket))---"), r"---({\left|\psi\right\rangle })---")
  expect_equal(.run(e, r"---(srepr(ket))---"), r"---(Ket(Symbol('psi')))---")
  expect_equal(.run(e, r"---(sstr(bra_tall))---"), r"---(<x/2|)---")
  .do(e, r"---(ascii_str <- " / |\n/ x|\n\\ -|\n \\2|")---")
  .do(e, r"---(ucode_str <- " \u2571 \u2502\n\u2571 x\u2502\n\u2572 \u2500\u2502\n \u25722\u2502")---")
  expect_equal(.run(e, r"---(latex(bra_tall))---"), r"---({\left\langle \frac{x}{2}\right|})---")
  expect_equal(.run(e, r"---(srepr(bra_tall))---"), r"---(Bra(Mul(Rational(1, 2), Symbol('x'))))---")
  expect_equal(.run(e, r"---(sstr(ket_tall))---"), r"---(|x/2>)---")
  .do(e, r"---(ascii_str <- "| \\ \n|x \\\n|- /\n|2/ ")---")
  .do(e, r"---(ucode_str <- "\u2502 \u2572 \n\u2502x \u2572\n\u2502\u2500 \u2571\n\u25022\u2571 ")---")
  expect_equal(.run(e, r"---(latex(ket_tall))---"), r"---({\left|\frac{x}{2}\right\rangle })---")
  expect_equal(.run(e, r"---(srepr(ket_tall))---"), r"---(Ket(Mul(Rational(1, 2), Symbol('x'))))---")
  expect_equal(.run(e, r"---(sstr(tbra))---"), r"---(<psi;t|)---")
  expect_equal(.run(e, r"---(latex(tbra))---"), r"---({\left\langle \psi;t\right|})---")
  expect_equal(.run(e, r"---(srepr(tbra))---"), r"---(TimeDepBra(Symbol('psi'),Symbol('t')))---")
  expect_equal(.run(e, r"---(sstr(tket))---"), r"---(|psi;t>)---")
  expect_equal(.run(e, r"---(latex(tket))---"), r"---({\left|\psi;t\right\rangle })---")
  expect_equal(.run(e, r"---(srepr(tket))---"), r"---(TimeDepKet(Symbol('psi'),Symbol('t')))---")
})

test_that("test_printing: test_tensorproduct", {
  e <- .new(c(r"---(MutableDenseMatrix <- "MutableDenseMatrix")---", r"---(ENV <- .qdict(list(), list()))---"), 'test_printing')
