})

test_that("test_printing: test_big_expr", {
  e <- .new(c(r"---(MutableDenseMatrix <- "MutableDenseMatrix")---", r"---(ENV <- .qdict(list(), list()))---"), 'test_printing')
  .do(e, r"---(f <- Function("f"))---")
  .do(e, r"---(x <- sym_symbols("x"))---")
  .do(e, r"---(e1 <- .pymul(.pymul(Dagger(.pymul(AntiCommutator((Operator("A") + Operator("B")), Pow(DifferentialOperator(Derivative(.qcallobj(f, x), x), .qcallobj(f, x)), S(3))), TensorProduct((JzOp(Symbol("J")) ^ S(2)), (Operator("A") + Operator("B"))))), (JzBra(S(1), S(0)) + JzBra(S(1), S(1)))), (JzKet(S(0), S(0)) + JzKet(S(1), S(-1)))))---")
  .do(e, r"---(e2 <- .pymul(.pymul(Commutator((JzOp(Symbol("J")) ^ S(2)), (Operator("A") + Operator("B"))), AntiCommutator(Dagger(.pymul(Operator("C"), Operator("D"))), (qcall(Operator("E"), "inv") ^ S(2)))), Dagger(Commutator(JzOp(Symbol("J")), J2Op(Symbol("J"))))))---")
  .do(e, r"---(e3 <- .pymul(.pymul(.pymul(Wigner3j(S(1), S(2), S(3), S(4), S(5), S(6)), TensorProduct(Commutator((Operator("A") + Dagger(Operator("B"))), (Operator("C") + Operator("D"))), (JzOp(Symbol("J")) - J2Op(Symbol("J"))))), Dagger(OuterProduct(Dagger(JzBra(S(1), S(1))), JzBra(S(1), S(0))))), TensorProduct((JzKetCoupled(S(1), S(1), list(S(1), S(1))) + JzKetCoupled(S(1), S(0), list(S(1), S(1)))), JzKetCoupled(S(1), S(-1), list(S(1), S(1))))))---")
  .do(e, r"---(e4 <- .pymul((.pymul(ComplexSpace(S(1)), ComplexSpace(S(2))) + (FockSpace() ^ S(2))), (L2(Interval(S(0), oo)) + HilbertSpace())))---")
  expect_equal(.run(e, r"---(sstr(e1))---"), r"---((Jz^2)x(Dagger(A) + Dagger(B))*{Dagger(DifferentialOperator(Derivative(f(x), x),f(x)))^3,Dagger(A) + Dagger(B)}*(<1,0| + <1,1|)*(|0,0> + |1,-1>))---")
  .do(e, r"---(ascii_str <- "                 /                                      3        \\                                 \n                 |/                                   +\\         |                                 \n    2  / +    +\\ <|                    /d            \\ |   +    +>                                 \n/J \\ x \\A  + B /*||DifferentialOperator|--(f(x)),f(x)| | ,A  + B |*(<1,0| + <1,1|)*(|0,0> + |1,-1>)\n\\ z/             \\\\                    \\dx           / /         /                                 ")---")
  .do(e, r"---(ucode_str <- "                 \u23a7                                      3        \u23ab                                 \n                 \u23aa\u239b                                   \u2020\u239e         \u23aa                                 \n    2  \u239b \u2020    \u2020\u239e \u23a8\u239c                    \u239bd            \u239e \u239f   \u2020    \u2020\u23ac                                 \n\u239bJ \u239e \u2a02 \u239dA  + B \u23a0\u22c5\u23aa\u239cDifferentialOperator\u239c\u2500\u2500(f(x)),f(x)\u239f \u239f ,A  + B \u23aa\u22c5(\u27e81,0\u2758 + \u27e81,1\u2758)\u22c5(\u27580,0\u27e9 + \u27581,-1\u27e9)\n\u239d z\u23a0             \u23a9\u239d                    \u239ddx           \u23a0 \u23a0         \u23ad                                 ")---")
  expect_equal(.run(e, r"---(latex(e1))---"), r"---({J_z^{2}}\otimes \left({A^{\dagger} + B^{\dagger}}\right) \left\{\left(DifferentialOperator\left(\frac{d}{d x} f{\left(x \right)},f{\left(x \right)}\right)^{\dagger}\right)^{3},A^{\dagger} + B^{\dagger}\right\} \left({\left\langle 1,0\right|} + {\left\langle 1,1\right|}\right) \left({\left|0,0\right\rangle } + {\left|1,-1\right\rangle }\right))---")
  expect_equal(.run(e, r"---(srepr(e1))---"), r"---(Mul(TensorProduct(Pow(JzOp(Symbol('J')), Integer(2)), Add(Dagger(Operator(Symbol('A'))), Dagger(Operator(Symbol('B'))))), AntiCommutator(Pow(Dagger(DifferentialOperator(Derivative(Function('f')(Symbol('x')), Tuple(Symbol('x'), Integer(1))),Function('f')(Symbol('x')))), Integer(3)),Add(Dagger(Operator(Symbol('A'))), Dagger(Operator(Symbol('B'))))), Add(JzBra(Integer(1),Integer(0)), JzBra(Integer(1),Integer(1))), Add(JzKet(Integer(0),Integer(0)), JzKet(Integer(1),Integer(-1)))))---")
  expect_equal(.run(e, r"---(sstr(e2))---"), r"---([Jz^2,A + B]*{E^(-2),Dagger(D)*Dagger(C)}*[J2,Jz])---")
  .do(e, r"---(ascii_str <- "[    2      ] / -2  +  +\\ [ 2   ]\n[/J \\ ,A + B]*<E  ,D *C >*[J ,J ]\n[\\ z/       ] \\         / [    z]")---")
  .do(e, r"---(ucode_str <- "\u23a1    2      \u23a4 \u23a7 -2  \u2020  \u2020\u23ab \u23a1 2   \u23a4\n\u23a2\u239bJ \u239e ,A + B\u23a5\u22c5\u23a8E  ,D \u22c5C \u23ac\u22c5\u23a2J ,J \u23a5\n\u23a3\u239d z\u23a0       \u23a6 \u23a9         \u23ad \u23a3    z\u23a6")---")
  expect_equal(.run(e, r"---(latex(e2))---"), r"---(\left[J_z^{2},A + B\right] \left\{E^{-2},D^{\dagger} C^{\dagger}\right\} \left[J^2,J_z\right])---")
  expect_equal(.run(e, r"---(srepr(e2))---"), r"---(Mul(Commutator(Pow(JzOp(Symbol('J')), Integer(2)),Add(Operator(Symbol('A')), Operator(Symbol('B')))), AntiCommutator(Pow(Operator(Symbol('E')), Integer(-2)),Mul(Dagger(Operator(Symbol('D'))), Dagger(Operator(Symbol('C'))))), Commutator(J2Op(Symbol('J')),JzOp(Symbol('J')))))---")
  expect_equal(.run(e, r"---(sstr(e3))---"), r"---(Wigner3j(1, 2, 3, 4, 5, 6)*[Dagger(B) + A,C + D]x(-J2 + Jz)*|1,0><1,1|*(|1,0,j1=1,j2=1> + |1,1,j1=1,j2=1>)x|1,-1,j1=1,j2=1>)---")
  .do(e, r"---(ascii_str <- "          [ +          ]  /   2     \\                                                                 \n/1  3  5\\*[B  + A,C + D]x |- J  + J |*|1,0><1,1|*(|1,0,j1=1,j2=1> + |1,1,j1=1,j2=1>)x |1,-1,j1=1,j2=1>\n|       |                 \\        z/                                                                 \n\\2  4  6/                                                                                             ")---")
  .do(e, r"---(ucode_str <- "          \u23a1 \u2020          \u23a4  \u239b   2     \u239e                                                                 \n\u239b1  3  5\u239e\u22c5\u23a3B  + A,C + D\u23a6\u2a02 \u239c- J  + J \u239f\u22c5\u27581,0\u27e9\u27e81,1\u2758\u22c5(\u27581,0,j\u2081=1,j\u2082=1\u27e9 + \u27581,1,j\u2081=1,j\u2082=1\u27e9)\u2a02 \u27581,-1,j\u2081=1,j\u2082=1\u27e9\n\u239c       \u239f                 \u239d        z\u23a0                                                                 \n\u239d2  4  6\u23a0                                                                                             ")---")
  expect_equal(.run(e, r"---(latex(e3))---"), r"---(\left(\begin{array}{ccc} 1 & 3 & 5 \\ 2 & 4 & 6 \end{array}\right) {\left[B^{\dagger} + A,C + D\right]}\otimes \left({- J^2 + J_z}\right) {\left|1,0\right\rangle }{\left\langle 1,1\right|} \left({{\left|1,0,j_{1}=1,j_{2}=1\right\rangle } + {\left|1,1,j_{1}=1,j_{2}=1\right\rangle }}\right)\otimes {{\left|1,-1,j_{1}=1,j_{2}=1\right\rangle }})---")
  expect_equal(.run(e, r"---(srepr(e3))---"), r"---(Mul(Wigner3j(Integer(1), Integer(2), Integer(3), Integer(4), Integer(5), Integer(6)), TensorProduct(Commutator(Add(Dagger(Operator(Symbol('B'))), Operator(Symbol('A'))),Add(Operator(Symbol('C')), Operator(Symbol('D')))), Add(Mul(Integer(-1), J2Op(Symbol('J'))), JzOp(Symbol('J')))), OuterProduct(JzKet(Integer(1),Integer(0)),JzBra(Integer(1),Integer(1))), TensorProduct(Add(JzKetCoupled(Integer(1),Integer(0),Tuple(Integer(1), Integer(1)),Tuple(Tuple(Integer(1), Integer(2), Integer(1)))), JzKetCoupled(Integer(1),Integer(1),Tuple(Integer(1), Integer(1)),Tuple(Tuple(Integer(1), Integer(2), Integer(1))))), JzKetCoupled(Integer(1),Integer(-1),Tuple(Integer(1), Integer(1)),Tuple(Tuple(Integer(1), Integer(2), Integer(1)))))))---")
  expect_equal(.run(e, r"---(sstr(e4))---"), r"---((C(1)*C(2)+F^2)*(L2(Interval(0, oo))+H))---")
  .do(e, r"---(ascii_str <- "// 1    2\\    x2\\   / 2    \\\n\\\\C  x C / + F  / x \\L  + H/")---")
  .do(e, r"---(ucode_str <- "\u239b\u239b 1    2\u239e    \u2a022\u239e   \u239b 2    \u239e\n\u239d\u239dC  \u2a02 C \u23a0 \u2295 F  \u23a0 \u2a02 \u239dL  \u2295 H\u23a0")---")
  expect_equal(.run(e, r"---(latex(e4))---"), r"---(\left(\left(\mathcal{C}^{1}\otimes \mathcal{C}^{2}\right)\oplus {\mathcal{F}}^{\otimes 2}\right)\otimes \left({\mathcal{L}^2}\left( \left[0, \infty\right) \right)\oplus \mathcal{H}\right))---")
  expect_equal(.run(e, r"---(srepr(e4))---"), r"---(TensorProductHilbertSpace((DirectSumHilbertSpace(TensorProductHilbertSpace(ComplexSpace(Integer(1)),ComplexSpace(Integer(2))),TensorPowerHilbertSpace(FockSpace(),Integer(2)))),(DirectSumHilbertSpace(L2(Interval(Integer(0), oo, false, true)),HilbertSpace()))))---")
})

test_that("test_qapply: test_basic", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j j' m m'"))---", r"---(j <- .tmp[[1]])---", r"---(jp <- .tmp[[2]])---", r"---(m <- .tmp[[3]])---", r"---(mp <- .tmp[[4]])---", r"---(z <- JzKet(S(1), S(0)))---", r"---(po <- JzKet(S(1), S(1)))---", r"---(mo <- JzKet(S(1), S(-1)))---", r"---(A <- Operator("A"))---"), 'test_qapply')
  expect_equal(.run(e, r"---(qapply(.pymul(JzOp(Symbol("J")), po)))---"), r"---(hbar*|1,1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JxOp(Symbol("J")), z)))---"), r"---(sqrt(2)*hbar*|1,-1>/2 + sqrt(2)*hbar*|1,1>/2)---")
  expect_equal(.run(e, r"---(qapply((.pymul((JplusOp(Symbol("J")) + JminusOp(Symbol("J"))), z) / sqrt(S(S(2))))))---"), r"---(hbar*|1,-1> + hbar*|1,1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JzOp(Symbol("J")), (po + mo))))---"), r"---(-hbar*|1,-1> + hbar*|1,1>)---")
  expect_equal(.run(e, r"---(qapply((.pymul(JzOp(Symbol("J")), po) + .pymul(JzOp(Symbol("J")), mo))))---"), r"---(-hbar*|1,-1> + hbar*|1,1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(.pymul(JminusOp(Symbol("J")), JminusOp(Symbol("J"))), po)))---"), r"---(2*hbar^2*|1,-1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul((JplusOp(Symbol("J")) ^ S(2)), mo)))---"), r"---(2*hbar^2*|1,1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(.pymul((JplusOp(Symbol("J")) ^ S(2)), (JminusOp(Symbol("J")) ^ S(2))), po)))---"), r"---(4*hbar^4*|1,1>)---")
})

test_that("test_qapply: test_extra", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j j' m m'"))---", r"---(j <- .tmp[[1]])---", r"---(jp <- .tmp[[2]])---", r"---(m <- .tmp[[3]])---", r"---(mp <- .tmp[[4]])---", r"---(z <- JzKet(S(1), S(0)))---", r"---(po <- JzKet(S(1), S(1)))---", r"---(mo <- JzKet(S(1), S(-1)))---", r"---(A <- Operator("A"))---"), 'test_qapply')
  .do(e, r"---(extra <- .pymul(.pymul(qattr(z, "dual"), A), z))---")
  expect_equal(.run(e, r"---(qapply(.pymul(.pymul(JzOp(Symbol("J")), po), extra)))---"), r"---(hbar*|1,1><1,0|*A*|1,0>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(.pymul(JxOp(Symbol("J")), z), extra)))---"), r"---((sqrt(2)*hbar*|1,-1>/2 + sqrt(2)*hbar*|1,1>/2)*<1,0|*A*|1,0>)---")
  expect_equal(.run(e, r"---(qapply(.pymul((.pymul((JplusOp(Symbol("J")) + JminusOp(Symbol("J"))), z) / sqrt(S(S(2)))), extra)))---"), r"---(hbar*|1,-1><1,0|*A*|1,0> + hbar*|1,1><1,0|*A*|1,0>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(.pymul(JzOp(Symbol("J")), (po + mo)), extra)))---"), r"---(-hbar*|1,-1><1,0|*A*|1,0> + hbar*|1,1><1,0|*A*|1,0>)---")
  expect_equal(.run(e, r"---(qapply((.pymul(.pymul(JzOp(Symbol("J")), po), extra) + .pymul(.pymul(JzOp(Symbol("J")), mo), extra))))---"), r"---(-hbar*|1,-1><1,0|*A*|1,0> + hbar*|1,1><1,0|*A*|1,0>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(.pymul(.pymul(JminusOp(Symbol("J")), JminusOp(Symbol("J"))), po), extra)))---"), r"---(2*hbar^2*|1,-1><1,0|*A*|1,0>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(.pymul((JplusOp(Symbol("J")) ^ S(2)), mo), extra)))---"), r"---(2*hbar^2*|1,1><1,0|*A*|1,0>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(.pymul(.pymul((JplusOp(Symbol("J")) ^ S(2)), (JminusOp(Symbol("J")) ^ S(2))), po), extra)))---"), r"---(4*hbar^4*|1,1><1,0|*A*|1,0>)---")
})

