  expect_equal(.run(e, r"---(qapply(.pymul(.pymul(Commutator(JxOp(Symbol("J")), JyOp(Symbol("J"))), JzOp(Symbol("J"))), po)))---"), r"---(hbar^3*I*|1,1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(.pymul(Commutator(J2Op(Symbol("J")), JzOp(Symbol("J"))), JzOp(Symbol("J"))), po)))---"), r"---(0)---")
