test_that("test_qapply: test_outerproduct", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j j' m m'"))---", r"---(j <- .tmp[[1]])---", r"---(jp <- .tmp[[2]])---", r"---(m <- .tmp[[3]])---", r"---(mp <- .tmp[[4]])---", r"---(z <- JzKet(S(1), S(0)))---", r"---(po <- JzKet(S(1), S(1)))---", r"---(mo <- JzKet(S(1), S(-1)))---", r"---(A <- Operator("A"))---"), 'test_qapply')
  .do(e, r"---(e <- .pymul(.pymul(.pymul(JzOp(Symbol("J")), .pymul(mo, qattr(po, "dual"))), JzOp(Symbol("J"))), po))---")
