test_that("test_qapply: test_tensorproduct", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j j' m m'"))---", r"---(j <- .tmp[[1]])---", r"---(jp <- .tmp[[2]])---", r"---(m <- .tmp[[3]])---", r"---(mp <- .tmp[[4]])---", r"---(z <- JzKet(S(1), S(0)))---", r"---(po <- JzKet(S(1), S(1)))---", r"---(mo <- JzKet(S(1), S(-1)))---", r"---(A <- Operator("A"))---"), 'test_qapply')
  .do(e, r"---(a <- BosonOp("a"))---")
  .do(e, r"---(b <- BosonOp("b"))---")
  .do(e, r"---(ket1 <- TensorProduct(BosonFockKet(S(1)), BosonFockKet(S(2))))---")
  .do(e, r"---(ket2 <- TensorProduct(BosonFockKet(S(0)), BosonFockKet(S(0))))---")
  .do(e, r"---(ket3 <- TensorProduct(BosonFockKet(S(0)), BosonFockKet(S(2))))---")
  .do(e, r"---(bra1 <- TensorProduct(BosonFockBra(S(0)), BosonFockBra(S(0))))---")
  .do(e, r"---(bra2 <- TensorProduct(BosonFockBra(S(1)), BosonFockBra(S(2))))---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(a, (b ^ S(2))), ket1)))---"), r"---(sqrt(2)*|0>|0>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(a, .pymul(Dagger(b), b)), ket1)))---"), r"---(2*|0>|2>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(bra1, TensorProduct(a, .pymul(b, b))), dagger = TRUE))---"), r"---(sqrt(2)*<1|<2|)---")
  expect_equal(.run(e, r"---(doit(qapply(.pymul(bra2, ket1))))---"), r"---(1)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(a, .pymul(b, b)), ket1)))---"), r"---(sqrt(2)*|0>|0>)---")
  expect_equal(.run(e, r"---(qapply(Dagger(.pymul(TensorProduct(a, .pymul(b, b)), ket1)), dagger = TRUE))---"), r"---(sqrt(2)*<0|<0|)---")
})

test_that("test_qapply: test_dagger", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j j' m m'"))---", r"---(j <- .tmp[[1]])---", r"---(jp <- .tmp[[2]])---", r"---(m <- .tmp[[3]])---", r"---(mp <- .tmp[[4]])---", r"---(z <- JzKet(S(1), S(0)))---", r"---(po <- JzKet(S(1), S(1)))---", r"---(mo <- JzKet(S(1), S(-1)))---", r"---(A <- Operator("A"))---"), 'test_qapply')
  .do(e, r"---(lhs <- .pymul(Dagger(Qubit(S(0))), Dagger(HadamardGate(S(0)))))---")
  .do(e, r"---(rhs <- ((Dagger(Qubit(S(1))) / sqrt(S(S(2)))) + (Dagger(Qubit(S(0))) / sqrt(S(S(2))))))---")
  expect_equal(.run(e, r"---(qapply(lhs, dagger = TRUE))---"), r"---(sqrt(2)*<0|/2 + sqrt(2)*<1|/2)---")
})

test_that("test_qapply: test_issue_6073", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j j' m m'"))---", r"---(j <- .tmp[[1]])---", r"---(jp <- .tmp[[2]])---", r"---(m <- .tmp[[3]])---", r"---(mp <- .tmp[[4]])---", r"---(z <- JzKet(S(1), S(0)))---", r"---(po <- JzKet(S(1), S(1)))---", r"---(mo <- JzKet(S(1), S(-1)))---", r"---(A <- Operator("A"))---"), 'test_qapply')
  .do(e, r"---(.tmp <- sym_symbols("x y", commutative = FALSE))---")
  .do(e, r"---(x <- .tmp[[1]])---")
  .do(e, r"---(y <- .tmp[[2]])---")
  .do(e, r"---(A <- Ket(x, y))---")
  .do(e, r"---(B <- Operator("B"))---")
  expect_equal(.run(e, r"---(qapply(A))---"), r"---(|xy>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(qattr(A, "dual"), B)))---"), r"---(<xy|*B)---")
})

test_that("test_qapply: test_density", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j j' m m'"))---", r"---(j <- .tmp[[1]])---", r"---(jp <- .tmp[[2]])---", r"---(m <- .tmp[[3]])---", r"---(mp <- .tmp[[4]])---", r"---(z <- JzKet(S(1), S(0)))---", r"---(po <- JzKet(S(1), S(1)))---", r"---(mo <- JzKet(S(1), S(-1)))---", r"---(A <- Operator("A"))---"), 'test_qapply')
  .do(e, r"---(d <- Density(list(.pymul(JzOp(Symbol("J")), mo), 0.5), list(.pymul(JzOp(Symbol("J")), po), 0.5)))---")
  expect_equal(.run(e, r"---(qapply(d))---"), r"---(Density((-hbar*|1,-1>, 0.5),(hbar*|1,1>, 0.5)))---")
})

test_that("test_qapply: test_issue3044", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j j' m m'"))---", r"---(j <- .tmp[[1]])---", r"---(jp <- .tmp[[2]])---", r"---(m <- .tmp[[3]])---", r"---(mp <- .tmp[[4]])---", r"---(z <- JzKet(S(1), S(0)))---", r"---(po <- JzKet(S(1), S(1)))---", r"---(mo <- JzKet(S(1), S(-1)))---", r"---(A <- Operator("A"))---"), 'test_qapply')
  .do(e, r"---(expr1 <- TensorProduct((.pymul(JzOp(Symbol("J")), JzKet(S(S(2)), S_NegativeOne)) / sqrt(S(S(2)))), .pymul(JzOp(Symbol("J")), JzKet(S_Half, S_Half))))---")
  .do(e, r"---(result <- Mul(S_NegativeOne, Rational(S(1), S(4)), (S(2) ^ S_Half), (hbar ^ S(2))))---")
  .do(e, r"---(result <- .pymul(result, TensorProduct(JzKet(S(2), S(-1)), JzKet(S_Half, S_Half))))---")
  expect_equal(.run(e, r"---(qapply(expr1))---"), r"---(-sqrt(2)*hbar^2*|2,-1>|1/2,1/2>/4)---")
})

test_that("test_qapply: test_issue24158_ket_times_op", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j j' m m'"))---", r"---(j <- .tmp[[1]])---", r"---(jp <- .tmp[[2]])---", r"---(m <- .tmp[[3]])---", r"---(mp <- .tmp[[4]])---", r"---(z <- JzKet(S(1), S(0)))---", r"---(po <- JzKet(S(1), S(1)))---", r"---(mo <- JzKet(S(1), S(-1)))---", r"---(A <- Operator("A"))---"), 'test_qapply')
  .do(e, r"---(P <- .pymul(BosonFockKet(S(0)), BosonOp("a")))---")
  expect_equal(.run(e, r"---(qapply(P))---"), r"---(|0>*a)---")
  .do(e, r"---(P <- .pymul(Qubit(S(1)), XGate(S(0))))---")
  expect_equal(.run(e, r"---(qapply(P))---"), r"---(|1>*X(0))---")
  .do(e, r"---(P1 <- Mul(QubitBra(S(0)), Mul(QubitBra(S(0)), Qubit(S(0))), XGate(S(0))))---")
  expect_equal(.run(e, r"---(qapply(P1))---"), r"---(<0|*X(0))---")
  .do(e, r"---(P1 <- qapply(P1, dagger = TRUE))---")
  expect_equal(.run(e, r"---(qapply(P1, dagger = TRUE))---"), r"---(<1|)---")
  .do(e, r"---(P2 <- .pymul(.pymul(QubitBra(S(0)), .pymul(QubitBra(S(0)), Qubit(S(0)))), XGate(S(0))))---")
  .do(e, r"---(P2 <- qapply(P2, dagger = TRUE))---")
  expect_equal(.run(e, r"---(P2)---"), r"---(<1|)---")
  expect_equal(.run(e, r"---(qapply(.pymul(QubitBra(S(1)), IdentityOperator())))---"), r"---(<1|)---")
  expect_equal(.run(e, r"---(qapply(.pymul(IdentityGate(S(0)), (Qubit(S(0)) + Qubit(S(1))))))---"), r"---(|0> + |1>)---")
})

