test_that("test_qexpr: test_qexpr_new", {
  e <- .new(c(r"---(x <- Symbol("x"))---", r"---(y <- Symbol("y"))---", r"---(n <- Symbol("n", integer = TRUE))---", r"---(m <- Symbol("m", integer = TRUE))---"), 'test_qexpr')
  .do(e, r"---(v_q <- QExpr(S(0)))---")
  expect_equal(.run(e, r"---(qattr(v_q, "label"))---"), r"---([0])---")
  expect_equal(.run(e, r"---(qattr(v_q, "hilbert_space"))---"), r"---(H)---")
  expect_equal(.run(e, r"---(qattr(v_q, "is_commutative"))---"), r"---(False)---")
  .do(e, r"---(v_q <- QExpr(S(0), S(1)))---")
  expect_equal(.run(e, r"---(qattr(v_q, "label"))---"), r"---([0, 1])---")
  .do(e, r"---(v_q <- qcall("QExpr", "_new_rawargs", HilbertSpace(), Integer(S(0)), Integer(S(1))))---")
  expect_equal(.run(e, r"---(qattr(v_q, "label"))---"), r"---([0, 1])---")
  expect_equal(.run(e, r"---(qattr(v_q, "hilbert_space"))---"), r"---(H)---")
})

test_that("test_qexpr: test_qexpr_commutative", {
  e <- .new(c(r"---(x <- Symbol("x"))---", r"---(y <- Symbol("y"))---", r"---(n <- Symbol("n", integer = TRUE))---", r"---(m <- Symbol("m", integer = TRUE))---"), 'test_qexpr')
  .do(e, r"---(q1 <- QExpr(x))---")
  .do(e, r"---(q2 <- QExpr(y))---")
  expect_equal(.run(e, r"---(qattr(q1, "is_commutative"))---"), r"---(False)---")
  expect_equal(.run(e, r"---(qattr(q2, "is_commutative"))---"), r"---(False)---")
  expect_equal(.run(e, r"---(.pymul(q1, q2))---"), r"---(x*y)---")
  .do(e, r"---(v_q <- qcall("QExpr", "_new_rawargs", Integer(S(0)), Integer(S(1)), HilbertSpace()))---")
  expect_equal(.run(e, r"---(qattr(v_q, "is_commutative"))---"), r"---(False)---")
})

