test_that("test_qft: test_RkGate", {
  e <- .new(character(), 'test_qft')
  .do(e, r"---(x <- Symbol("x"))---")
  expect_equal(.run(e, r"---(qattr(RkGate(S(1), x), "k"))---"), r"---(x)---")
  expect_equal(.run(e, r"---(qattr(RkGate(S(1), x), "targets"))---"), r"---([1])---")
  expect_equal(.run(e, r"---(RkGate(S(1), S(1)))---"), r"---(Z(1))---")
  expect_equal(.run(e, r"---(RkGate(S(2), S(2)))---"), r"---(S(2))---")
  expect_equal(.run(e, r"---(RkGate(S(3), S(3)))---"), r"---(T(3))---")
  expect_equal(.run(e, r"---(represent(RkGate(S(0), x), nqubits = S(1)))---"), r"---(Matrix([[1, 0], [0, exp(2*I*pi*sign(x)/2^Abs(x))]]))---")
})

test_that("test_qft: test_quantum_fourier", {
  e <- .new(character(), 'test_qft')
  expect_equal(.run(e, r"---(qcall(QFT(S(0), S(3)), "decompose"))---"), r"---(SWAP(0,2)*H(0)*C((0),S(1))*H(1)*C((0),T(2))*C((1),S(2))*H(2))---")
  expect_equal(.run(e, r"---(qcall(IQFT(S(0), S(3)), "decompose"))---"), r"---(H(2)*C((1),Rk(2,-2))*C((0),Rk(2,-3))*H(1)*C((0),Rk(1,-2))*H(0)*SWAP(0,2))---")
  expect_equal(.run(e, r"---(represent(QFT(S(0), S(3)), nqubits = S(3)))---"), r"---(Matrix([[sqrt(2)/4, sqrt(2)/4, sqrt(2)/4, sqrt(2)/4, sqrt(2)/4, sqrt(2)/4, sqrt(2)/4, sqrt(2)/4], [sqrt(2)/4, sqrt(2)*exp(I*pi/4)/4, sqrt(2)*I/4, sqrt(2)*exp(3*I*pi/4)/4, -sqrt(2)/4, sqrt(2)*exp(-3*I*pi/4)/4, -sqrt(2)*I/4, sqrt(2)*exp(-I*pi/4)/4], [sqrt(2)/4, sqrt(2)*I/4, -sqrt(2)/4, -sqrt(2)*I/4, sqrt(2)/4, sqrt(2)*I/4, -sqrt(2)/4, -sqrt(2)*I/4], [sqrt(2)/4, sqrt(2)*exp(3*I*pi/4)/4, -sqrt(2)*I/4, sqrt(2)*exp(I*pi/4)/4, -sqrt(2)/4, sqrt(2)*exp(-I*pi/4)/4, sqrt(2)*I/4, sqrt(2)*exp(-3*I*pi/4)/4], [sqrt(2)/4, -sqrt(2)/4, sqrt(2)/4, -sqrt(2)/4, sqrt(2)/4, -sqrt(2)/4, sqrt(2)/4, -sqrt(2)/4], [sqrt(2)/4, sqrt(2)*exp(-3*I*pi/4)/4, sqrt(2)*I/4, sqrt(2)*exp(-I*pi/4)/4, -sqrt(2)/4, sqrt(2)*exp(I*pi/4)/4, -sqrt(2)*I/4, sqrt(2)*exp(3*I*pi/4)/4], [sqrt(2)/4, -sqrt(2)*I/4, -sqrt(2)/4, sqrt(2)*I/4, sqrt(2)/4, -sqrt(2)*I/4, -sqrt(2)/4, sqrt(2)*I/4], [sqrt(2)/4, sqrt(2)*exp(-I*pi/4)/4, -sqrt(2)*I/4, sqrt(2)*exp(-3*I*pi/4)/4, -sqrt(2)/4, sqrt(2)*exp(3*I*pi/4)/4, sqrt(2)*I/4, sqrt(2)*exp(I*pi/4)/4]]))---")
  expect_equal(.run(e, r"---(qcall(QFT(S(0), S(4)), "decompose"))---"), r"---(SWAP(1,2)*SWAP(0,3)*H(0)*C((0),S(1))*H(1)*C((0),T(2))*C((1),S(2))*H(2)*C((0),Rk(3,4))*C((1),T(3))*C((2),S(3))*H(3))---")
  expect_equal(.run(e, r"---(expand(qapply(.pymul(qcall(QFT(S(0), S(3)), "decompose"), Qubit(S(0), S(0), S(0))))))---"), r"---(sqrt(2)*|000>/4 + sqrt(2)*|001>/4 + sqrt(2)*|010>/4 + sqrt(2)*|011>/4 + sqrt(2)*|100>/4 + sqrt(2)*|101>/4 + sqrt(2)*|110>/4 + sqrt(2)*|111>/4)---")
})

