test_that("test_spin: test_represent_spin_operators", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j1:5 m1:5"))---", r"---(j1 <- .tmp[[1]])---", r"---(j2 <- .tmp[[2]])---", r"---(j3 <- .tmp[[3]])---", r"---(j4 <- .tmp[[4]])---", r"---(m1 <- .tmp[[5]])---", r"---(m2 <- .tmp[[6]])---", r"---(m3 <- .tmp[[7]])---", r"---(m4 <- .tmp[[8]])---", r"---(.tmp <- sym_symbols("j12 j13 j24 j34 j123 j134 mi mi1 mp"))---", r"---(j12 <- .tmp[[1]])---", r"---(j13 <- .tmp[[2]])---", r"---(j24 <- .tmp[[3]])---", r"---(j34 <- .tmp[[4]])---", r"---(j123 <- .tmp[[5]])---", r"---(j134 <- .tmp[[6]])---", r"---(mi <- .tmp[[7]])---", r"---(mi1 <- .tmp[[8]])---", r"---(mp <- .tmp[[9]])---"), 'test_spin')
  expect_equal(.run(e, r"---(represent(JxOp(Symbol("J"))))---"), r"---(Matrix([[0, hbar/2], [hbar/2, 0]]))---")
  expect_equal(.run(e, r"---(represent(JxOp(Symbol("J")), j = S(1)))---"), r"---(Matrix([[0, sqrt(2)*hbar/2, 0], [sqrt(2)*hbar/2, 0, sqrt(2)*hbar/2], [0, sqrt(2)*hbar/2, 0]]))---")
  expect_equal(.run(e, r"---(represent(JyOp(Symbol("J"))))---"), r"---(Matrix([[0, -hbar*I/2], [hbar*I/2, 0]]))---")
  expect_equal(.run(e, r"---(represent(JyOp(Symbol("J")), j = S(1)))---"), r"---(Matrix([[0, -sqrt(2)*hbar*I/2, 0], [sqrt(2)*hbar*I/2, 0, -sqrt(2)*hbar*I/2], [0, sqrt(2)*hbar*I/2, 0]]))---")
  expect_equal(.run(e, r"---(represent(JzOp(Symbol("J"))))---"), r"---(Matrix([[hbar/2, 0], [0, -hbar/2]]))---")
  expect_equal(.run(e, r"---(represent(JzOp(Symbol("J")), j = S(1)))---"), r"---(Matrix([[hbar, 0, 0], [0, 0, 0], [0, 0, -hbar]]))---")
})

test_that("test_spin: test_represent_spin_states", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j1:5 m1:5"))---", r"---(j1 <- .tmp[[1]])---", r"---(j2 <- .tmp[[2]])---", r"---(j3 <- .tmp[[3]])---", r"---(j4 <- .tmp[[4]])---", r"---(m1 <- .tmp[[5]])---", r"---(m2 <- .tmp[[6]])---", r"---(m3 <- .tmp[[7]])---", r"---(m4 <- .tmp[[8]])---", r"---(.tmp <- sym_symbols("j12 j13 j24 j34 j123 j134 mi mi1 mp"))---", r"---(j12 <- .tmp[[1]])---", r"---(j13 <- .tmp[[2]])---", r"---(j24 <- .tmp[[3]])---", r"---(j34 <- .tmp[[4]])---", r"---(j123 <- .tmp[[5]])---", r"---(j134 <- .tmp[[6]])---", r"---(mi <- .tmp[[7]])---", r"---(mi1 <- .tmp[[8]])---", r"---(mp <- .tmp[[9]])---"), 'test_spin')
  expect_equal(.run(e, r"---(represent(JxKet(S_Half, S_Half), basis = JxOp(Symbol("J"))))---"), r"---(Matrix([[1], [0]]))---")
  expect_equal(.run(e, r"---(represent(JxKet(S_Half, Rational(S(-1), S(2))), basis = JxOp(Symbol("J"))))---"), r"---(Matrix([[0], [1]]))---")
  expect_equal(.run(e, r"---(represent(JxKet(S(1), S(1)), basis = JxOp(Symbol("J"))))---"), r"---(Matrix([[1], [0], [0]]))---")
  expect_equal(.run(e, r"---(represent(JxKet(S(1), S(0)), basis = JxOp(Symbol("J"))))---"), r"---(Matrix([[0], [1], [0]]))---")
