  expect_equal(.run(e, r"---(represent(JyKet(S(1), S(1)), basis = JxOp(Symbol("J"))))---"), r"---(Matrix([[-I], [0], [0]]))---")
  expect_equal(.run(e, r"---(represent(JyKet(S(1), S(0)), basis = JxOp(Symbol("J"))))---"), r"---(Matrix([[0], [1], [0]]))---")
  expect_equal(.run(e, r"---(represent(JyKet(S(1), S(-1)), basis = JxOp(Symbol("J"))))---"), r"---(Matrix([[0], [0], [I]]))---")
  expect_equal(.run(e, r"---(represent(JzKet(S_Half, S_Half), basis = JxOp(Symbol("J"))))---"), r"---(Matrix([[-sqrt(2)/2], [sqrt(2)/2]]))---")
  expect_equal(.run(e, r"---(represent(JzKet(S_Half, Rational(S(-1), S(2))), basis = JxOp(Symbol("J"))))---"), r"---(Matrix([[-sqrt(2)/2], [-sqrt(2)/2]]))---")
  expect_equal(.run(e, r"---(represent(JzKet(S(1), S(1)), basis = JxOp(Symbol("J"))))---"), r"---(Matrix([[1/2], [-sqrt(2)/2], [1/2]]))---")
  expect_equal(.run(e, r"---(represent(JzKet(S(1), S(0)), basis = JxOp(Symbol("J"))))---"), r"---(Matrix([[sqrt(2)/2], [0], [-sqrt(2)/2]]))---")
  expect_equal(.run(e, r"---(represent(JzKet(S(1), S(-1)), basis = JxOp(Symbol("J"))))---"), r"---(Matrix([[1/2], [sqrt(2)/2], [1/2]]))---")
  expect_equal(.run(e, r"---(represent(JxKet(S_Half, S_Half), basis = JyOp(Symbol("J"))))---"), r"---(Matrix([[exp(-3*I*pi/4)], [0]]))---")
  expect_equal(.run(e, r"---(represent(JxKet(S_Half, Rational(S(-1), S(2))), basis = JyOp(Symbol("J"))))---"), r"---(Matrix([[0], [exp(3*I*pi/4)]]))---")
