  expect_equal(.run(e, r"---(represent(JyKet(S(1), S(1)), basis = JyOp(Symbol("J"))))---"), r"---(Matrix([[1], [0], [0]]))---")
  expect_equal(.run(e, r"---(represent(JyKet(S(1), S(0)), basis = JyOp(Symbol("J"))))---"), r"---(Matrix([[0], [1], [0]]))---")
