  expect_equal(.run(e, r"---(represent(JzKet(S(1), S(-1)), basis = JyOp(Symbol("J"))))---"), r"---(Matrix([[-1/2], [-sqrt(2)*I/2], [1/2]]))---")
  expect_equal(.run(e, r"---(represent(JxKet(S_Half, S_Half), basis = JzOp(Symbol("J"))))---"), r"---(Matrix([[sqrt(2)/2], [sqrt(2)/2]]))---")
  expect_equal(.run(e, r"---(represent(JxKet(S_Half, Rational(S(-1), S(2))), basis = JzOp(Symbol("J"))))---"), r"---(Matrix([[-sqrt(2)/2], [sqrt(2)/2]]))---")
  expect_equal(.run(e, r"---(represent(JxKet(S(1), S(1)), basis = JzOp(Symbol("J"))))---"), r"---(Matrix([[1/2], [sqrt(2)/2], [1/2]]))---")
  expect_equal(.run(e, r"---(represent(JxKet(S(1), S(0)), basis = JzOp(Symbol("J"))))---"), r"---(Matrix([[-sqrt(2)/2], [0], [sqrt(2)/2]]))---")
  expect_equal(.run(e, r"---(represent(JxKet(S(1), S(-1)), basis = JzOp(Symbol("J"))))---"), r"---(Matrix([[1/2], [-sqrt(2)/2], [1/2]]))---")
  expect_equal(.run(e, r"---(represent(JyKet(S_Half, S_Half), basis = JzOp(Symbol("J"))))---"), r"---(Matrix([[-sqrt(2)/2], [-sqrt(2)*I/2]]))---")
  expect_equal(.run(e, r"---(represent(JyKet(S_Half, Rational(S(-1), S(2))), basis = JzOp(Symbol("J"))))---"), r"---(Matrix([[-sqrt(2)*I/2], [-sqrt(2)/2]]))---")
  expect_equal(.run(e, r"---(represent(JyKet(S(1), S(1)), basis = JzOp(Symbol("J"))))---"), r"---(Matrix([[1/2], [sqrt(2)*I/2], [-1/2]]))---")
  expect_equal(.run(e, r"---(represent(JyKet(S(1), S(0)), basis = JzOp(Symbol("J"))))---"), r"---(Matrix([[sqrt(2)*I/2], [0], [sqrt(2)*I/2]]))---")
  expect_equal(.run(e, r"---(represent(JyKet(S(1), S(-1)), basis = JzOp(Symbol("J"))))---"), r"---(Matrix([[-1/2], [sqrt(2)*I/2], [1/2]]))---")
  expect_equal(.run(e, r"---(represent(JzKet(S_Half, S_Half), basis = JzOp(Symbol("J"))))---"), r"---(Matrix([[1], [0]]))---")
