test_that("test_spin: test_represent_rotation", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j1:5 m1:5"))---", r"---(j1 <- .tmp[[1]])---", r"---(j2 <- .tmp[[2]])---", r"---(j3 <- .tmp[[3]])---", r"---(j4 <- .tmp[[4]])---", r"---(m1 <- .tmp[[5]])---", r"---(m2 <- .tmp[[6]])---", r"---(m3 <- .tmp[[7]])---", r"---(m4 <- .tmp[[8]])---", r"---(.tmp <- sym_symbols("j12 j13 j24 j34 j123 j134 mi mi1 mp"))---", r"---(j12 <- .tmp[[1]])---", r"---(j13 <- .tmp[[2]])---", r"---(j24 <- .tmp[[3]])---", r"---(j34 <- .tmp[[4]])---", r"---(j123 <- .tmp[[5]])---", r"---(j134 <- .tmp[[6]])---", r"---(mi <- .tmp[[7]])---", r"---(mi1 <- .tmp[[8]])---", r"---(mp <- .tmp[[9]])---"), 'test_spin')
  expect_equal(.run(e, r"---(represent(Rotation(S(0), (sym_pi / S(2)), S(0))))---"), r"---(Matrix([[WignerD(1/2, 1/2, 1/2, 0, pi/2, 0), WignerD(1/2, 1/2, -1/2, 0, pi/2, 0)], [WignerD(1/2, -1/2, 1/2, 0, pi/2, 0), WignerD(1/2, -1/2, -1/2, 0, pi/2, 0)]]))---")
  expect_equal(.run(e, r"---(represent(Rotation(S(0), (sym_pi / S(2)), S(0)), doit = TRUE))---"), r"---(Matrix([[sqrt(2)/2, -sqrt(2)/2], [sqrt(2)/2, sqrt(2)/2]]))---")
})

test_that("test_spin: test_rewrite_same", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j1:5 m1:5"))---", r"---(j1 <- .tmp[[1]])---", r"---(j2 <- .tmp[[2]])---", r"---(j3 <- .tmp[[3]])---", r"---(j4 <- .tmp[[4]])---", r"---(m1 <- .tmp[[5]])---", r"---(m2 <- .tmp[[6]])---", r"---(m3 <- .tmp[[7]])---", r"---(m4 <- .tmp[[8]])---", r"---(.tmp <- sym_symbols("j12 j13 j24 j34 j123 j134 mi mi1 mp"))---", r"---(j12 <- .tmp[[1]])---", r"---(j13 <- .tmp[[2]])---", r"---(j24 <- .tmp[[3]])---", r"---(j34 <- .tmp[[4]])---", r"---(j123 <- .tmp[[5]])---", r"---(j134 <- .tmp[[6]])---", r"---(mi <- .tmp[[7]])---", r"---(mi1 <- .tmp[[8]])---", r"---(mp <- .tmp[[9]])---"), 'test_spin')
  expect_equal(.run(e, r"---(rewrite(JxBra(S(1), S(1)), "Jx"))---"), r"---(<1,1|)---")
  expect_equal(.run(e, r"---(rewrite(JxBra(Symbol("j"), Symbol("m")), "Jx"))---"), r"---(<j,m|)---")
  expect_equal(.run(e, r"---(rewrite(JxKet(S(1), S(1)), "Jx"))---"), r"---(|1,1>)---")
  expect_equal(.run(e, r"---(rewrite(JxKet(Symbol("j"), Symbol("m")), "Jx"))---"), r"---(|j,m>)---")
})

test_that("test_spin: test_rewrite_Bra", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j1:5 m1:5"))---", r"---(j1 <- .tmp[[1]])---", r"---(j2 <- .tmp[[2]])---", r"---(j3 <- .tmp[[3]])---", r"---(j4 <- .tmp[[4]])---", r"---(m1 <- .tmp[[5]])---", r"---(m2 <- .tmp[[6]])---", r"---(m3 <- .tmp[[7]])---", r"---(m4 <- .tmp[[8]])---", r"---(.tmp <- sym_symbols("j12 j13 j24 j34 j123 j134 mi mi1 mp"))---", r"---(j12 <- .tmp[[1]])---", r"---(j13 <- .tmp[[2]])---", r"---(j24 <- .tmp[[3]])---", r"---(j34 <- .tmp[[4]])---", r"---(j123 <- .tmp[[5]])---", r"---(j134 <- .tmp[[6]])---", r"---(mi <- .tmp[[7]])---", r"---(mi1 <- .tmp[[8]])---", r"---(mp <- .tmp[[9]])---"), 'test_spin')
  expect_equal(.run(e, r"---(rewrite(JxBra(S(1), S(1)), "Jy"))---"), r"---(-I*<1,1|)---")
  expect_equal(.run(e, r"---(rewrite(JxBra(S(1), S(0)), "Jy"))---"), r"---(<1,0|)---")
  expect_equal(.run(e, r"---(rewrite(JxBra(S(1), S(-1)), "Jy"))---"), r"---(I*<1,-1|)---")
  expect_equal(.run(e, r"---(rewrite(JxBra(S(1), S(1)), "Jz"))---"), r"---(<1,-1|/2 + sqrt(2)*<1,0|/2 + <1,1|/2)---")
  expect_equal(.run(e, r"---(rewrite(JxBra(S(1), S(0)), "Jz"))---"), r"---(sqrt(2)*<1,-1|/2 - sqrt(2)*<1,1|/2)---")
  expect_equal(.run(e, r"---(rewrite(JxBra(S(1), S(-1)), "Jz"))---"), r"---(<1,-1|/2 - sqrt(2)*<1,0|/2 + <1,1|/2)---")
  expect_equal(.run(e, r"---(rewrite(JyBra(S(1), S(1)), "Jx"))---"), r"---(I*<1,1|)---")
  expect_equal(.run(e, r"---(rewrite(JyBra(S(1), S(0)), "Jx"))---"), r"---(<1,0|)---")
  expect_equal(.run(e, r"---(rewrite(JyBra(S(1), S(-1)), "Jx"))---"), r"---(-I*<1,-1|)---")
  expect_equal(.run(e, r"---(rewrite(JyBra(S(1), S(1)), "Jz"))---"), r"---(-<1,-1|/2 - sqrt(2)*I*<1,0|/2 + <1,1|/2)---")
  expect_equal(.run(e, r"---(rewrite(JyBra(S(1), S(0)), "Jz"))---"), r"---(-sqrt(2)*I*<1,-1|/2 - sqrt(2)*I*<1,1|/2)---")
  expect_equal(.run(e, r"---(rewrite(JyBra(S(1), S(-1)), "Jz"))---"), r"---(<1,-1|/2 - sqrt(2)*I*<1,0|/2 - <1,1|/2)---")
  expect_equal(.run(e, r"---(rewrite(JzBra(S(1), S(1)), "Jx"))---"), r"---(<1,-1|/2 - sqrt(2)*<1,0|/2 + <1,1|/2)---")
  expect_equal(.run(e, r"---(rewrite(JzBra(S(1), S(0)), "Jx"))---"), r"---(-sqrt(2)*<1,-1|/2 + sqrt(2)*<1,1|/2)---")
  expect_equal(.run(e, r"---(rewrite(JzBra(S(1), S(-1)), "Jx"))---"), r"---(<1,-1|/2 + sqrt(2)*<1,0|/2 + <1,1|/2)---")
  expect_equal(.run(e, r"---(rewrite(JzBra(S(1), S(1)), "Jy"))---"), r"---(-<1,-1|/2 + sqrt(2)*I*<1,0|/2 + <1,1|/2)---")
  expect_equal(.run(e, r"---(rewrite(JzBra(S(1), S(0)), "Jy"))---"), r"---(sqrt(2)*I*<1,-1|/2 + sqrt(2)*I*<1,1|/2)---")
  expect_equal(.run(e, r"---(rewrite(JzBra(S(1), S(-1)), "Jy"))---"), r"---(<1,-1|/2 + sqrt(2)*I*<1,0|/2 - <1,1|/2)---")
  expect_equal(.run(e, r"---(rewrite(JxBra(Symbol("j"), Symbol("m")), "Jy"))---"), r"---(Sum(WignerD(j, mi, m, 3*pi/2, 0, 0)*<j,mi|, (mi, -j, j)))---")
  expect_equal(.run(e, r"---(rewrite(JxBra(Symbol("j"), Symbol("m")), "Jz"))---"), r"---(Sum(WignerD(j, mi, m, 0, pi/2, 0)*<j,mi|, (mi, -j, j)))---")
  expect_equal(.run(e, r"---(rewrite(JyBra(Symbol("j"), Symbol("m")), "Jx"))---"), r"---(Sum(WignerD(j, mi, m, 0, 0, pi/2)*<j,mi|, (mi, -j, j)))---")
  expect_equal(.run(e, r"---(rewrite(JyBra(Symbol("j"), Symbol("m")), "Jz"))---"), r"---(Sum(WignerD(j, mi, m, 3*pi/2, -pi/2, pi/2)*<j,mi|, (mi, -j, j)))---")
  expect_equal(.run(e, r"---(rewrite(JzBra(Symbol("j"), Symbol("m")), "Jx"))---"), r"---(Sum(WignerD(j, mi, m, 0, 3*pi/2, 0)*<j,mi|, (mi, -j, j)))---")
  expect_equal(.run(e, r"---(rewrite(JzBra(Symbol("j"), Symbol("m")), "Jy"))---"), r"---(Sum(WignerD(j, mi, m, 3*pi/2, pi/2, pi/2)*<j,mi|, (mi, -j, j)))---")
})

