test_that("test_spin: test_rewrite_uncoupled_state", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j1:5 m1:5"))---", r"---(j1 <- .tmp[[1]])---", r"---(j2 <- .tmp[[2]])---", r"---(j3 <- .tmp[[3]])---", r"---(j4 <- .tmp[[4]])---", r"---(m1 <- .tmp[[5]])---", r"---(m2 <- .tmp[[6]])---", r"---(m3 <- .tmp[[7]])---", r"---(m4 <- .tmp[[8]])---", r"---(.tmp <- sym_symbols("j12 j13 j24 j34 j123 j134 mi mi1 mp"))---", r"---(j12 <- .tmp[[1]])---", r"---(j13 <- .tmp[[2]])---", r"---(j24 <- .tmp[[3]])---", r"---(j34 <- .tmp[[4]])---", r"---(j123 <- .tmp[[5]])---", r"---(j134 <- .tmp[[6]])---", r"---(mi <- .tmp[[7]])---", r"---(mi1 <- .tmp[[8]])---", r"---(mp <- .tmp[[9]])---"), 'test_spin')
  expect_equal(.run(e, r"---(rewrite(TensorProduct(JyKet(S(1), S(1)), JxKet(S(1), S(1))), "Jx"))---"), r"---(-I*|1,1>|1,1>)---")
  expect_equal(.run(e, r"---(rewrite(TensorProduct(JyKet(S(1), S(0)), JxKet(S(1), S(1))), "Jx"))---"), r"---(|1,0>|1,1>)---")
  expect_equal(.run(e, r"---(rewrite(TensorProduct(JyKet(S(1), S(-1)), JxKet(S(1), S(1))), "Jx"))---"), r"---(I*|1,-1>|1,1>)---")
  expect_equal(.run(e, r"---(rewrite(TensorProduct(JzKet(S(1), S(1)), JxKet(S(1), S(1))), "Jx"))---"), r"---(|1,-1>|1,1>/2 - sqrt(2)*|1,0>|1,1>/2 + |1,1>|1,1>/2)---")
  expect_equal(.run(e, r"---(rewrite(TensorProduct(JzKet(S(1), S(0)), JxKet(S(1), S(1))), "Jx"))---"), r"---(-sqrt(2)*|1,-1>|1,1>/2 + sqrt(2)*|1,1>|1,1>/2)---")
  expect_equal(.run(e, r"---(rewrite(TensorProduct(JzKet(S(1), S(-1)), JxKet(S(1), S(1))), "Jx"))---"), r"---(|1,-1>|1,1>/2 + sqrt(2)*|1,0>|1,1>/2 + |1,1>|1,1>/2)---")
  expect_equal(.run(e, r"---(rewrite(TensorProduct(JxKet(S(1), S(1)), JyKet(S(1), S(1))), "Jy"))---"), r"---(I*|1,1>|1,1>)---")
  expect_equal(.run(e, r"---(rewrite(TensorProduct(JxKet(S(1), S(0)), JyKet(S(1), S(1))), "Jy"))---"), r"---(|1,0>|1,1>)---")
  expect_equal(.run(e, r"---(rewrite(TensorProduct(JxKet(S(1), S(-1)), JyKet(S(1), S(1))), "Jy"))---"), r"---(-I*|1,-1>|1,1>)---")
  expect_equal(.run(e, r"---(rewrite(TensorProduct(JzKet(S(1), S(1)), JyKet(S(1), S(1))), "Jy"))---"), r"---(-|1,-1>|1,1>/2 - sqrt(2)*I*|1,0>|1,1>/2 + |1,1>|1,1>/2)---")
  expect_equal(.run(e, r"---(rewrite(TensorProduct(JzKet(S(1), S(0)), JyKet(S(1), S(1))), "Jy"))---"), r"---(-sqrt(2)*I*|1,-1>|1,1>/2 - sqrt(2)*I*|1,1>|1,1>/2)---")
  expect_equal(.run(e, r"---(rewrite(TensorProduct(JzKet(S(1), S(-1)), JyKet(S(1), S(1))), "Jy"))---"), r"---(|1,-1>|1,1>/2 - sqrt(2)*I*|1,0>|1,1>/2 - |1,1>|1,1>/2)---")
  expect_equal(.run(e, r"---(rewrite(TensorProduct(JxKet(S(1), S(1)), JzKet(S(1), S(1))), "Jz"))---"), r"---(|1,-1>|1,1>/2 + sqrt(2)*|1,0>|1,1>/2 + |1,1>|1,1>/2)---")
  expect_equal(.run(e, r"---(rewrite(TensorProduct(JxKet(S(1), S(0)), JzKet(S(1), S(1))), "Jz"))---"), r"---(sqrt(2)*|1,-1>|1,1>/2 - sqrt(2)*|1,1>|1,1>/2)---")
  expect_equal(.run(e, r"---(rewrite(TensorProduct(JxKet(S(1), S(-1)), JzKet(S(1), S(1))), "Jz"))---"), r"---(|1,-1>|1,1>/2 - sqrt(2)*|1,0>|1,1>/2 + |1,1>|1,1>/2)---")
  expect_equal(.run(e, r"---(rewrite(TensorProduct(JyKet(S(1), S(1)), JzKet(S(1), S(1))), "Jz"))---"), r"---(-|1,-1>|1,1>/2 + sqrt(2)*I*|1,0>|1,1>/2 + |1,1>|1,1>/2)---")
  expect_equal(.run(e, r"---(rewrite(TensorProduct(JyKet(S(1), S(0)), JzKet(S(1), S(1))), "Jz"))---"), r"---(sqrt(2)*I*|1,-1>|1,1>/2 + sqrt(2)*I*|1,1>|1,1>/2)---")
  expect_equal(.run(e, r"---(rewrite(TensorProduct(JyKet(S(1), S(-1)), JzKet(S(1), S(1))), "Jz"))---"), r"---(|1,-1>|1,1>/2 + sqrt(2)*I*|1,0>|1,1>/2 - |1,1>|1,1>/2)---")
  expect_equal(.run(e, r"---(rewrite(TensorProduct(JyKet(j1, m1), JxKet(j2, m2)), "Jy"))---"), r"---(|j1,m1>Sum(WignerD(j2, mi, m2, 3*pi/2, 0, 0)*|j2,mi>, (mi, -j2, j2)))---")
  expect_equal(.run(e, r"---(rewrite(TensorProduct(JzKet(j1, m1), JxKet(j2, m2)), "Jz"))---"), r"---(|j1,m1>Sum(WignerD(j2, mi, m2, 0, pi/2, 0)*|j2,mi>, (mi, -j2, j2)))---")
  expect_equal(.run(e, r"---(rewrite(TensorProduct(JxKet(j1, m1), JyKet(j2, m2)), "Jx"))---"), r"---(|j1,m1>Sum(WignerD(j2, mi, m2, 0, 0, pi/2)*|j2,mi>, (mi, -j2, j2)))---")
  expect_equal(.run(e, r"---(rewrite(TensorProduct(JzKet(j1, m1), JyKet(j2, m2)), "Jz"))---"), r"---(|j1,m1>Sum(WignerD(j2, mi, m2, 3*pi/2, -pi/2, pi/2)*|j2,mi>, (mi, -j2, j2)))---")
  expect_equal(.run(e, r"---(rewrite(TensorProduct(JxKet(j1, m1), JzKet(j2, m2)), "Jx"))---"), r"---(|j1,m1>Sum(WignerD(j2, mi, m2, 0, 3*pi/2, 0)*|j2,mi>, (mi, -j2, j2)))---")
  expect_equal(.run(e, r"---(rewrite(TensorProduct(JyKet(j1, m1), JzKet(j2, m2)), "Jy"))---"), r"---(|j1,m1>Sum(WignerD(j2, mi, m2, 3*pi/2, pi/2, pi/2)*|j2,mi>, (mi, -j2, j2)))---")
})

test_that("test_spin: test_rewrite_coupled_state", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j1:5 m1:5"))---", r"---(j1 <- .tmp[[1]])---", r"---(j2 <- .tmp[[2]])---", r"---(j3 <- .tmp[[3]])---", r"---(j4 <- .tmp[[4]])---", r"---(m1 <- .tmp[[5]])---", r"---(m2 <- .tmp[[6]])---", r"---(m3 <- .tmp[[7]])---", r"---(m4 <- .tmp[[8]])---", r"---(.tmp <- sym_symbols("j12 j13 j24 j34 j123 j134 mi mi1 mp"))---", r"---(j12 <- .tmp[[1]])---", r"---(j13 <- .tmp[[2]])---", r"---(j24 <- .tmp[[3]])---", r"---(j34 <- .tmp[[4]])---", r"---(j123 <- .tmp[[5]])---", r"---(j134 <- .tmp[[6]])---", r"---(mi <- .tmp[[7]])---", r"---(mi1 <- .tmp[[8]])---", r"---(mp <- .tmp[[9]])---"), 'test_spin')
  expect_equal(.run(e, r"---(rewrite(JyKetCoupled(S(0), S(0), list(S_Half, S_Half)), "Jx"))---"), r"---(|0,0,j1=1/2,j2=1/2>)---")
  expect_equal(.run(e, r"---(rewrite(JyKetCoupled(S(1), S(1), list(S_Half, S_Half)), "Jx"))---"), r"---(-I*|1,1,j1=1/2,j2=1/2>)---")
  expect_equal(.run(e, r"---(rewrite(JyKetCoupled(S(1), S(0), list(S_Half, S_Half)), "Jx"))---"), r"---(|1,0,j1=1/2,j2=1/2>)---")
  expect_equal(.run(e, r"---(rewrite(JyKetCoupled(S(1), S(-1), list(S_Half, S_Half)), "Jx"))---"), r"---(I*|1,-1,j1=1/2,j2=1/2>)---")
  expect_equal(.run(e, r"---(rewrite(JzKetCoupled(S(0), S(0), list(S_Half, S_Half)), "Jx"))---"), r"---(|0,0,j1=1/2,j2=1/2>)---")
  expect_equal(.run(e, r"---(rewrite(JzKetCoupled(S(1), S(1), list(S_Half, S_Half)), "Jx"))---"), r"---(|1,-1,j1=1/2,j2=1/2>/2 - sqrt(2)*|1,0,j1=1/2,j2=1/2>/2 + |1,1,j1=1/2,j2=1/2>/2)---")
  expect_equal(.run(e, r"---(rewrite(JzKetCoupled(S(1), S(0), list(S_Half, S_Half)), "Jx"))---"), r"---(-sqrt(2)*|1,-1,j1=1/2,j2=1/2>/2 + sqrt(2)*|1,1,j1=1/2,j2=1/2>/2)---")
  expect_equal(.run(e, r"---(rewrite(JzKetCoupled(S(1), S(-1), list(S_Half, S_Half)), "Jx"))---"), r"---(|1,-1,j1=1/2,j2=1/2>/2 + sqrt(2)*|1,0,j1=1/2,j2=1/2>/2 + |1,1,j1=1/2,j2=1/2>/2)---")
  expect_equal(.run(e, r"---(rewrite(JxKetCoupled(S(0), S(0), list(S_Half, S_Half)), "Jy"))---"), r"---(|0,0,j1=1/2,j2=1/2>)---")
  expect_equal(.run(e, r"---(rewrite(JxKetCoupled(S(1), S(1), list(S_Half, S_Half)), "Jy"))---"), r"---(I*|1,1,j1=1/2,j2=1/2>)---")
  expect_equal(.run(e, r"---(rewrite(JxKetCoupled(S(1), S(0), list(S_Half, S_Half)), "Jy"))---"), r"---(|1,0,j1=1/2,j2=1/2>)---")
  expect_equal(.run(e, r"---(rewrite(JxKetCoupled(S(1), S(-1), list(S_Half, S_Half)), "Jy"))---"), r"---(-I*|1,-1,j1=1/2,j2=1/2>)---")
  expect_equal(.run(e, r"---(rewrite(JzKetCoupled(S(0), S(0), list(S_Half, S_Half)), "Jy"))---"), r"---(|0,0,j1=1/2,j2=1/2>)---")
  expect_equal(.run(e, r"---(rewrite(JzKetCoupled(S(1), S(1), list(S_Half, S_Half)), "Jy"))---"), r"---(-|1,-1,j1=1/2,j2=1/2>/2 - sqrt(2)*I*|1,0,j1=1/2,j2=1/2>/2 + |1,1,j1=1/2,j2=1/2>/2)---")
  expect_equal(.run(e, r"---(rewrite(JzKetCoupled(S(1), S(0), list(S_Half, S_Half)), "Jy"))---"), r"---(-sqrt(2)*I*|1,-1,j1=1/2,j2=1/2>/2 - sqrt(2)*I*|1,1,j1=1/2,j2=1/2>/2)---")
  expect_equal(.run(e, r"---(rewrite(JzKetCoupled(S(1), S(-1), list(S_Half, S_Half)), "Jy"))---"), r"---(|1,-1,j1=1/2,j2=1/2>/2 - sqrt(2)*I*|1,0,j1=1/2,j2=1/2>/2 - |1,1,j1=1/2,j2=1/2>/2)---")
  expect_equal(.run(e, r"---(rewrite(JxKetCoupled(S(0), S(0), list(S_Half, S_Half)), "Jz"))---"), r"---(|0,0,j1=1/2,j2=1/2>)---")
  expect_equal(.run(e, r"---(rewrite(JxKetCoupled(S(1), S(1), list(S_Half, S_Half)), "Jz"))---"), r"---(|1,-1,j1=1/2,j2=1/2>/2 + sqrt(2)*|1,0,j1=1/2,j2=1/2>/2 + |1,1,j1=1/2,j2=1/2>/2)---")
  expect_equal(.run(e, r"---(rewrite(JxKetCoupled(S(1), S(0), list(S_Half, S_Half)), "Jz"))---"), r"---(sqrt(2)*|1,-1,j1=1/2,j2=1/2>/2 - sqrt(2)*|1,1,j1=1/2,j2=1/2>/2)---")
  expect_equal(.run(e, r"---(rewrite(JxKetCoupled(S(1), S(-1), list(S_Half, S_Half)), "Jz"))---"), r"---(|1,-1,j1=1/2,j2=1/2>/2 - sqrt(2)*|1,0,j1=1/2,j2=1/2>/2 + |1,1,j1=1/2,j2=1/2>/2)---")
  expect_equal(.run(e, r"---(rewrite(JyKetCoupled(S(0), S(0), list(S_Half, S_Half)), "Jz"))---"), r"---(|0,0,j1=1/2,j2=1/2>)---")
  expect_equal(.run(e, r"---(rewrite(JyKetCoupled(S(1), S(1), list(S_Half, S_Half)), "Jz"))---"), r"---(-|1,-1,j1=1/2,j2=1/2>/2 + sqrt(2)*I*|1,0,j1=1/2,j2=1/2>/2 + |1,1,j1=1/2,j2=1/2>/2)---")
  expect_equal(.run(e, r"---(rewrite(JyKetCoupled(S(1), S(0), list(S_Half, S_Half)), "Jz"))---"), r"---(sqrt(2)*I*|1,-1,j1=1/2,j2=1/2>/2 + sqrt(2)*I*|1,1,j1=1/2,j2=1/2>/2)---")
  expect_equal(.run(e, r"---(rewrite(JyKetCoupled(S(1), S(-1), list(S_Half, S_Half)), "Jz"))---"), r"---(|1,-1,j1=1/2,j2=1/2>/2 + sqrt(2)*I*|1,0,j1=1/2,j2=1/2>/2 - |1,1,j1=1/2,j2=1/2>/2)---")
  expect_equal(.run(e, r"---(rewrite(JyKetCoupled(Symbol("j"), Symbol("m"), list(j1, j2)), "Jx"))---"), r"---(Sum(WignerD(j, mi, m, 0, 0, pi/2)*|j,mi,j1=j1,j2=j2>, (mi, -j, j)))---")
  expect_equal(.run(e, r"---(rewrite(JzKetCoupled(Symbol("j"), Symbol("m"), list(j1, j2)), "Jx"))---"), r"---(Sum(WignerD(j, mi, m, 0, 3*pi/2, 0)*|j,mi,j1=j1,j2=j2>, (mi, -j, j)))---")
  expect_equal(.run(e, r"---(rewrite(JxKetCoupled(Symbol("j"), Symbol("m"), list(j1, j2)), "Jy"))---"), r"---(Sum(WignerD(j, mi, m, 3*pi/2, 0, 0)*|j,mi,j1=j1,j2=j2>, (mi, -j, j)))---")
  expect_equal(.run(e, r"---(rewrite(JzKetCoupled(Symbol("j"), Symbol("m"), list(j1, j2)), "Jy"))---"), r"---(Sum(WignerD(j, mi, m, 3*pi/2, pi/2, pi/2)*|j,mi,j1=j1,j2=j2>, (mi, -j, j)))---")
  expect_equal(.run(e, r"---(rewrite(JxKetCoupled(Symbol("j"), Symbol("m"), list(j1, j2)), "Jz"))---"), r"---(Sum(WignerD(j, mi, m, 0, pi/2, 0)*|j,mi,j1=j1,j2=j2>, (mi, -j, j)))---")
  expect_equal(.run(e, r"---(rewrite(JyKetCoupled(Symbol("j"), Symbol("m"), list(j1, j2)), "Jz"))---"), r"---(Sum(WignerD(j, mi, m, 3*pi/2, -pi/2, pi/2)*|j,mi,j1=j1,j2=j2>, (mi, -j, j)))---")
})

test_that("test_spin: test_innerproducts_of_rewritten_states", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j1:5 m1:5"))---", r"---(j1 <- .tmp[[1]])---", r"---(j2 <- .tmp[[2]])---", r"---(j3 <- .tmp[[3]])---", r"---(j4 <- .tmp[[4]])---", r"---(m1 <- .tmp[[5]])---", r"---(m2 <- .tmp[[6]])---", r"---(m3 <- .tmp[[7]])---", r"---(m4 <- .tmp[[8]])---", r"---(.tmp <- sym_symbols("j12 j13 j24 j34 j123 j134 mi mi1 mp"))---", r"---(j12 <- .tmp[[1]])---", r"---(j13 <- .tmp[[2]])---", r"---(j24 <- .tmp[[3]])---", r"---(j34 <- .tmp[[4]])---", r"---(j123 <- .tmp[[5]])---", r"---(j134 <- .tmp[[6]])---", r"---(mi <- .tmp[[7]])---", r"---(mi1 <- .tmp[[8]])---", r"---(mp <- .tmp[[9]])---"), 'test_spin')
  expect_equal(.run(e, r"---(doit(qapply(.pymul(JxBra(S(1), S(1)), rewrite(JxKet(S(1), S(1)), "Jy")))))---"), r"---(1)---")
  expect_equal(.run(e, r"---(doit(qapply(.pymul(JxBra(S(1), S(0)), rewrite(JxKet(S(1), S(0)), "Jy")))))---"), r"---(1)---")
  expect_equal(.run(e, r"---(doit(qapply(.pymul(JxBra(S(1), S(-1)), rewrite(JxKet(S(1), S(-1)), "Jy")))))---"), r"---(1)---")
  expect_equal(.run(e, r"---(doit(qapply(.pymul(JxBra(S(1), S(1)), rewrite(JxKet(S(1), S(1)), "Jz")))))---"), r"---(1)---")
