  expect_equal(.run(e, r"---(qapply(.pymul(JyBra(S(1), S(1)), rewrite(JyKet(S(1), S(-1)), "Jz"))))---"), r"---(0)---")
  expect_equal(.run(e, r"---(doit(qapply(.pymul(JzBra(S(1), S(1)), rewrite(JzKet(S(1), S(0)), "Jx")))))---"), r"---(0)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JzBra(S(1), S(1)), rewrite(JzKet(S(1), S(-1)), "Jx"))))---"), r"---(0)---")
  expect_equal(.run(e, r"---(doit(qapply(.pymul(JzBra(S(1), S(1)), rewrite(JzKet(S(1), S(0)), "Jy")))))---"), r"---(0)---")
