test_that("test_spin: test_uncouple_2_coupled_states", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j1:5 m1:5"))---", r"---(j1 <- .tmp[[1]])---", r"---(j2 <- .tmp[[2]])---", r"---(j3 <- .tmp[[3]])---", r"---(j4 <- .tmp[[4]])---", r"---(m1 <- .tmp[[5]])---", r"---(m2 <- .tmp[[6]])---", r"---(m3 <- .tmp[[7]])---", r"---(m4 <- .tmp[[8]])---", r"---(.tmp <- sym_symbols("j12 j13 j24 j34 j123 j134 mi mi1 mp"))---", r"---(j12 <- .tmp[[1]])---", r"---(j13 <- .tmp[[2]])---", r"---(j24 <- .tmp[[3]])---", r"---(j34 <- .tmp[[4]])---", r"---(j123 <- .tmp[[5]])---", r"---(j134 <- .tmp[[6]])---", r"---(mi <- .tmp[[7]])---", r"---(mi1 <- .tmp[[8]])---", r"---(mp <- .tmp[[9]])---"), 'test_spin')
  expect_equal(.run(e, r"---(TensorProduct(JzKet(S_Half, S_Half), JzKet(S_Half, S_Half)))---"), r"---(|1/2,1/2>|1/2,1/2>)---")
  expect_equal(.run(e, r"---(TensorProduct(JzKet(S_Half, Rational(S(-1), S(2))), JzKet(S_Half, S_Half)))---"), r"---(|1/2,-1/2>|1/2,1/2>)---")
  expect_equal(.run(e, r"---(TensorProduct(JzKet(S_Half, S_Half), JzKet(S_Half, Rational(S(-1), S(2)))))---"), r"---(|1/2,1/2>|1/2,-1/2>)---")
  expect_equal(.run(e, r"---(TensorProduct(JzKet(S_Half, Rational(S(-1), S(2))), JzKet(S_Half, Rational(S(-1), S(2)))))---"), r"---(|1/2,-1/2>|1/2,-1/2>)---")
  expect_equal(.run(e, r"---(TensorProduct(JzKet(S_Half, S_Half), JzKet(S(1), S(1))))---"), r"---(|1/2,1/2>|1,1>)---")
  expect_equal(.run(e, r"---(TensorProduct(JzKet(S_Half, S_Half), JzKet(S(1), S(0))))---"), r"---(|1/2,1/2>|1,0>)---")
  expect_equal(.run(e, r"---(TensorProduct(JzKet(S_Half, S_Half), JzKet(S(1), S(-1))))---"), r"---(|1/2,1/2>|1,-1>)---")
  expect_equal(.run(e, r"---(TensorProduct(JzKet(S_Half, Rational(S(-1), S(2))), JzKet(S(1), S(1))))---"), r"---(|1/2,-1/2>|1,1>)---")
  expect_equal(.run(e, r"---(TensorProduct(JzKet(S_Half, Rational(S(-1), S(2))), JzKet(S(1), S(0))))---"), r"---(|1/2,-1/2>|1,0>)---")
  expect_equal(.run(e, r"---(TensorProduct(JzKet(S_Half, Rational(S(-1), S(2))), JzKet(S(1), S(-1))))---"), r"---(|1/2,-1/2>|1,-1>)---")
  expect_equal(.run(e, r"---(TensorProduct(JzKet(S(1), S(1)), JzKet(S(1), S(1))))---"), r"---(|1,1>|1,1>)---")
  expect_equal(.run(e, r"---(TensorProduct(JzKet(S(1), S(1)), JzKet(S(1), S(0))))---"), r"---(|1,1>|1,0>)---")
  expect_equal(.run(e, r"---(TensorProduct(JzKet(S(1), S(1)), JzKet(S(1), S(-1))))---"), r"---(|1,1>|1,-1>)---")
  expect_equal(.run(e, r"---(TensorProduct(JzKet(S(1), S(0)), JzKet(S(1), S(1))))---"), r"---(|1,0>|1,1>)---")
  expect_equal(.run(e, r"---(TensorProduct(JzKet(S(1), S(0)), JzKet(S(1), S(0))))---"), r"---(|1,0>|1,0>)---")
  expect_equal(.run(e, r"---(TensorProduct(JzKet(S(1), S(0)), JzKet(S(1), S(-1))))---"), r"---(|1,0>|1,-1>)---")
  expect_equal(.run(e, r"---(TensorProduct(JzKet(S(1), S(-1)), JzKet(S(1), S(1))))---"), r"---(|1,-1>|1,1>)---")
  expect_equal(.run(e, r"---(TensorProduct(JzKet(S(1), S(-1)), JzKet(S(1), S(0))))---"), r"---(|1,-1>|1,0>)---")
  expect_equal(.run(e, r"---(TensorProduct(JzKet(S(1), S(-1)), JzKet(S(1), S(-1))))---"), r"---(|1,-1>|1,-1>)---")
})

