  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(Rational(S(5), S(2)), Rational(S(3), S(2)), list(S_Half, S(1), S(1)))))---"), r"---(sqrt(5)*|1/2,-1/2>|1,1>|1,1>/5 + sqrt(10)*|1/2,1/2>|1,0>|1,1>/5 + sqrt(10)*|1/2,1/2>|1,1>|1,0>/5)---")
