  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(Rational(S(3), S(2)), Rational(S(3), S(2)), list(S_Half, S(1), S(1)))))---"), r"---(-sqrt(30)*|1/2,-1/2>|1,1>|1,1>/15 - 2*sqrt(15)*|1/2,1/2>|1,0>|1,1>/15 + sqrt(15)*|1/2,1/2>|1,1>|1,0>/5)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(Rational(S(3), S(2)), S_Half, list(S_Half, S(1), S(1)))))---"), r"---(-4*sqrt(5)*|1/2,-1/2>|1,0>|1,1>/15 + sqrt(5)*|1/2,-1/2>|1,1>|1,0>/15 - 2*sqrt(10)*|1/2,1/2>|1,-1>|1,1>/15 + sqrt(10)*|1/2,1/2>|1,0>|1,0>/15 + sqrt(10)*|1/2,1/2>|1,1>|1,-1>/5)---")
