  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(3), S(-2), list(S(1), S(1), S(1)))))---"), r"---(sqrt(3)*|1,-1>|1,-1>|1,0>/3 + sqrt(3)*|1,-1>|1,0>|1,-1>/3 + sqrt(3)*|1,0>|1,-1>|1,-1>/3)---")
