  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(2), S(1), list(S(1), S(1), S(1)))))---"), r"---(-sqrt(3)*|1,-1>|1,1>|1,1>/6 - sqrt(3)*|1,0>|1,0>|1,1>/3 + sqrt(3)*|1,0>|1,1>|1,0>/6 - sqrt(3)*|1,1>|1,-1>|1,1>/6 + sqrt(3)*|1,1>|1,0>|1,0>/6 + sqrt(3)*|1,1>|1,1>|1,-1>/3)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(2), S(0), list(S(1), S(1), S(1)))))---"), r"---(-|1,-1>|1,0>|1,1>/2 - |1,0>|1,-1>|1,1>/2 + |1,0>|1,1>|1,-1>/2 + |1,1>|1,0>|1,-1>/2)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(2), S(-1), list(S(1), S(1), S(1)))))---"), r"---(-sqrt(3)*|1,-1>|1,-1>|1,1>/3 - sqrt(3)*|1,-1>|1,0>|1,0>/6 + sqrt(3)*|1,-1>|1,1>|1,-1>/6 - sqrt(3)*|1,0>|1,-1>|1,0>/6 + sqrt(3)*|1,0>|1,0>|1,-1>/3 + sqrt(3)*|1,1>|1,-1>|1,-1>/6)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(2), S(-2), list(S(1), S(1), S(1)))))---"), r"---(-sqrt(6)*|1,-1>|1,-1>|1,0>/3 + sqrt(6)*|1,-1>|1,0>|1,-1>/6 + sqrt(6)*|1,0>|1,-1>|1,-1>/6)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(1), S(1), list(S(1), S(1), S(1)))))---"), r"---(sqrt(15)*|1,-1>|1,1>|1,1>/30 + sqrt(15)*|1,0>|1,0>|1,1>/15 - sqrt(15)*|1,0>|1,1>|1,0>/10 + sqrt(15)*|1,1>|1,-1>|1,1>/30 - sqrt(15)*|1,1>|1,0>|1,0>/10 + sqrt(15)*|1,1>|1,1>|1,-1>/5)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(1), S(0), list(S(1), S(1), S(1)))))---"), r"---(sqrt(15)*|1,-1>|1,0>|1,1>/10 - sqrt(15)*|1,-1>|1,1>|1,0>/15 + sqrt(15)*|1,0>|1,-1>|1,1>/10 - 2*sqrt(15)*|1,0>|1,0>|1,0>/15 + sqrt(15)*|1,0>|1,1>|1,-1>/10 - sqrt(15)*|1,1>|1,-1>|1,0>/15 + sqrt(15)*|1,1>|1,0>|1,-1>/10)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(1), S(-1), list(S(1), S(1), S(1)))))---"), r"---(sqrt(15)*|1,-1>|1,-1>|1,1>/5 - sqrt(15)*|1,-1>|1,0>|1,0>/10 + sqrt(15)*|1,-1>|1,1>|1,-1>/30 - sqrt(15)*|1,0>|1,-1>|1,0>/10 + sqrt(15)*|1,0>|1,0>|1,-1>/15 + sqrt(15)*|1,1>|1,-1>|1,-1>/30)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(1), S(1), list(S_Half, S_Half, S(1)), list(list(S(1), S(3), S_Half), list(S(1), S(2), S(1))))))---"), r"---(-sqrt(6)*|1/2,-1/2>|1/2,1/2>|1,1>/3 + sqrt(3)*|1/2,1/2>|1/2,1/2>|1,0>/3)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(1), S(0), list(S_Half, S_Half, S(1)), list(list(S(1), S(3), S_Half), list(S(1), S(2), S(1))))))---"), r"---(-sqrt(3)*|1/2,-1/2>|1/2,-1/2>|1,1>/3 - sqrt(6)*|1/2,-1/2>|1/2,1/2>|1,0>/6 + sqrt(6)*|1/2,1/2>|1/2,-1/2>|1,0>/6 + sqrt(3)*|1/2,1/2>|1/2,1/2>|1,-1>/3)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(1), S(-1), list(S_Half, S_Half, S(1)), list(list(S(1), S(3), S_Half), list(S(1), S(2), S(1))))))---"), r"---(-sqrt(3)*|1/2,-1/2>|1/2,-1/2>|1,0>/3 + sqrt(6)*|1/2,1/2>|1/2,-1/2>|1,-1>/3)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(Rational(S(3), S(2)), Rational(S(3), S(2)), list(S_Half, S(1), S(1)), list(list(S(1), S(3), S_Half), list(S(1), S(2), Rational(S(3), S(2)))))))---"), r"---(-sqrt(6)*|1/2,-1/2>|1,1>|1,1>/3 + sqrt(3)*|1/2,1/2>|1,1>|1,0>/3)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(Rational(S(3), S(2)), S_Half, list(S_Half, S(1), S(1)), list(list(S(1), S(3), S_Half), list(S(1), S(2), Rational(S(3), S(2)))))))---"), r"---(-2*|1/2,-1/2>|1,0>|1,1>/3 - |1/2,-1/2>|1,1>|1,0>/3 + sqrt(2)*|1/2,1/2>|1,0>|1,0>/3 + sqrt(2)*|1/2,1/2>|1,1>|1,-1>/3)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(Rational(S(3), S(2)), Rational(S(-1), S(2)), list(S_Half, S(1), S(1)), list(list(S(1), S(3), S_Half), list(S(1), S(2), Rational(S(3), S(2)))))))---"), r"---(-sqrt(2)*|1/2,-1/2>|1,-1>|1,1>/3 - sqrt(2)*|1/2,-1/2>|1,0>|1,0>/3 + |1/2,1/2>|1,-1>|1,0>/3 + 2*|1/2,1/2>|1,0>|1,-1>/3)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(Rational(S(3), S(2)), Rational(S(-3), S(2)), list(S_Half, S(1), S(1)), list(list(S(1), S(3), S_Half), list(S(1), S(2), Rational(S(3), S(2)))))))---"), r"---(-sqrt(3)*|1/2,-1/2>|1,-1>|1,0>/3 + sqrt(6)*|1/2,1/2>|1,-1>|1,-1>/3)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(2), S(2), list(S(1), S(1), S(1)), list(list(S(1), S(3), S(1)), list(S(1), S(2), S(2))))))---"), r"---(-sqrt(2)*|1,0>|1,1>|1,1>/2 + sqrt(2)*|1,1>|1,1>|1,0>/2)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(2), S(1), list(S(1), S(1), S(1)), list(list(S(1), S(3), S(1)), list(S(1), S(2), S(2))))))---"), r"---(-|1,-1>|1,1>|1,1>/2 - |1,0>|1,0>|1,1>/2 + |1,1>|1,0>|1,0>/2 + |1,1>|1,1>|1,-1>/2)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(2), S(0), list(S(1), S(1), S(1)), list(list(S(1), S(3), S(1)), list(S(1), S(2), S(2))))))---"), r"---(-sqrt(3)*|1,-1>|1,0>|1,1>/3 - sqrt(3)*|1,-1>|1,1>|1,0>/6 - sqrt(3)*|1,0>|1,-1>|1,1>/6 + sqrt(3)*|1,0>|1,1>|1,-1>/6 + sqrt(3)*|1,1>|1,-1>|1,0>/6 + sqrt(3)*|1,1>|1,0>|1,-1>/3)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(2), S(-1), list(S(1), S(1), S(1)), list(list(S(1), S(3), S(1)), list(S(1), S(2), S(2))))))---"), r"---(-|1,-1>|1,-1>|1,1>/2 - |1,-1>|1,0>|1,0>/2 + |1,0>|1,0>|1,-1>/2 + |1,1>|1,-1>|1,-1>/2)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(2), S(-2), list(S(1), S(1), S(1)), list(list(S(1), S(3), S(1)), list(S(1), S(2), S(2))))))---"), r"---(-sqrt(2)*|1,-1>|1,-1>|1,0>/2 + sqrt(2)*|1,0>|1,-1>|1,-1>/2)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(1), S(1), list(S(1), S(1), S(1)), list(list(S(1), S(3), S(1)), list(S(1), S(2), S(1))))))---"), r"---(|1,-1>|1,1>|1,1>/2 - |1,0>|1,0>|1,1>/2 + |1,1>|1,0>|1,0>/2 - |1,1>|1,1>|1,-1>/2)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(1), S(0), list(S(1), S(1), S(1)), list(list(S(1), S(3), S(1)), list(S(1), S(2), S(1))))))---"), r"---(|1,-1>|1,1>|1,0>/2 - |1,0>|1,-1>|1,1>/2 - |1,0>|1,1>|1,-1>/2 + |1,1>|1,-1>|1,0>/2)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(1), S(-1), list(S(1), S(1), S(1)), list(list(S(1), S(3), S(1)), list(S(1), S(2), S(1))))))---"), r"---(-|1,-1>|1,-1>|1,1>/2 + |1,-1>|1,0>|1,0>/2 - |1,0>|1,0>|1,-1>/2 + |1,1>|1,-1>|1,-1>/2)---")
})

test_that("test_spin: test_uncouple_4_coupled_states_numerical", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j1:5 m1:5"))---", r"---(j1 <- .tmp[[1]])---", r"---(j2 <- .tmp[[2]])---", r"---(j3 <- .tmp[[3]])---", r"---(j4 <- .tmp[[4]])---", r"---(m1 <- .tmp[[5]])---", r"---(m2 <- .tmp[[6]])---", r"---(m3 <- .tmp[[7]])---", r"---(m4 <- .tmp[[8]])---", r"---(.tmp <- sym_symbols("j12 j13 j24 j34 j123 j134 mi mi1 mp"))---", r"---(j12 <- .tmp[[1]])---", r"---(j13 <- .tmp[[2]])---", r"---(j24 <- .tmp[[3]])---", r"---(j34 <- .tmp[[4]])---", r"---(j123 <- .tmp[[5]])---", r"---(j134 <- .tmp[[6]])---", r"---(mi <- .tmp[[7]])---", r"---(mi1 <- .tmp[[8]])---", r"---(mp <- .tmp[[9]])---"), 'test_spin')
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(3), S(3), list(S_Half, S_Half, S(1), S(1)))))---"), r"---(|1/2,1/2>|1/2,1/2>|1,1>|1,1>)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(3), S(2), list(S_Half, S_Half, S(1), S(1)))))---"), r"---(sqrt(6)*|1/2,-1/2>|1/2,1/2>|1,1>|1,1>/6 + sqrt(6)*|1/2,1/2>|1/2,-1/2>|1,1>|1,1>/6 + sqrt(3)*|1/2,1/2>|1/2,1/2>|1,0>|1,1>/3 + sqrt(3)*|1/2,1/2>|1/2,1/2>|1,1>|1,0>/3)---")
