  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(3), S(3), list(S_Half, S_Half, S(1), S(1)), list(list(S(1), S(2), S(1)), list(S(3), S(4), S(2)), list(S(1), S(3), S(3))))))---"), r"---(|1/2,1/2>|1/2,1/2>|1,1>|1,1>)---")
