  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(3), S(1), list(S_Half, S_Half, S(1), S(1)), list(list(S(1), S(2), S(1)), list(S(3), S(4), S(2)), list(S(1), S(3), S(3))))))---"), r"---(sqrt(15)*|1/2,-1/2>|1/2,-1/2>|1,1>|1,1>/15 + sqrt(30)*|1/2,-1/2>|1/2,1/2>|1,0>|1,1>/15 + sqrt(30)*|1/2,-1/2>|1/2,1/2>|1,1>|1,0>/15 + sqrt(30)*|1/2,1/2>|1/2,-1/2>|1,0>|1,1>/15 + sqrt(30)*|1/2,1/2>|1/2,-1/2>|1,1>|1,0>/15 + sqrt(15)*|1/2,1/2>|1/2,1/2>|1,-1>|1,1>/15 + 2*sqrt(15)*|1/2,1/2>|1/2,1/2>|1,0>|1,0>/15 + sqrt(15)*|1/2,1/2>|1/2,1/2>|1,1>|1,-1>/15)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(3), S(0), list(S_Half, S_Half, S(1), S(1)), list(list(S(1), S(2), S(1)), list(S(3), S(4), S(2)), list(S(1), S(3), S(3))))))---"), r"---(sqrt(10)*|1/2,-1/2>|1/2,-1/2>|1,0>|1,1>/10 + sqrt(10)*|1/2,-1/2>|1/2,-1/2>|1,1>|1,0>/10 + sqrt(5)*|1/2,-1/2>|1/2,1/2>|1,-1>|1,1>/10 + sqrt(5)*|1/2,-1/2>|1/2,1/2>|1,0>|1,0>/5 + sqrt(5)*|1/2,-1/2>|1/2,1/2>|1,1>|1,-1>/10 + sqrt(5)*|1/2,1/2>|1/2,-1/2>|1,-1>|1,1>/10 + sqrt(5)*|1/2,1/2>|1/2,-1/2>|1,0>|1,0>/5 + sqrt(5)*|1/2,1/2>|1/2,-1/2>|1,1>|1,-1>/10 + sqrt(10)*|1/2,1/2>|1/2,1/2>|1,-1>|1,0>/10 + sqrt(10)*|1/2,1/2>|1/2,1/2>|1,0>|1,-1>/10)---")
