  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(2), S(2), list(S_Half, S_Half, S(1), S(1)), list(list(S(1), S(2), S(1)), list(S(3), S(4), S(2)), list(S(1), S(3), S(2))))))---"), r"---(-sqrt(3)*|1/2,-1/2>|1/2,1/2>|1,1>|1,1>/3 - sqrt(3)*|1/2,1/2>|1/2,-1/2>|1,1>|1,1>/3 + sqrt(6)*|1/2,1/2>|1/2,1/2>|1,0>|1,1>/6 + sqrt(6)*|1/2,1/2>|1/2,1/2>|1,1>|1,0>/6)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(2), S(1), list(S_Half, S_Half, S(1), S(1)), list(list(S(1), S(2), S(1)), list(S(3), S(4), S(2)), list(S(1), S(3), S(2))))))---"), r"---(-sqrt(3)*|1/2,-1/2>|1/2,-1/2>|1,1>|1,1>/3 - sqrt(6)*|1/2,-1/2>|1/2,1/2>|1,0>|1,1>/12 - sqrt(6)*|1/2,-1/2>|1/2,1/2>|1,1>|1,0>/12 - sqrt(6)*|1/2,1/2>|1/2,-1/2>|1,0>|1,1>/12 - sqrt(6)*|1/2,1/2>|1/2,-1/2>|1,1>|1,0>/12 + sqrt(3)*|1/2,1/2>|1/2,1/2>|1,-1>|1,1>/6 + sqrt(3)*|1/2,1/2>|1/2,1/2>|1,0>|1,0>/3 + sqrt(3)*|1/2,1/2>|1/2,1/2>|1,1>|1,-1>/6)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(2), S(0), list(S_Half, S_Half, S(1), S(1)), list(list(S(1), S(2), S(1)), list(S(3), S(4), S(2)), list(S(1), S(3), S(2))))))---"), r"---(-|1/2,-1/2>|1/2,-1/2>|1,0>|1,1>/2 - |1/2,-1/2>|1/2,-1/2>|1,1>|1,0>/2 + |1/2,1/2>|1/2,1/2>|1,-1>|1,0>/2 + |1/2,1/2>|1/2,1/2>|1,0>|1,-1>/2)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(2), S(-1), list(S_Half, S_Half, S(1), S(1)), list(list(S(1), S(2), S(1)), list(S(3), S(4), S(2)), list(S(1), S(3), S(2))))))---"), r"---(-sqrt(3)*|1/2,-1/2>|1/2,-1/2>|1,-1>|1,1>/6 - sqrt(3)*|1/2,-1/2>|1/2,-1/2>|1,0>|1,0>/3 - sqrt(3)*|1/2,-1/2>|1/2,-1/2>|1,1>|1,-1>/6 + sqrt(6)*|1/2,-1/2>|1/2,1/2>|1,-1>|1,0>/12 + sqrt(6)*|1/2,-1/2>|1/2,1/2>|1,0>|1,-1>/12 + sqrt(6)*|1/2,1/2>|1/2,-1/2>|1,-1>|1,0>/12 + sqrt(6)*|1/2,1/2>|1/2,-1/2>|1,0>|1,-1>/12 + sqrt(3)*|1/2,1/2>|1/2,1/2>|1,-1>|1,-1>/3)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(2), S(-2), list(S_Half, S_Half, S(1), S(1)), list(list(S(1), S(2), S(1)), list(S(3), S(4), S(2)), list(S(1), S(3), S(2))))))---"), r"---(-sqrt(6)*|1/2,-1/2>|1/2,-1/2>|1,-1>|1,0>/6 - sqrt(6)*|1/2,-1/2>|1/2,-1/2>|1,0>|1,-1>/6 + sqrt(3)*|1/2,-1/2>|1/2,1/2>|1,-1>|1,-1>/3 + sqrt(3)*|1/2,1/2>|1/2,-1/2>|1,-1>|1,-1>/3)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(1), S(1), list(S_Half, S_Half, S(1), S(1)), list(list(S(1), S(2), S(1)), list(S(3), S(4), S(2)), list(S(1), S(3), S(1))))))---"), r"---(sqrt(15)*|1/2,-1/2>|1/2,-1/2>|1,1>|1,1>/5 - sqrt(30)*|1/2,-1/2>|1/2,1/2>|1,0>|1,1>/20 - sqrt(30)*|1/2,-1/2>|1/2,1/2>|1,1>|1,0>/20 - sqrt(30)*|1/2,1/2>|1/2,-1/2>|1,0>|1,1>/20 - sqrt(30)*|1/2,1/2>|1/2,-1/2>|1,1>|1,0>/20 + sqrt(15)*|1/2,1/2>|1/2,1/2>|1,-1>|1,1>/30 + sqrt(15)*|1/2,1/2>|1/2,1/2>|1,0>|1,0>/15 + sqrt(15)*|1/2,1/2>|1/2,1/2>|1,1>|1,-1>/30)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(1), S(0), list(S_Half, S_Half, S(1), S(1)), list(list(S(1), S(2), S(1)), list(S(3), S(4), S(2)), list(S(1), S(3), S(1))))))---"), r"---(sqrt(15)*|1/2,-1/2>|1/2,-1/2>|1,0>|1,1>/10 + sqrt(15)*|1/2,-1/2>|1/2,-1/2>|1,1>|1,0>/10 - sqrt(30)*|1/2,-1/2>|1/2,1/2>|1,-1>|1,1>/30 - sqrt(30)*|1/2,-1/2>|1/2,1/2>|1,0>|1,0>/15 - sqrt(30)*|1/2,-1/2>|1/2,1/2>|1,1>|1,-1>/30 - sqrt(30)*|1/2,1/2>|1/2,-1/2>|1,-1>|1,1>/30 - sqrt(30)*|1/2,1/2>|1/2,-1/2>|1,0>|1,0>/15 - sqrt(30)*|1/2,1/2>|1/2,-1/2>|1,1>|1,-1>/30 + sqrt(15)*|1/2,1/2>|1/2,1/2>|1,-1>|1,0>/10 + sqrt(15)*|1/2,1/2>|1/2,1/2>|1,0>|1,-1>/10)---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(S(1), S(-1), list(S_Half, S_Half, S(1), S(1)), list(list(S(1), S(2), S(1)), list(S(3), S(4), S(2)), list(S(1), S(3), S(1))))))---"), r"---(sqrt(15)*|1/2,-1/2>|1/2,-1/2>|1,-1>|1,1>/30 + sqrt(15)*|1/2,-1/2>|1/2,-1/2>|1,0>|1,0>/15 + sqrt(15)*|1/2,-1/2>|1/2,-1/2>|1,1>|1,-1>/30 - sqrt(30)*|1/2,-1/2>|1/2,1/2>|1,-1>|1,0>/20 - sqrt(30)*|1/2,-1/2>|1/2,1/2>|1,0>|1,-1>/20 - sqrt(30)*|1/2,1/2>|1/2,-1/2>|1,-1>|1,0>/20 - sqrt(30)*|1/2,1/2>|1/2,-1/2>|1,0>|1,-1>/20 + sqrt(15)*|1/2,1/2>|1/2,1/2>|1,-1>|1,-1>/5)---")
