test_that("test_spin: test_uncouple_symbolic", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j1:5 m1:5"))---", r"---(j1 <- .tmp[[1]])---", r"---(j2 <- .tmp[[2]])---", r"---(j3 <- .tmp[[3]])---", r"---(j4 <- .tmp[[4]])---", r"---(m1 <- .tmp[[5]])---", r"---(m2 <- .tmp[[6]])---", r"---(m3 <- .tmp[[7]])---", r"---(m4 <- .tmp[[8]])---", r"---(.tmp <- sym_symbols("j12 j13 j24 j34 j123 j134 mi mi1 mp"))---", r"---(j12 <- .tmp[[1]])---", r"---(j13 <- .tmp[[2]])---", r"---(j24 <- .tmp[[3]])---", r"---(j34 <- .tmp[[4]])---", r"---(j123 <- .tmp[[5]])---", r"---(j134 <- .tmp[[6]])---", r"---(mi <- .tmp[[7]])---", r"---(mi1 <- .tmp[[8]])---", r"---(mp <- .tmp[[9]])---"), 'test_spin')
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(Symbol("j"), Symbol("m"), list(j1, j2))))---"), r"---(Sum(CG(j1, m1, j2, m2, j, m)*|j1,m1>|j2,m2>, (m1, -j1, j1), (m2, -j2, j2)))---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(Symbol("j"), Symbol("m"), list(j1, j2, j3))))---"), r"---(Sum(CG(j1, m1, j2, m2, j1 + j2, m1 + m2)*CG(j1 + j2, m1 + m2, j3, m3, j, m)*|j1,m1>|j2,m2>|j3,m3>, (m1, -j1, j1), (m2, -j2, j2), (m3, -j3, j3)))---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(Symbol("j"), Symbol("m"), list(j1, j2, j3), list(list(S(1), S(3), j13), list(S(1), S(2), Symbol("j"))))))---"), r"---(Sum(CG(j1, m1, j3, m3, j13, m1 + m3)*CG(j13, m1 + m3, j2, m2, j, m)*|j1,m1>|j2,m2>|j3,m3>, (m1, -j1, j1), (m2, -j2, j2), (m3, -j3, j3)))---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(Symbol("j"), Symbol("m"), list(j1, j2, j3, j4))))---"), r"---(Sum(CG(j1, m1, j2, m2, j1 + j2, m1 + m2)*CG(j1 + j2, m1 + m2, j3, m3, j1 + j2 + j3, m1 + m2 + m3)*CG(j1 + j2 + j3, m1 + m2 + m3, j4, m4, j, m)*|j1,m1>|j2,m2>|j3,m3>|j4,m4>, (m1, -j1, j1), (m2, -j2, j2), (m3, -j3, j3), (m4, -j4, j4)))---")
  expect_equal(.run(e, r"---(uncouple(JzKetCoupled(Symbol("j"), Symbol("m"), list(j1, j2, j3, j4), list(list(S(1), S(3), j13), list(S(2), S(4), j24), list(S(1), S(2), Symbol("j"))))))---"), r"---(Sum(CG(j1, m1, j3, m3, j13, m1 + m3)*CG(j13, m1 + m3, j24, m2 + m4, j, m)*CG(j2, m2, j4, m4, j24, m2 + m4)*|j1,m1>|j2,m2>|j3,m3>|j4,m4>, (m1, -j1, j1), (m2, -j2, j2), (m3, -j3, j3), (m4, -j4, j4)))---")
})

test_that("test_spin: test_couple_2_states", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j1:5 m1:5"))---", r"---(j1 <- .tmp[[1]])---", r"---(j2 <- .tmp[[2]])---", r"---(j3 <- .tmp[[3]])---", r"---(j4 <- .tmp[[4]])---", r"---(m1 <- .tmp[[5]])---", r"---(m2 <- .tmp[[6]])---", r"---(m3 <- .tmp[[7]])---", r"---(m4 <- .tmp[[8]])---", r"---(.tmp <- sym_symbols("j12 j13 j24 j34 j123 j134 mi mi1 mp"))---", r"---(j12 <- .tmp[[1]])---", r"---(j13 <- .tmp[[2]])---", r"---(j24 <- .tmp[[3]])---", r"---(j34 <- .tmp[[4]])---", r"---(j123 <- .tmp[[5]])---", r"---(j134 <- .tmp[[6]])---", r"---(mi <- .tmp[[7]])---", r"---(mi1 <- .tmp[[8]])---", r"---(mp <- .tmp[[9]])---"), 'test_spin')
  expect_equal(.run(e, r"---(JzKetCoupled(S(0), S(0), list(S_Half, S_Half)))---"), r"---(|0,0,j1=1/2,j2=1/2>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(1), list(S_Half, S_Half)))---"), r"---(|1,1,j1=1/2,j2=1/2>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(0), list(S_Half, S_Half)))---"), r"---(|1,0,j1=1/2,j2=1/2>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(-1), list(S_Half, S_Half)))---"), r"---(|1,-1,j1=1/2,j2=1/2>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S_Half, S_Half, list(S(1), S_Half)))---"), r"---(|1/2,1/2,j1=1,j2=1/2>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S_Half, Rational(S(-1), S(2)), list(S(1), S_Half)))---"), r"---(|1/2,-1/2,j1=1,j2=1/2>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(Rational(S(3), S(2)), Rational(S(3), S(2)), list(S(1), S_Half)))---"), r"---(|3/2,3/2,j1=1,j2=1/2>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(Rational(S(3), S(2)), S_Half, list(S(1), S_Half)))---"), r"---(|3/2,1/2,j1=1,j2=1/2>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(Rational(S(3), S(2)), Rational(S(-1), S(2)), list(S(1), S_Half)))---"), r"---(|3/2,-1/2,j1=1,j2=1/2>)---")
