  expect_equal(.run(e, r"---(JzKetCoupled(S(2), S(-2), list(S(1), S(1))))---"), r"---(|2,-2,j1=1,j2=1>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(1), list(S_Half, Rational(S(3), S(2)))))---"), r"---(|1,1,j1=1/2,j2=3/2>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(0), list(S_Half, Rational(S(3), S(2)))))---"), r"---(|1,0,j1=1/2,j2=3/2>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(-1), list(S_Half, Rational(S(3), S(2)))))---"), r"---(|1,-1,j1=1/2,j2=3/2>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(2), S(2), list(S_Half, Rational(S(3), S(2)))))---"), r"---(|2,2,j1=1/2,j2=3/2>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(2), S(1), list(S_Half, Rational(S(3), S(2)))))---"), r"---(|2,1,j1=1/2,j2=3/2>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(2), S(0), list(S_Half, Rational(S(3), S(2)))))---"), r"---(|2,0,j1=1/2,j2=3/2>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(2), S(-1), list(S_Half, Rational(S(3), S(2)))))---"), r"---(|2,-1,j1=1/2,j2=3/2>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(2), S(-2), list(S_Half, Rational(S(3), S(2)))))---"), r"---(|2,-2,j1=1/2,j2=3/2>)---")
})

