  expect_equal(.run(e, r"---(JzKetCoupled(Rational(S(3), S(2)), S_Half, list(S_Half, S_Half, S_Half)))---"), r"---(|3/2,1/2,j1=1/2,j2=1/2,j3=1/2,j(1,2)=1>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(Rational(S(3), S(2)), Rational(S(-1), S(2)), list(S_Half, S_Half, S_Half)))---"), r"---(|3/2,-1/2,j1=1/2,j2=1/2,j3=1/2,j(1,2)=1>)---")
