  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(1), list(S_Half, S_Half, S(1))))---"), r"---(|1,1,j1=1/2,j2=1/2,j3=1,j(1,2)=1>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(0), list(S_Half, S_Half, S(1))))---"), r"---(|1,0,j1=1/2,j2=1/2,j3=1,j(1,2)=1>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(-1), list(S_Half, S_Half, S(1))))---"), r"---(|1,-1,j1=1/2,j2=1/2,j3=1,j(1,2)=1>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(2), S(2), list(S_Half, S_Half, S(1))))---"), r"---(|2,2,j1=1/2,j2=1/2,j3=1,j(1,2)=1>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(2), S(1), list(S_Half, S_Half, S(1))))---"), r"---(|2,1,j1=1/2,j2=1/2,j3=1,j(1,2)=1>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(2), S(0), list(S_Half, S_Half, S(1))))---"), r"---(|2,0,j1=1/2,j2=1/2,j3=1,j(1,2)=1>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(2), S(-1), list(S_Half, S_Half, S(1))))---"), r"---(|2,-1,j1=1/2,j2=1/2,j3=1,j(1,2)=1>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(2), S(-2), list(S_Half, S_Half, S(1))))---"), r"---(|2,-2,j1=1/2,j2=1/2,j3=1,j(1,2)=1>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S_Half, S_Half, list(S_Half, S_Half, S_Half), list(list(S(1), S(3), S(0)), list(S(1), S(2), S_Half))))---"), r"---(|1/2,1/2,j1=1/2,j2=1/2,j3=1/2,j(1,3)=0>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S_Half, Rational(S(-1), S(2)), list(S_Half, S_Half, S_Half), list(list(S(1), S(3), S(0)), list(S(1), S(2), S_Half))))---"), r"---(|1/2,-1/2,j1=1/2,j2=1/2,j3=1/2,j(1,3)=0>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S_Half, S_Half, list(S(1), S_Half, S(1)), list(list(S(1), S(3), S(1)), list(S(1), S(2), S_Half))))---"), r"---(|1/2,1/2,j1=1,j2=1/2,j3=1,j(1,3)=1>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S_Half, Rational(S(-1), S(2)), list(S(1), S_Half, S(1)), list(list(S(1), S(3), S(1)), list(S(1), S(2), S_Half))))---"), r"---(|1/2,-1/2,j1=1,j2=1/2,j3=1,j(1,3)=1>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(Rational(S(3), S(2)), Rational(S(3), S(2)), list(S(1), S_Half, S(1)), list(list(S(1), S(3), S(1)), list(S(1), S(2), Rational(S(3), S(2))))))---"), r"---(|3/2,3/2,j1=1,j2=1/2,j3=1,j(1,3)=1>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(Rational(S(3), S(2)), S_Half, list(S(1), S_Half, S(1)), list(list(S(1), S(3), S(1)), list(S(1), S(2), Rational(S(3), S(2))))))---"), r"---(|3/2,1/2,j1=1,j2=1/2,j3=1,j(1,3)=1>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(Rational(S(3), S(2)), Rational(S(-1), S(2)), list(S(1), S_Half, S(1)), list(list(S(1), S(3), S(1)), list(S(1), S(2), Rational(S(3), S(2))))))---"), r"---(|3/2,-1/2,j1=1,j2=1/2,j3=1,j(1,3)=1>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(Rational(S(3), S(2)), Rational(S(-3), S(2)), list(S(1), S_Half, S(1)), list(list(S(1), S(3), S(1)), list(S(1), S(2), Rational(S(3), S(2))))))---"), r"---(|3/2,-3/2,j1=1,j2=1/2,j3=1,j(1,3)=1>)---")
})

