  expect_equal(.run(e, r"---(JzKetCoupled(Rational(S(3), S(2)), Rational(S(-3), S(2)), list(S_Half, S_Half, S_Half, S(1)), list(list(S(1), S(3), S(1)), list(S(2), S(4), S_Half), list(S(1), S(2), Rational(S(3), S(2))))))---"), r"---(|3/2,-3/2,j1=1/2,j2=1/2,j3=1/2,j4=1,j(1,3)=1,j(2,4)=1/2>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(1), list(S_Half, S(1), S_Half, S(1)), list(list(S(1), S(3), S(0)), list(S(2), S(4), S(1)), list(S(1), S(2), S(1)))))---"), r"---(|1,1,j1=1/2,j2=1,j3=1/2,j4=1,j(1,3)=0,j(2,4)=1>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(0), list(S_Half, S(1), S_Half, S(1)), list(list(S(1), S(3), S(0)), list(S(2), S(4), S(1)), list(S(1), S(2), S(1)))))---"), r"---(|1,0,j1=1/2,j2=1,j3=1/2,j4=1,j(1,3)=0,j(2,4)=1>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(-1), list(S_Half, S(1), S_Half, S(1)), list(list(S(1), S(3), S(0)), list(S(2), S(4), S(1)), list(S(1), S(2), S(1)))))---"), r"---(|1,-1,j1=1/2,j2=1,j3=1/2,j4=1,j(1,3)=0,j(2,4)=1>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(0), S(0), list(S_Half, S(1), S_Half, S(1)), list(list(S(1), S(3), S(1)), list(S(2), S(4), S(1)), list(S(1), S(2), S(0)))))---"), r"---(|0,0,j1=1/2,j2=1,j3=1/2,j4=1,j(1,3)=1,j(2,4)=1>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(1), list(S_Half, S(1), S_Half, S(1)), list(list(S(1), S(3), S(1)), list(S(2), S(4), S(1)), list(S(1), S(2), S(1)))))---"), r"---(|1,1,j1=1/2,j2=1,j3=1/2,j4=1,j(1,3)=1,j(2,4)=1>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(0), list(S_Half, S(1), S_Half, S(1)), list(list(S(1), S(3), S(1)), list(S(2), S(4), S(1)), list(S(1), S(2), S(1)))))---"), r"---(|1,0,j1=1/2,j2=1,j3=1/2,j4=1,j(1,3)=1,j(2,4)=1>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(-1), list(S_Half, S(1), S_Half, S(1)), list(list(S(1), S(3), S(1)), list(S(2), S(4), S(1)), list(S(1), S(2), S(1)))))---"), r"---(|1,-1,j1=1/2,j2=1,j3=1/2,j4=1,j(1,3)=1,j(2,4)=1>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(2), S(2), list(S_Half, S(1), S_Half, S(1)), list(list(S(1), S(3), S(1)), list(S(2), S(4), S(1)), list(S(1), S(2), S(2)))))---"), r"---(|2,2,j1=1/2,j2=1,j3=1/2,j4=1,j(1,3)=1,j(2,4)=1>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(2), S(1), list(S_Half, S(1), S_Half, S(1)), list(list(S(1), S(3), S(1)), list(S(2), S(4), S(1)), list(S(1), S(2), S(2)))))---"), r"---(|2,1,j1=1/2,j2=1,j3=1/2,j4=1,j(1,3)=1,j(2,4)=1>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(2), S(0), list(S_Half, S(1), S_Half, S(1)), list(list(S(1), S(3), S(1)), list(S(2), S(4), S(1)), list(S(1), S(2), S(2)))))---"), r"---(|2,0,j1=1/2,j2=1,j3=1/2,j4=1,j(1,3)=1,j(2,4)=1>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(2), S(-1), list(S_Half, S(1), S_Half, S(1)), list(list(S(1), S(3), S(1)), list(S(2), S(4), S(1)), list(S(1), S(2), S(2)))))---"), r"---(|2,-1,j1=1/2,j2=1,j3=1/2,j4=1,j(1,3)=1,j(2,4)=1>)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(2), S(-2), list(S_Half, S(1), S_Half, S(1)), list(list(S(1), S(3), S(1)), list(S(2), S(4), S(1)), list(S(1), S(2), S(2)))))---"), r"---(|2,-2,j1=1/2,j2=1,j3=1/2,j4=1,j(1,3)=1,j(2,4)=1>)---")
})

test_that("test_spin: test_couple_2_states_numerical", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j1:5 m1:5"))---", r"---(j1 <- .tmp[[1]])---", r"---(j2 <- .tmp[[2]])---", r"---(j3 <- .tmp[[3]])---", r"---(j4 <- .tmp[[4]])---", r"---(m1 <- .tmp[[5]])---", r"---(m2 <- .tmp[[6]])---", r"---(m3 <- .tmp[[7]])---", r"---(m4 <- .tmp[[8]])---", r"---(.tmp <- sym_symbols("j12 j13 j24 j34 j123 j134 mi mi1 mp"))---", r"---(j12 <- .tmp[[1]])---", r"---(j13 <- .tmp[[2]])---", r"---(j24 <- .tmp[[3]])---", r"---(j34 <- .tmp[[4]])---", r"---(j123 <- .tmp[[5]])---", r"---(j134 <- .tmp[[6]])---", r"---(mi <- .tmp[[7]])---", r"---(mi1 <- .tmp[[8]])---", r"---(mp <- .tmp[[9]])---"), 'test_spin')
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S_Half, S_Half), JzKet(S_Half, S_Half))))---"), r"---(|1,1,j1=1/2,j2=1/2>)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S_Half, S_Half), JzKet(S_Half, Rational(S(-1), S(2))))))---"), r"---(sqrt(2)*|0,0,j1=1/2,j2=1/2>/2 + sqrt(2)*|1,0,j1=1/2,j2=1/2>/2)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S_Half, Rational(S(-1), S(2))), JzKet(S_Half, S_Half))))---"), r"---(-sqrt(2)*|0,0,j1=1/2,j2=1/2>/2 + sqrt(2)*|1,0,j1=1/2,j2=1/2>/2)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S_Half, Rational(S(-1), S(2))), JzKet(S_Half, Rational(S(-1), S(2))))))---"), r"---(|1,-1,j1=1/2,j2=1/2>)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S(1), S(1)), JzKet(S_Half, S_Half))))---"), r"---(|3/2,3/2,j1=1,j2=1/2>)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S(1), S(1)), JzKet(S_Half, Rational(S(-1), S(2))))))---"), r"---(sqrt(6)*|1/2,1/2,j1=1,j2=1/2>/3 + sqrt(3)*|3/2,1/2,j1=1,j2=1/2>/3)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S(1), S(0)), JzKet(S_Half, S_Half))))---"), r"---(-sqrt(3)*|1/2,1/2,j1=1,j2=1/2>/3 + sqrt(6)*|3/2,1/2,j1=1,j2=1/2>/3)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S(1), S(0)), JzKet(S_Half, Rational(S(-1), S(2))))))---"), r"---(sqrt(3)*|1/2,-1/2,j1=1,j2=1/2>/3 + sqrt(6)*|3/2,-1/2,j1=1,j2=1/2>/3)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S(1), S(-1)), JzKet(S_Half, S_Half))))---"), r"---(-sqrt(6)*|1/2,-1/2,j1=1,j2=1/2>/3 + sqrt(3)*|3/2,-1/2,j1=1,j2=1/2>/3)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S(1), S(-1)), JzKet(S_Half, Rational(S(-1), S(2))))))---"), r"---(|3/2,-3/2,j1=1,j2=1/2>)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S(1), S(1)), JzKet(S(1), S(1)))))---"), r"---(|2,2,j1=1,j2=1>)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S(1), S(1)), JzKet(S(1), S(0)))))---"), r"---(sqrt(2)*|1,1,j1=1,j2=1>/2 + sqrt(2)*|2,1,j1=1,j2=1>/2)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S(1), S(1)), JzKet(S(1), S(-1)))))---"), r"---(sqrt(3)*|0,0,j1=1,j2=1>/3 + sqrt(2)*|1,0,j1=1,j2=1>/2 + sqrt(6)*|2,0,j1=1,j2=1>/6)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S(1), S(0)), JzKet(S(1), S(1)))))---"), r"---(-sqrt(2)*|1,1,j1=1,j2=1>/2 + sqrt(2)*|2,1,j1=1,j2=1>/2)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S(1), S(0)), JzKet(S(1), S(0)))))---"), r"---(-sqrt(3)*|0,0,j1=1,j2=1>/3 + sqrt(6)*|2,0,j1=1,j2=1>/3)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S(1), S(0)), JzKet(S(1), S(-1)))))---"), r"---(sqrt(2)*|1,-1,j1=1,j2=1>/2 + sqrt(2)*|2,-1,j1=1,j2=1>/2)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S(1), S(-1)), JzKet(S(1), S(1)))))---"), r"---(sqrt(3)*|0,0,j1=1,j2=1>/3 - sqrt(2)*|1,0,j1=1,j2=1>/2 + sqrt(6)*|2,0,j1=1,j2=1>/6)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S(1), S(-1)), JzKet(S(1), S(0)))))---"), r"---(-sqrt(2)*|1,-1,j1=1,j2=1>/2 + sqrt(2)*|2,-1,j1=1,j2=1>/2)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S(1), S(-1)), JzKet(S(1), S(-1)))))---"), r"---(|2,-2,j1=1,j2=1>)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(Rational(S(3), S(2)), Rational(S(3), S(2))), JzKet(S_Half, S_Half))))---"), r"---(|2,2,j1=3/2,j2=1/2>)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(Rational(S(3), S(2)), Rational(S(3), S(2))), JzKet(S_Half, Rational(S(-1), S(2))))))---"), r"---(sqrt(3)*|1,1,j1=3/2,j2=1/2>/2 + |2,1,j1=3/2,j2=1/2>/2)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(Rational(S(3), S(2)), S_Half), JzKet(S_Half, S_Half))))---"), r"---(-|1,1,j1=3/2,j2=1/2>/2 + sqrt(3)*|2,1,j1=3/2,j2=1/2>/2)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(Rational(S(3), S(2)), S_Half), JzKet(S_Half, Rational(S(-1), S(2))))))---"), r"---(sqrt(2)*|1,0,j1=3/2,j2=1/2>/2 + sqrt(2)*|2,0,j1=3/2,j2=1/2>/2)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(Rational(S(3), S(2)), Rational(S(-1), S(2))), JzKet(S_Half, S_Half))))---"), r"---(-sqrt(2)*|1,0,j1=3/2,j2=1/2>/2 + sqrt(2)*|2,0,j1=3/2,j2=1/2>/2)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(Rational(S(3), S(2)), Rational(S(-1), S(2))), JzKet(S_Half, Rational(S(-1), S(2))))))---"), r"---(|1,-1,j1=3/2,j2=1/2>/2 + sqrt(3)*|2,-1,j1=3/2,j2=1/2>/2)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(Rational(S(3), S(2)), Rational(S(-3), S(2))), JzKet(S_Half, S_Half))))---"), r"---(-sqrt(3)*|1,-1,j1=3/2,j2=1/2>/2 + |2,-1,j1=3/2,j2=1/2>/2)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(Rational(S(3), S(2)), Rational(S(-3), S(2))), JzKet(S_Half, Rational(S(-1), S(2))))))---"), r"---(|2,-2,j1=3/2,j2=1/2>)---")
})

test_that("test_spin: test_couple_3_states_numerical", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j1:5 m1:5"))---", r"---(j1 <- .tmp[[1]])---", r"---(j2 <- .tmp[[2]])---", r"---(j3 <- .tmp[[3]])---", r"---(j4 <- .tmp[[4]])---", r"---(m1 <- .tmp[[5]])---", r"---(m2 <- .tmp[[6]])---", r"---(m3 <- .tmp[[7]])---", r"---(m4 <- .tmp[[8]])---", r"---(.tmp <- sym_symbols("j12 j13 j24 j34 j123 j134 mi mi1 mp"))---", r"---(j12 <- .tmp[[1]])---", r"---(j13 <- .tmp[[2]])---", r"---(j24 <- .tmp[[3]])---", r"---(j34 <- .tmp[[4]])---", r"---(j123 <- .tmp[[5]])---", r"---(j134 <- .tmp[[6]])---", r"---(mi <- .tmp[[7]])---", r"---(mi1 <- .tmp[[8]])---", r"---(mp <- .tmp[[9]])---"), 'test_spin')
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S_Half, S_Half), JzKet(S_Half, S_Half), JzKet(S_Half, S_Half))))---"), r"---(|3/2,3/2,j1=1/2,j2=1/2,j3=1/2,j(1,2)=1>)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S_Half, S_Half), JzKet(S_Half, S_Half), JzKet(S_Half, Rational(S(-1), S(2))))))---"), r"---(sqrt(6)*|1/2,1/2,j1=1/2,j2=1/2,j3=1/2,j(1,2)=1>/3 + sqrt(3)*|3/2,1/2,j1=1/2,j2=1/2,j3=1/2,j(1,2)=1>/3)---")
