  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S_Half, S_Half), JzKet(S_Half, Rational(S(-1), S(2))), JzKet(S_Half, Rational(S(-1), S(2))))))---"), r"---(sqrt(2)*|1/2,-1/2,j1=1/2,j2=1/2,j3=1/2,j(1,2)=0>/2 + sqrt(6)*|1/2,-1/2,j1=1/2,j2=1/2,j3=1/2,j(1,2)=1>/6 + sqrt(3)*|3/2,-1/2,j1=1/2,j2=1/2,j3=1/2,j(1,2)=1>/3)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S_Half, Rational(S(-1), S(2))), JzKet(S_Half, S_Half), JzKet(S_Half, S_Half))))---"), r"---(-sqrt(2)*|1/2,1/2,j1=1/2,j2=1/2,j3=1/2,j(1,2)=0>/2 - sqrt(6)*|1/2,1/2,j1=1/2,j2=1/2,j3=1/2,j(1,2)=1>/6 + sqrt(3)*|3/2,1/2,j1=1/2,j2=1/2,j3=1/2,j(1,2)=1>/3)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S_Half, Rational(S(-1), S(2))), JzKet(S_Half, S_Half), JzKet(S_Half, Rational(S(-1), S(2))))))---"), r"---(-sqrt(2)*|1/2,-1/2,j1=1/2,j2=1/2,j3=1/2,j(1,2)=0>/2 + sqrt(6)*|1/2,-1/2,j1=1/2,j2=1/2,j3=1/2,j(1,2)=1>/6 + sqrt(3)*|3/2,-1/2,j1=1/2,j2=1/2,j3=1/2,j(1,2)=1>/3)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S_Half, Rational(S(-1), S(2))), JzKet(S_Half, Rational(S(-1), S(2))), JzKet(S_Half, S_Half))))---"), r"---(-sqrt(6)*|1/2,-1/2,j1=1/2,j2=1/2,j3=1/2,j(1,2)=1>/3 + sqrt(3)*|3/2,-1/2,j1=1/2,j2=1/2,j3=1/2,j(1,2)=1>/3)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S_Half, Rational(S(-1), S(2))), JzKet(S_Half, Rational(S(-1), S(2))), JzKet(S_Half, Rational(S(-1), S(2))))))---"), r"---(|3/2,-3/2,j1=1/2,j2=1/2,j3=1/2,j(1,2)=1>)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S_Half, S_Half), JzKet(S_Half, S_Half), JzKet(S(1), S(1)))))---"), r"---(|2,2,j1=1/2,j2=1/2,j3=1,j(1,2)=1>)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S_Half, S_Half), JzKet(S_Half, S_Half), JzKet(S(1), S(0)))))---"), r"---(sqrt(2)*|1,1,j1=1/2,j2=1/2,j3=1,j(1,2)=1>/2 + sqrt(2)*|2,1,j1=1/2,j2=1/2,j3=1,j(1,2)=1>/2)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S_Half, S_Half), JzKet(S_Half, S_Half), JzKet(S(1), S(-1)))))---"), r"---(sqrt(3)*|0,0,j1=1/2,j2=1/2,j3=1,j(1,2)=1>/3 + sqrt(2)*|1,0,j1=1/2,j2=1/2,j3=1,j(1,2)=1>/2 + sqrt(6)*|2,0,j1=1/2,j2=1/2,j3=1,j(1,2)=1>/6)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S_Half, S_Half), JzKet(S_Half, Rational(S(-1), S(2))), JzKet(S(1), S(1)))))---"), r"---(sqrt(2)*|1,1,j1=1/2,j2=1/2,j3=1,j(1,2)=0>/2 - |1,1,j1=1/2,j2=1/2,j3=1,j(1,2)=1>/2 + |2,1,j1=1/2,j2=1/2,j3=1,j(1,2)=1>/2)---")
