  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S_Half, Rational(S(-1), S(2))), JzKet(S_Half, Rational(S(-1), S(2))), JzKet(S_Half, Rational(S(-1), S(2))), JzKet(S(1), S(0))), list(list(S(1), S(2)), list(S(3), S(4)), list(S(1), S(3)))))---"), r"---(-sqrt(3)*|3/2,-3/2,j1=1/2,j2=1/2,j3=1/2,j4=1,j(1,2)=1,j(3,4)=1/2>/3 - 2*sqrt(15)*|3/2,-3/2,j1=1/2,j2=1/2,j3=1/2,j4=1,j(1,2)=1,j(3,4)=3/2>/15 + sqrt(10)*|5/2,-3/2,j1=1/2,j2=1/2,j3=1/2,j4=1,j(1,2)=1,j(3,4)=3/2>/5)---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(S_Half, Rational(S(-1), S(2))), JzKet(S_Half, Rational(S(-1), S(2))), JzKet(S_Half, Rational(S(-1), S(2))), JzKet(S(1), S(-1))), list(list(S(1), S(2)), list(S(3), S(4)), list(S(1), S(3)))))---"), r"---(|5/2,-5/2,j1=1/2,j2=1/2,j3=1/2,j4=1,j(1,2)=1,j(3,4)=3/2>)---")
})

test_that("test_spin: test_couple_symbolic", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j1:5 m1:5"))---", r"---(j1 <- .tmp[[1]])---", r"---(j2 <- .tmp[[2]])---", r"---(j3 <- .tmp[[3]])---", r"---(j4 <- .tmp[[4]])---", r"---(m1 <- .tmp[[5]])---", r"---(m2 <- .tmp[[6]])---", r"---(m3 <- .tmp[[7]])---", r"---(m4 <- .tmp[[8]])---", r"---(.tmp <- sym_symbols("j12 j13 j24 j34 j123 j134 mi mi1 mp"))---", r"---(j12 <- .tmp[[1]])---", r"---(j13 <- .tmp[[2]])---", r"---(j24 <- .tmp[[3]])---", r"---(j34 <- .tmp[[4]])---", r"---(j123 <- .tmp[[5]])---", r"---(j134 <- .tmp[[6]])---", r"---(mi <- .tmp[[7]])---", r"---(mi1 <- .tmp[[8]])---", r"---(mp <- .tmp[[9]])---"), 'test_spin')
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(j1, m1), JzKet(j2, m2))))---"), r"---(Sum(CG(j1, m1, j2, m2, j, m1 + m2)*|j,m1 + m2,j1=j1,j2=j2>, (j, m1 + m2, j1 + j2)))---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(j1, m1), JzKet(j2, m2), JzKet(j3, m3))))---"), r"---(Sum(CG(j1, m1, j2, m2, j12, m1 + m2)*CG(j12, m1 + m2, j3, m3, j, m1 + m2 + m3)*|j,m1 + m2 + m3,j1=j1,j2=j2,j3=j3,j(1,2)=j12>, (j12, m1 + m2, j1 + j2), (j, m1 + m2 + m3, j12 + j3)))---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(j1, m1), JzKet(j2, m2), JzKet(j3, m3)), list(list(S(1), S(3)), list(S(1), S(2)))))---"), r"---(Sum(CG(j1, m1, j3, m3, j13, m1 + m3)*CG(j13, m1 + m3, j2, m2, j, m1 + m2 + m3)*|j,m1 + m2 + m3,j1=j1,j2=j2,j3=j3,j(1,3)=j13>, (j13, m1 + m3, j1 + j3), (j, m1 + m2 + m3, j13 + j2)))---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(j1, m1), JzKet(j2, m2), JzKet(j3, m3), JzKet(j4, m4))))---"), r"---(Sum(CG(j1, m1, j2, m2, j12, m1 + m2)*CG(j12, m1 + m2, j3, m3, j123, m1 + m2 + m3)*CG(j123, m1 + m2 + m3, j4, m4, j, m1 + m2 + m3 + m4)*|j,m1 + m2 + m3 + m4,j1=j1,j2=j2,j3=j3,j4=j4,j(1,2)=j12,j(1,2,3)=j123>, (j12, m1 + m2, j1 + j2), (j123, m1 + m2 + m3, j12 + j3), (j, m1 + m2 + m3 + m4, j123 + j4)))---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(j1, m1), JzKet(j2, m2), JzKet(j3, m3), JzKet(j4, m4)), list(list(S(1), S(2)), list(S(3), S(4)), list(S(1), S(3)))))---"), r"---(Sum(CG(j1, m1, j2, m2, j12, m1 + m2)*CG(j12, m1 + m2, j34, m3 + m4, j, m1 + m2 + m3 + m4)*CG(j3, m3, j4, m4, j34, m3 + m4)*|j,m1 + m2 + m3 + m4,j1=j1,j2=j2,j3=j3,j4=j4,j(1,2)=j12,j(3,4)=j34>, (j12, m1 + m2, j1 + j2), (j34, m3 + m4, j3 + j4), (j, m1 + m2 + m3 + m4, j12 + j34)))---")
  expect_equal(.run(e, r"---(couple(TensorProduct(JzKet(j1, m1), JzKet(j2, m2), JzKet(j3, m3), JzKet(j4, m4)), list(list(S(1), S(3)), list(S(1), S(4)), list(S(1), S(2)))))---"), r"---(Sum(CG(j1, m1, j3, m3, j13, m1 + m3)*CG(j13, m1 + m3, j4, m4, j134, m1 + m3 + m4)*CG(j134, m1 + m3 + m4, j2, m2, j, m1 + m2 + m3 + m4)*|j,m1 + m2 + m3 + m4,j1=j1,j2=j2,j3=j3,j4=j4,j(1,3)=j13,j(1,3,4)=j134>, (j13, m1 + m3, j1 + j3), (j134, m1 + m3 + m4, j13 + j4), (j, m1 + m2 + m3 + m4, j134 + j2)))---")
})

test_that("test_spin: test_innerproduct", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j1:5 m1:5"))---", r"---(j1 <- .tmp[[1]])---", r"---(j2 <- .tmp[[2]])---", r"---(j3 <- .tmp[[3]])---", r"---(j4 <- .tmp[[4]])---", r"---(m1 <- .tmp[[5]])---", r"---(m2 <- .tmp[[6]])---", r"---(m3 <- .tmp[[7]])---", r"---(m4 <- .tmp[[8]])---", r"---(.tmp <- sym_symbols("j12 j13 j24 j34 j123 j134 mi mi1 mp"))---", r"---(j12 <- .tmp[[1]])---", r"---(j13 <- .tmp[[2]])---", r"---(j24 <- .tmp[[3]])---", r"---(j34 <- .tmp[[4]])---", r"---(j123 <- .tmp[[5]])---", r"---(j134 <- .tmp[[6]])---", r"---(mi <- .tmp[[7]])---", r"---(mi1 <- .tmp[[8]])---", r"---(mp <- .tmp[[9]])---"), 'test_spin')
  expect_equal(.run(e, r"---(doit(InnerProduct(JzBra(S(1), S(1)), JzKet(S(1), S(1)))))---"), r"---(1)---")
  expect_equal(.run(e, r"---(doit(InnerProduct(JzBra(S_Half, S_Half), JzKet(S_Half, Rational(S(-1), S(2))))))---"), r"---(0)---")
  expect_equal(.run(e, r"---(doit(InnerProduct(JzBra(Symbol("j"), Symbol("m")), JzKet(Symbol("j"), Symbol("m")))))---"), r"---(1)---")
  expect_equal(.run(e, r"---(doit(InnerProduct(JzBra(S(1), S(0)), JyKet(S(1), S(1)))))---"), r"---(sqrt(2)*I/2)---")
  expect_equal(.run(e, r"---(doit(InnerProduct(JxBra(S_Half, S_Half), JzKet(S_Half, S_Half))))---"), r"---(-sqrt(2)/2)---")
  expect_equal(.run(e, r"---(doit(InnerProduct(JyBra(S(1), S(1)), JzKet(S(1), S(1)))))---"), r"---(1/2)---")
  expect_equal(.run(e, r"---(doit(InnerProduct(JxBra(S(1), S(-1)), JyKet(S(1), S(1)))))---"), r"---(0)---")
})

test_that("test_spin: test_rotation_small_d", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j1:5 m1:5"))---", r"---(j1 <- .tmp[[1]])---", r"---(j2 <- .tmp[[2]])---", r"---(j3 <- .tmp[[3]])---", r"---(j4 <- .tmp[[4]])---", r"---(m1 <- .tmp[[5]])---", r"---(m2 <- .tmp[[6]])---", r"---(m3 <- .tmp[[7]])---", r"---(m4 <- .tmp[[8]])---", r"---(.tmp <- sym_symbols("j12 j13 j24 j34 j123 j134 mi mi1 mp"))---", r"---(j12 <- .tmp[[1]])---", r"---(j13 <- .tmp[[2]])---", r"---(j24 <- .tmp[[3]])---", r"---(j34 <- .tmp[[4]])---", r"---(j123 <- .tmp[[5]])---", r"---(j134 <- .tmp[[6]])---", r"---(mi <- .tmp[[7]])---", r"---(mi1 <- .tmp[[8]])---", r"---(mp <- .tmp[[9]])---"), 'test_spin')
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S_Half, S_Half, S_Half, Symbol("beta"))))---"), r"---(cos(beta/2))---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S_Half, S_Half, Rational(S(-1), S(2)), Symbol("beta"))))---"), r"---(-sin(beta/2))---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S_Half, Rational(S(-1), S(2)), S_Half, Symbol("beta"))))---"), r"---(sin(beta/2))---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S_Half, Rational(S(-1), S(2)), Rational(S(-1), S(2)), Symbol("beta"))))---"), r"---(cos(beta/2))---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(1), S(1), S(1), Symbol("beta"))))---"), r"---(cos(beta)/2 + 1/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(1), S(1), S(0), Symbol("beta"))))---"), r"---(-sqrt(2)*sin(beta)/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(1), S(1), S(-1), Symbol("beta"))))---"), r"---(1/2 - cos(beta)/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(1), S(0), S(1), Symbol("beta"))))---"), r"---(sqrt(2)*sin(beta)/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(1), S(0), S(0), Symbol("beta"))))---"), r"---(cos(beta))---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(1), S(0), S(-1), Symbol("beta"))))---"), r"---(-sqrt(2)*sin(beta)/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(1), S(-1), S(1), Symbol("beta"))))---"), r"---(1/2 - cos(beta)/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(1), S(-1), S(0), Symbol("beta"))))---"), r"---(sqrt(2)*sin(beta)/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(1), S(-1), S(-1), Symbol("beta"))))---"), r"---(cos(beta)/2 + 1/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", (S(S(3)) / S(2)), Rational(S(3), S(2)), Rational(S(3), S(2)), Symbol("beta"))))---"), r"---(3*cos(beta/2)/4 + cos(3*beta/2)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", Rational(S(3), S(2)), (S(S(3)) / S(2)), S_Half, Symbol("beta"))))---"), r"---(-sqrt(3)*(sin(beta/2) + sin(3*beta/2))/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", Rational(S(3), S(2)), (S(S(3)) / S(2)), Rational(S(-1), S(2)), Symbol("beta"))))---"), r"---(sqrt(3)*(cos(beta/2) - cos(3*beta/2))/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", Rational(S(3), S(2)), (S(S(3)) / S(2)), Rational(S(-3), S(2)), Symbol("beta"))))---"), r"---(-3*sin(beta/2)/4 + sin(3*beta/2)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", Rational(S(3), S(2)), (S(S(1)) / S(2)), Rational(S(3), S(2)), Symbol("beta"))))---"), r"---(sqrt(3)*(sin(beta/2) + sin(3*beta/2))/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", (S(S(3)) / S(2)), S_Half, S_Half, Symbol("beta"))))---"), r"---(cos(beta/2)/4 + 3*cos(3*beta/2)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", (S(S(3)) / S(2)), S_Half, Rational(S(-1), S(2)), Symbol("beta"))))---"), r"---(sin(beta/2)/4 - 3*sin(3*beta/2)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", Rational(S(3), S(2)), (S(S(1)) / S(2)), Rational(S(-3), S(2)), Symbol("beta"))))---"), r"---(sqrt(3)*(cos(beta/2) - cos(3*beta/2))/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", Rational(S(3), S(2)), ((-S(S(1))) / S(2)), Rational(S(3), S(2)), Symbol("beta"))))---"), r"---(sqrt(3)*(cos(beta/2) - cos(3*beta/2))/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", Rational(S(3), S(2)), ((-S(S(1))) / S(2)), S_Half, Symbol("beta"))))---"), r"---(-sin(beta/2)/4 + 3*sin(3*beta/2)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", Rational(S(3), S(2)), ((-S(S(1))) / S(2)), Rational(S(-1), S(2)), Symbol("beta"))))---"), r"---(cos(beta/2)/4 + 3*cos(3*beta/2)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", Rational(S(3), S(2)), ((-S(S(1))) / S(2)), Rational(S(-3), S(2)), Symbol("beta"))))---"), r"---(-sqrt(3)*(sin(beta/2) + sin(3*beta/2))/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", (S(S(3)) / S(2)), Rational(S(-3), S(2)), Rational(S(3), S(2)), Symbol("beta"))))---"), r"---(3*sin(beta/2)/4 - sin(3*beta/2)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", Rational(S(3), S(2)), ((-S(S(3))) / S(2)), S_Half, Symbol("beta"))))---"), r"---(sqrt(3)*(cos(beta/2) - cos(3*beta/2))/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", Rational(S(3), S(2)), ((-S(S(3))) / S(2)), Rational(S(-1), S(2)), Symbol("beta"))))---"), r"---(sqrt(3)*(sin(beta/2) + sin(3*beta/2))/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", Rational(S(3), S(2)), ((-S(S(3))) / S(2)), Rational(S(-3), S(2)), Symbol("beta"))))---"), r"---(3*cos(beta/2)/4 + cos(3*beta/2)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(2), S(2), Symbol("beta"))))---"), r"---(cos(beta)/2 + cos(2*beta)/8 + 3/8)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(2), S(1), Symbol("beta"))))---"), r"---(-(cos(beta) + 1)*sin(beta)/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(2), S(0), Symbol("beta"))))---"), r"---(sqrt(6)*sin(beta)^2/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(2), S(-1), Symbol("beta"))))---"), r"---((cos(beta) - 1)*sin(beta)/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(2), S(-2), Symbol("beta"))))---"), r"---(-cos(beta)/2 + cos(2*beta)/8 + 3/8)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(1), S(2), Symbol("beta"))))---"), r"---((cos(beta) + 1)*sin(beta)/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(1), S(1), Symbol("beta"))))---"), r"---(cos(beta)/2 + cos(2*beta)/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(1), S(0), Symbol("beta"))))---"), r"---(-sqrt(6)*sin(2*beta)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(1), S(-1), Symbol("beta"))))---"), r"---(cos(beta)/2 - cos(2*beta)/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(1), S(-2), Symbol("beta"))))---"), r"---((cos(beta) - 1)*sin(beta)/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(0), S(2), Symbol("beta"))))---"), r"---(sqrt(6)*sin(beta)^2/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(0), S(1), Symbol("beta"))))---"), r"---(sqrt(6)*sin(2*beta)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(0), S(0), Symbol("beta"))))---"), r"---(3*cos(2*beta)/4 + 1/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(0), S(-1), Symbol("beta"))))---"), r"---(-sqrt(6)*sin(2*beta)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(0), S(-2), Symbol("beta"))))---"), r"---(sqrt(6)*sin(beta)^2/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(-1), S(2), Symbol("beta"))))---"), r"---(sin(beta)/2 - sin(2*beta)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(-1), S(1), Symbol("beta"))))---"), r"---(cos(beta)/2 - cos(2*beta)/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(-1), S(0), Symbol("beta"))))---"), r"---(sqrt(6)*sin(2*beta)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(-1), S(-1), Symbol("beta"))))---"), r"---(cos(beta)/2 + cos(2*beta)/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(-1), S(-2), Symbol("beta"))))---"), r"---(-(cos(beta) + 1)*sin(beta)/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(-2), S(2), Symbol("beta"))))---"), r"---(-cos(beta)/2 + cos(2*beta)/8 + 3/8)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(-2), S(1), Symbol("beta"))))---"), r"---(sin(beta)/2 - sin(2*beta)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(-2), S(0), Symbol("beta"))))---"), r"---(sqrt(6)*sin(beta)^2/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(-2), S(-1), Symbol("beta"))))---"), r"---((cos(beta) + 1)*sin(beta)/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(-2), S(-2), Symbol("beta"))))---"), r"---(cos(beta)/2 + cos(2*beta)/8 + 3/8)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S_Half, S_Half, S_Half, (sym_pi / S(2)))))---"), r"---(sqrt(2)/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S_Half, S_Half, Rational(S(-1), S(2)), (sym_pi / S(2)))))---"), r"---(-sqrt(2)/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S_Half, Rational(S(-1), S(2)), S_Half, (sym_pi / S(2)))))---"), r"---(sqrt(2)/2)---")
