  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", Rational(S(3), S(2)), S_Half, S_Half, (sym_pi / S(2)))))---"), r"---(-sqrt(2)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", Rational(S(3), S(2)), S_Half, Rational(S(-1), S(2)), (sym_pi / S(2)))))---"), r"---(-sqrt(2)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", Rational(S(3), S(2)), S_Half, Rational(S(-3), S(2)), (sym_pi / S(2)))))---"), r"---(sqrt(6)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", Rational(S(3), S(2)), Rational(S(-1), S(2)), Rational(S(3), S(2)), (sym_pi / S(2)))))---"), r"---(sqrt(6)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", Rational(S(3), S(2)), Rational(S(-1), S(2)), S_Half, (sym_pi / S(2)))))---"), r"---(sqrt(2)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", Rational(S(3), S(2)), Rational(S(-1), S(2)), Rational(S(-1), S(2)), (sym_pi / S(2)))))---"), r"---(-sqrt(2)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", Rational(S(3), S(2)), Rational(S(-1), S(2)), Rational(S(-3), S(2)), (sym_pi / S(2)))))---"), r"---(-sqrt(6)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", Rational(S(3), S(2)), Rational(S(-3), S(2)), Rational(S(3), S(2)), (sym_pi / S(2)))))---"), r"---(sqrt(2)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", Rational(S(3), S(2)), Rational(S(-3), S(2)), S_Half, (sym_pi / S(2)))))---"), r"---(sqrt(6)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", Rational(S(3), S(2)), Rational(S(-3), S(2)), Rational(S(-1), S(2)), (sym_pi / S(2)))))---"), r"---(sqrt(6)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", Rational(S(3), S(2)), Rational(S(-3), S(2)), Rational(S(-3), S(2)), (sym_pi / S(2)))))---"), r"---(sqrt(2)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(2), S(2), (sym_pi / S(2)))))---"), r"---(1/4)---")
