  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(1), S(0), (sym_pi / S(2)))))---"), r"---(0)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(1), S(-1), (sym_pi / S(2)))))---"), r"---(1/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(1), S(-2), (sym_pi / S(2)))))---"), r"---(-1/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(0), S(2), (sym_pi / S(2)))))---"), r"---(sqrt(6)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(0), S(1), (sym_pi / S(2)))))---"), r"---(0)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(0), S(0), (sym_pi / S(2)))))---"), r"---(-1/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(0), S(-1), (sym_pi / S(2)))))---"), r"---(0)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(0), S(-2), (sym_pi / S(2)))))---"), r"---(sqrt(6)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(-1), S(2), (sym_pi / S(2)))))---"), r"---(1/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(-1), S(1), (sym_pi / S(2)))))---"), r"---(1/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(-1), S(0), (sym_pi / S(2)))))---"), r"---(0)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(-1), S(-1), (sym_pi / S(2)))))---"), r"---(-1/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(-1), S(-2), (sym_pi / S(2)))))---"), r"---(-1/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(-2), S(2), (sym_pi / S(2)))))---"), r"---(1/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(-2), S(1), (sym_pi / S(2)))))---"), r"---(1/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(-2), S(0), (sym_pi / S(2)))))---"), r"---(sqrt(6)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(-2), S(-1), (sym_pi / S(2)))))---"), r"---(1/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "d", S(2), S(-2), S(-2), (sym_pi / S(2)))))---"), r"---(1/4)---")
})

test_that("test_spin: test_rotation_d", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j1:5 m1:5"))---", r"---(j1 <- .tmp[[1]])---", r"---(j2 <- .tmp[[2]])---", r"---(j3 <- .tmp[[3]])---", r"---(j4 <- .tmp[[4]])---", r"---(m1 <- .tmp[[5]])---", r"---(m2 <- .tmp[[6]])---", r"---(m3 <- .tmp[[7]])---", r"---(m4 <- .tmp[[8]])---", r"---(.tmp <- sym_symbols("j12 j13 j24 j34 j123 j134 mi mi1 mp"))---", r"---(j12 <- .tmp[[1]])---", r"---(j13 <- .tmp[[2]])---", r"---(j24 <- .tmp[[3]])---", r"---(j34 <- .tmp[[4]])---", r"---(j123 <- .tmp[[5]])---", r"---(j134 <- .tmp[[6]])---", r"---(mi <- .tmp[[7]])---", r"---(mi1 <- .tmp[[8]])---", r"---(mp <- .tmp[[9]])---"), 'test_spin')
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S_Half, S_Half, S_Half, Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---(exp(-I*alpha/2)*exp(-I*gamma/2)*cos(beta/2))---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S_Half, S_Half, Rational(S(-1), S(2)), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---(-exp(-I*alpha/2)*exp(I*gamma/2)*sin(beta/2))---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S_Half, Rational(S(-1), S(2)), S_Half, Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---(exp(I*alpha/2)*exp(-I*gamma/2)*sin(beta/2))---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S_Half, Rational(S(-1), S(2)), Rational(S(-1), S(2)), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---(exp(I*alpha/2)*exp(I*gamma/2)*cos(beta/2))---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S(1), S(1), S(1), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---((cos(beta)/2 + 1/2)*exp(-I*alpha)*exp(-I*gamma))---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S(1), S(1), S(0), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---(-sqrt(2)*exp(-I*alpha)*sin(beta)/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S(1), S(1), S(-1), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---((1/2 - cos(beta)/2)*exp(-I*alpha)*exp(I*gamma))---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S(1), S(0), S(1), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---(sqrt(2)*exp(-I*gamma)*sin(beta)/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S(1), S(0), S(0), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---(cos(beta))---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S(1), S(0), S(-1), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---(-sqrt(2)*exp(I*gamma)*sin(beta)/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S(1), S(-1), S(1), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---((1/2 - cos(beta)/2)*exp(I*alpha)*exp(-I*gamma))---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S(1), S(-1), S(0), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---(sqrt(2)*exp(I*alpha)*sin(beta)/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S(1), S(-1), S(-1), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---((cos(beta)/2 + 1/2)*exp(I*alpha)*exp(I*gamma))---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", Rational(S(3), S(2)), Rational(S(3), S(2)), Rational(S(3), S(2)), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---((3*cos(beta/2)/4 + cos(3*beta/2)/4)*exp(-3*I*alpha/2)*exp(-3*I*gamma/2))---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", Rational(S(3), S(2)), Rational(S(3), S(2)), S_Half, Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---(-sqrt(3)*(sin(beta/2) + sin(3*beta/2))*exp(-3*I*alpha/2)*exp(-I*gamma/2)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", Rational(S(3), S(2)), Rational(S(3), S(2)), Rational(S(-1), S(2)), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---(sqrt(3)*(cos(beta/2) - cos(3*beta/2))*exp(-3*I*alpha/2)*exp(I*gamma/2)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", Rational(S(3), S(2)), Rational(S(3), S(2)), Rational(S(-3), S(2)), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---((-3*sin(beta/2)/4 + sin(3*beta/2)/4)*exp(-3*I*alpha/2)*exp(3*I*gamma/2))---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", Rational(S(3), S(2)), S_Half, Rational(S(3), S(2)), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---(sqrt(3)*(sin(beta/2) + sin(3*beta/2))*exp(-I*alpha/2)*exp(-3*I*gamma/2)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", Rational(S(3), S(2)), S_Half, S_Half, Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---((cos(beta/2)/4 + 3*cos(3*beta/2)/4)*exp(-I*alpha/2)*exp(-I*gamma/2))---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", Rational(S(3), S(2)), S_Half, Rational(S(-1), S(2)), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---((sin(beta/2)/4 - 3*sin(3*beta/2)/4)*exp(-I*alpha/2)*exp(I*gamma/2))---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", Rational(S(3), S(2)), S_Half, Rational(S(-3), S(2)), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---(sqrt(3)*(cos(beta/2) - cos(3*beta/2))*exp(-I*alpha/2)*exp(3*I*gamma/2)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", Rational(S(3), S(2)), Rational(S(-1), S(2)), Rational(S(3), S(2)), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---(sqrt(3)*(cos(beta/2) - cos(3*beta/2))*exp(I*alpha/2)*exp(-3*I*gamma/2)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", Rational(S(3), S(2)), Rational(S(-1), S(2)), S_Half, Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---((-sin(beta/2)/4 + 3*sin(3*beta/2)/4)*exp(I*alpha/2)*exp(-I*gamma/2))---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", Rational(S(3), S(2)), Rational(S(-1), S(2)), Rational(S(-1), S(2)), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---((cos(beta/2)/4 + 3*cos(3*beta/2)/4)*exp(I*alpha/2)*exp(I*gamma/2))---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", Rational(S(3), S(2)), Rational(S(-1), S(2)), Rational(S(-3), S(2)), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---(-sqrt(3)*(sin(beta/2) + sin(3*beta/2))*exp(I*alpha/2)*exp(3*I*gamma/2)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", Rational(S(3), S(2)), Rational(S(-3), S(2)), Rational(S(3), S(2)), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---((3*sin(beta/2)/4 - sin(3*beta/2)/4)*exp(3*I*alpha/2)*exp(-3*I*gamma/2))---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", Rational(S(3), S(2)), Rational(S(-3), S(2)), S_Half, Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---(sqrt(3)*(cos(beta/2) - cos(3*beta/2))*exp(3*I*alpha/2)*exp(-I*gamma/2)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", Rational(S(3), S(2)), Rational(S(-3), S(2)), Rational(S(-1), S(2)), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---(sqrt(3)*(sin(beta/2) + sin(3*beta/2))*exp(3*I*alpha/2)*exp(I*gamma/2)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", Rational(S(3), S(2)), Rational(S(-3), S(2)), Rational(S(-3), S(2)), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---((3*cos(beta/2)/4 + cos(3*beta/2)/4)*exp(3*I*alpha/2)*exp(3*I*gamma/2))---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S(2), S(2), S(2), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---((cos(beta)/2 + cos(2*beta)/8 + 3/8)*exp(-2*I*alpha)*exp(-2*I*gamma))---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S(2), S(2), S(1), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---(-(cos(beta) + 1)*exp(-2*I*alpha)*exp(-I*gamma)*sin(beta)/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S(2), S(2), S(0), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---(sqrt(6)*exp(-2*I*alpha)*sin(beta)^2/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S(2), S(2), S(-1), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---((cos(beta) - 1)*exp(-2*I*alpha)*exp(I*gamma)*sin(beta)/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S(2), S(2), S(-2), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---((-cos(beta)/2 + cos(2*beta)/8 + 3/8)*exp(-2*I*alpha)*exp(2*I*gamma))---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S(2), S(1), S(2), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---((cos(beta) + 1)*exp(-I*alpha)*exp(-2*I*gamma)*sin(beta)/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S(2), S(1), S(1), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---((cos(beta)/2 + cos(2*beta)/2)*exp(-I*alpha)*exp(-I*gamma))---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S(2), S(1), S(0), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---(-sqrt(6)*exp(-I*alpha)*sin(2*beta)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S(2), S(1), S(-1), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---((cos(beta)/2 - cos(2*beta)/2)*exp(-I*alpha)*exp(I*gamma))---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S(2), S(1), S(-2), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---((cos(beta) - 1)*exp(-I*alpha)*exp(2*I*gamma)*sin(beta)/2)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S(2), S(0), S(2), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---(sqrt(6)*exp(-2*I*gamma)*sin(beta)^2/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S(2), S(0), S(1), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---(sqrt(6)*exp(-I*gamma)*sin(2*beta)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S(2), S(0), S(0), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---(3*cos(2*beta)/4 + 1/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S(2), S(0), S(-1), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---(-sqrt(6)*exp(I*gamma)*sin(2*beta)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S(2), S(0), S(-2), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---(sqrt(6)*exp(2*I*gamma)*sin(beta)^2/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S(2), S(-1), S(2), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---((sin(beta)/2 - sin(2*beta)/4)*exp(I*alpha)*exp(-2*I*gamma))---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S(2), S(-1), S(1), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---((cos(beta)/2 - cos(2*beta)/2)*exp(I*alpha)*exp(-I*gamma))---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S(2), S(-1), S(0), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---(sqrt(6)*exp(I*alpha)*sin(2*beta)/4)---")
  expect_equal(.run(e, r"---(doit(qcall("Rotation", "D", S(2), S(-1), S(-1), Symbol("alpha"), Symbol("beta"), Symbol("gamma"))))---"), r"---((cos(beta)/2 + cos(2*beta)/2)*exp(I*alpha)*exp(I*gamma))---")
