test_that("test_spin: test_wignerd", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j1:5 m1:5"))---", r"---(j1 <- .tmp[[1]])---", r"---(j2 <- .tmp[[2]])---", r"---(j3 <- .tmp[[3]])---", r"---(j4 <- .tmp[[4]])---", r"---(m1 <- .tmp[[5]])---", r"---(m2 <- .tmp[[6]])---", r"---(m3 <- .tmp[[7]])---", r"---(m4 <- .tmp[[8]])---", r"---(.tmp <- sym_symbols("j12 j13 j24 j34 j123 j134 mi mi1 mp"))---", r"---(j12 <- .tmp[[1]])---", r"---(j13 <- .tmp[[2]])---", r"---(j24 <- .tmp[[3]])---", r"---(j34 <- .tmp[[4]])---", r"---(j123 <- .tmp[[5]])---", r"---(j134 <- .tmp[[6]])---", r"---(mi <- .tmp[[7]])---", r"---(mi1 <- .tmp[[8]])---", r"---(mp <- .tmp[[9]])---"), 'test_spin')
  expect_equal(.run(e, r"---(qcall("Rotation", "D", Symbol("j"), Symbol("m"), mp, Symbol("alpha"), Symbol("beta"), Symbol("gamma")))---"), r"---(WignerD(j, m, mp, alpha, beta, gamma))---")
  expect_equal(.run(e, r"---(qcall("Rotation", "d", Symbol("j"), Symbol("m"), mp, Symbol("beta")))---"), r"---(WignerD(j, m, mp, 0, beta, 0))---")
})

test_that("test_spin: test_wignerD", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j1:5 m1:5"))---", r"---(j1 <- .tmp[[1]])---", r"---(j2 <- .tmp[[2]])---", r"---(j3 <- .tmp[[3]])---", r"---(j4 <- .tmp[[4]])---", r"---(m1 <- .tmp[[5]])---", r"---(m2 <- .tmp[[6]])---", r"---(m3 <- .tmp[[7]])---", r"---(m4 <- .tmp[[8]])---", r"---(.tmp <- sym_symbols("j12 j13 j24 j34 j123 j134 mi mi1 mp"))---", r"---(j12 <- .tmp[[1]])---", r"---(j13 <- .tmp[[2]])---", r"---(j24 <- .tmp[[3]])---", r"---(j34 <- .tmp[[4]])---", r"---(j123 <- .tmp[[5]])---", r"---(j134 <- .tmp[[6]])---", r"---(mi <- .tmp[[7]])---", r"---(mi1 <- .tmp[[8]])---", r"---(mp <- .tmp[[9]])---"), 'test_spin')
  .do(e, r"---(.tmp <- sym_symbols("i j"))---")
  .do(e, r"---(i <- .tmp[[1]])---")
  .do(e, r"---(j <- .tmp[[2]])---")
  expect_equal(.run(e, r"---(qcall("Rotation", "D", S(1), S(1), S(1), S(0), S(0), S(0)))---"), r"---(WignerD(1, 1, 1, 0, 0, 0))---")
  expect_equal(.run(e, r"---(qcall("Rotation", "D", S(1), S(1), S(2), S(0), S(0), S(0)))---"), r"---(WignerD(1, 1, 2, 0, 0, 0))---")
  expect_equal(.run(e, r"---(qcall("Rotation", "D", S(1), ((i ^ S(2)) - (j ^ S(2))), ((i ^ S(2)) - (j ^ S(2))), S(0), S(0), S(0)))---"), r"---(WignerD(1, i^2 - j^2, i^2 - j^2, 0, 0, 0))---")
  expect_equal(.run(e, r"---(qcall("Rotation", "D", S(1), i, i, S(0), S(0), S(0)))---"), r"---(WignerD(1, i, i, 0, 0, 0))---")
  expect_equal(.run(e, r"---(qcall("Rotation", "D", S(1), i, (i + S(1)), S(0), S(0), S(0)))---"), r"---(WignerD(1, i, i + 1, 0, 0, 0))---")
  expect_equal(.run(e, r"---(qcall("Rotation", "D", S(1), S(0), S(0), S(0), S(0), S(0)))---"), r"---(WignerD(1, 0, 0, 0, 0, 0))---")
})

test_that("test_spin: test_jplus", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j1:5 m1:5"))---", r"---(j1 <- .tmp[[1]])---", r"---(j2 <- .tmp[[2]])---", r"---(j3 <- .tmp[[3]])---", r"---(j4 <- .tmp[[4]])---", r"---(m1 <- .tmp[[5]])---", r"---(m2 <- .tmp[[6]])---", r"---(m3 <- .tmp[[7]])---", r"---(m4 <- .tmp[[8]])---", r"---(.tmp <- sym_symbols("j12 j13 j24 j34 j123 j134 mi mi1 mp"))---", r"---(j12 <- .tmp[[1]])---", r"---(j13 <- .tmp[[2]])---", r"---(j24 <- .tmp[[3]])---", r"---(j34 <- .tmp[[4]])---", r"---(j123 <- .tmp[[5]])---", r"---(j134 <- .tmp[[6]])---", r"---(mi <- .tmp[[7]])---", r"---(mi1 <- .tmp[[8]])---", r"---(mp <- .tmp[[9]])---"), 'test_spin')
  expect_equal(.run(e, r"---(doit(Commutator(JplusOp(Symbol("J")), JminusOp(Symbol("J")))))---"), r"---(2*hbar*Jz)---")
  expect_equal(.run(e, r"---(qcall(JplusOp(Symbol("J")), "matrix_element", S(1), S(1), S(1), S(1)))---"), r"---(0)---")
  expect_equal(.run(e, r"---(rewrite(JplusOp(Symbol("J")), "xyz"))---"), r"---(Jx + I*Jy)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JplusOp(Symbol("J")), JxKet(S(1), S(1)))))---"), r"---(-sqrt(2)*hbar*|1,0>/2 + hbar*|1,1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JplusOp(Symbol("J")), JyKet(S(1), S(1)))))---"), r"---(sqrt(2)*hbar*|1,0>/2 + hbar*I*|1,1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JplusOp(Symbol("J")), JzKet(S(1), S(1)))))---"), r"---(0)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JplusOp(Symbol("J")), JxKet(Symbol("j"), Symbol("m")))))---"), r"---(Sum(hbar*sqrt(j^2 + j - mi^2 - mi)*WignerD(j, mi, m, 0, pi/2, 0)*Sum(WignerD(j, mi1, mi + 1, 0, 3*pi/2, 0)*|j,mi1>, (mi1, -j, j)), (mi, -j, j)))---")
  expect_equal(.run(e, r"---(qapply(.pymul(JplusOp(Symbol("J")), JyKet(Symbol("j"), Symbol("m")))))---"), r"---(Sum(hbar*sqrt(j^2 + j - mi^2 - mi)*WignerD(j, mi, m, 3*pi/2, -pi/2, pi/2)*Sum(WignerD(j, mi1, mi + 1, 3*pi/2, pi/2, pi/2)*|j,mi1>, (mi1, -j, j)), (mi, -j, j)))---")
  expect_equal(.run(e, r"---(qapply(.pymul(JplusOp(Symbol("J")), JzKet(Symbol("j"), Symbol("m")))))---"), r"---(hbar*sqrt(j^2 + j - m^2 - m)*|j,m + 1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JplusOp(Symbol("J")), JxKetCoupled(S(1), S(1), list(S(1), S(1))))))---"), r"---(-sqrt(2)*hbar*|1,0,j1=1,j2=1>/2 + hbar*|1,1,j1=1,j2=1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JplusOp(Symbol("J")), JyKetCoupled(S(1), S(1), list(S(1), S(1))))))---"), r"---(sqrt(2)*hbar*|1,0,j1=1,j2=1>/2 + hbar*I*|1,1,j1=1,j2=1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JplusOp(Symbol("J")), JzKet(S(1), S(1)))))---"), r"---(0)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JplusOp(Symbol("J")), JxKetCoupled(Symbol("j"), Symbol("m"), list(j1, j2)))))---"), r"---(Sum(hbar*sqrt(j^2 + j - mi^2 - mi)*WignerD(j, mi, m, 0, pi/2, 0)*Sum(WignerD(j, mi1, mi + 1, 0, 3*pi/2, 0)*|j,mi1,j1=j1,j2=j2>, (mi1, -j, j)), (mi, -j, j)))---")
  expect_equal(.run(e, r"---(qapply(.pymul(JplusOp(Symbol("J")), JyKetCoupled(Symbol("j"), Symbol("m"), list(j1, j2)))))---"), r"---(Sum(hbar*sqrt(j^2 + j - mi^2 - mi)*WignerD(j, mi, m, 3*pi/2, -pi/2, pi/2)*Sum(WignerD(j, mi1, mi + 1, 3*pi/2, pi/2, pi/2)*|j,mi1,j1=j1,j2=j2>, (mi1, -j, j)), (mi, -j, j)))---")
  expect_equal(.run(e, r"---(qapply(.pymul(JplusOp(Symbol("J")), JzKetCoupled(Symbol("j"), Symbol("m"), list(j1, j2)))))---"), r"---(hbar*sqrt(j^2 + j - m^2 - m)*|j,m + 1,j1=j1,j2=j2>)---")
  .do(e, r"---(e1 <- qapply(.pymul(TensorProduct(JplusOp(Symbol("J")), S(1)), TensorProduct(JxKet(S(1), S(1)), JxKet(S(1), S(-1))))))---")
  .do(e, r"---(e2 <- ((.pymul(.pymul((-hbar), sqrt(S(S(2)))), TensorProduct(JxKet(S(1), S(0)), JxKet(S(1), S(-1)))) / S(2)) + .pymul(hbar, TensorProduct(JxKet(S(1), S(1)), JxKet(S(1), S(-1))))))---")
  .do(e, r"---(e1 <- qapply(.pymul(TensorProduct(S(1), JplusOp(Symbol("J"))), TensorProduct(JxKet(S(1), S(1)), JxKet(S(1), S(-1))))))---")
  .do(e, r"---(e2 <- (.pymul((-hbar), TensorProduct(JxKet(S(1), S(1)), JxKet(S(1), S(-1)))) + (.pymul(.pymul(hbar, sqrt(S(S(2)))), TensorProduct(JxKet(S(1), S(1)), JxKet(S(1), S(0)))) / S(2))))---")
  .do(e, r"---(e1 <- qapply(.pymul(TensorProduct(JplusOp(Symbol("J")), S(1)), TensorProduct(JyKet(S(1), S(1)), JyKet(S(1), S(-1))))))---")
  .do(e, r"---(e2 <- ((.pymul(.pymul(hbar, sqrt(S(S(2)))), TensorProduct(JyKet(S(1), S(0)), JyKet(S(1), S(-1)))) / S(2)) + .pymul(.pymul(hbar, sym_I), TensorProduct(JyKet(S(1), S(1)), JyKet(S(1), S(-1))))))---")
  .do(e, r"---(e1 <- qapply(.pymul(TensorProduct(S(1), JplusOp(Symbol("J"))), TensorProduct(JyKet(S(1), S(1)), JyKet(S(1), S(-1))))))---")
  .do(e, r"---(e2 <- (.pymul(.pymul((-hbar), sym_I), TensorProduct(JyKet(S(1), S(1)), JyKet(S(1), S(-1)))) + (.pymul(.pymul(hbar, sqrt(S(S(2)))), TensorProduct(JyKet(S(1), S(1)), JyKet(S(1), S(0)))) / S(2))))---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(JplusOp(Symbol("J")), S(1)), TensorProduct(JzKet(S(1), S(1)), JzKet(S(1), S(-1))))))---"), r"---(0)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(S(1), JplusOp(Symbol("J"))), TensorProduct(JzKet(S(1), S(1)), JzKet(S(1), S(-1))))))---"), r"---(sqrt(2)*hbar*|1,1>|1,0>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(JplusOp(Symbol("J")), S(1)), TensorProduct(JxKet(j1, m1), JxKet(j2, m2)))))---"), r"---(Sum(hbar*sqrt(j1^2 + j1 - mi^2 - mi)*WignerD(j1, mi, m1, 0, pi/2, 0)*Sum(WignerD(j1, mi1, mi + 1, 0, 3*pi/2, 0)*|j1,mi1>, (mi1, -j1, j1)), (mi, -j1, j1))x|j2,m2>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(S(1), JplusOp(Symbol("J"))), TensorProduct(JxKet(j1, m1), JxKet(j2, m2)))))---"), r"---(|j1,m1>Sum(hbar*sqrt(j2^2 + j2 - mi^2 - mi)*WignerD(j2, mi, m2, 0, pi/2, 0)*Sum(WignerD(j2, mi1, mi + 1, 0, 3*pi/2, 0)*|j2,mi1>, (mi1, -j2, j2)), (mi, -j2, j2)))---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(JplusOp(Symbol("J")), S(1)), TensorProduct(JyKet(j1, m1), JyKet(j2, m2)))))---"), r"---(Sum(hbar*sqrt(j1^2 + j1 - mi^2 - mi)*WignerD(j1, mi, m1, 3*pi/2, -pi/2, pi/2)*Sum(WignerD(j1, mi1, mi + 1, 3*pi/2, pi/2, pi/2)*|j1,mi1>, (mi1, -j1, j1)), (mi, -j1, j1))x|j2,m2>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(S(1), JplusOp(Symbol("J"))), TensorProduct(JyKet(j1, m1), JyKet(j2, m2)))))---"), r"---(|j1,m1>Sum(hbar*sqrt(j2^2 + j2 - mi^2 - mi)*WignerD(j2, mi, m2, 3*pi/2, -pi/2, pi/2)*Sum(WignerD(j2, mi1, mi + 1, 3*pi/2, pi/2, pi/2)*|j2,mi1>, (mi1, -j2, j2)), (mi, -j2, j2)))---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(JplusOp(Symbol("J")), S(1)), TensorProduct(JzKet(j1, m1), JzKet(j2, m2)))))---"), r"---(hbar*sqrt(j1^2 + j1 - m1^2 - m1)*|j1,m1 + 1>|j2,m2>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(S(1), JplusOp(Symbol("J"))), TensorProduct(JzKet(j1, m1), JzKet(j2, m2)))))---"), r"---(hbar*sqrt(j2^2 + j2 - m2^2 - m2)*|j1,m1>|j2,m2 + 1>)---")
})

test_that("test_spin: test_jminus", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j1:5 m1:5"))---", r"---(j1 <- .tmp[[1]])---", r"---(j2 <- .tmp[[2]])---", r"---(j3 <- .tmp[[3]])---", r"---(j4 <- .tmp[[4]])---", r"---(m1 <- .tmp[[5]])---", r"---(m2 <- .tmp[[6]])---", r"---(m3 <- .tmp[[7]])---", r"---(m4 <- .tmp[[8]])---", r"---(.tmp <- sym_symbols("j12 j13 j24 j34 j123 j134 mi mi1 mp"))---", r"---(j12 <- .tmp[[1]])---", r"---(j13 <- .tmp[[2]])---", r"---(j24 <- .tmp[[3]])---", r"---(j34 <- .tmp[[4]])---", r"---(j123 <- .tmp[[5]])---", r"---(j134 <- .tmp[[6]])---", r"---(mi <- .tmp[[7]])---", r"---(mi1 <- .tmp[[8]])---", r"---(mp <- .tmp[[9]])---"), 'test_spin')
  expect_equal(.run(e, r"---(qapply(.pymul(JminusOp(Symbol("J")), JzKet(S(1), S(-1)))))---"), r"---(0)---")
  expect_equal(.run(e, r"---(qcall(JminusOp(Symbol("J")), "matrix_element", S(1), S(0), S(1), S(1)))---"), r"---(sqrt(2)*hbar)---")
  expect_equal(.run(e, r"---(rewrite(JminusOp(Symbol("J")), "xyz"))---"), r"---(Jx - I*Jy)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JminusOp(Symbol("J")), JxKet(S(1), S(1)))))---"), r"---(sqrt(2)*hbar*|1,0>/2 + hbar*|1,1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JminusOp(Symbol("J")), JyKet(S(1), S(1)))))---"), r"---(sqrt(2)*hbar*|1,0>/2 - hbar*I*|1,1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JminusOp(Symbol("J")), JzKet(S(1), S(1)))))---"), r"---(sqrt(2)*hbar*|1,0>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JminusOp(Symbol("J")), JxKet(Symbol("j"), Symbol("m")))))---"), r"---(Sum(hbar*sqrt(j^2 + j - mi^2 + mi)*WignerD(j, mi, m, 0, pi/2, 0)*Sum(WignerD(j, mi1, mi - 1, 0, 3*pi/2, 0)*|j,mi1>, (mi1, -j, j)), (mi, -j, j)))---")
  expect_equal(.run(e, r"---(qapply(.pymul(JminusOp(Symbol("J")), JyKet(Symbol("j"), Symbol("m")))))---"), r"---(Sum(hbar*sqrt(j^2 + j - mi^2 + mi)*WignerD(j, mi, m, 3*pi/2, -pi/2, pi/2)*Sum(WignerD(j, mi1, mi - 1, 3*pi/2, pi/2, pi/2)*|j,mi1>, (mi1, -j, j)), (mi, -j, j)))---")
  expect_equal(.run(e, r"---(qapply(.pymul(JminusOp(Symbol("J")), JzKet(Symbol("j"), Symbol("m")))))---"), r"---(hbar*sqrt(j^2 + j - m^2 + m)*|j,m - 1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JminusOp(Symbol("J")), JxKetCoupled(S(1), S(1), list(S(1), S(1))))))---"), r"---(sqrt(2)*hbar*|1,0,j1=1,j2=1>/2 + hbar*|1,1,j1=1,j2=1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JminusOp(Symbol("J")), JyKetCoupled(S(1), S(1), list(S(1), S(1))))))---"), r"---(sqrt(2)*hbar*|1,0,j1=1,j2=1>/2 - hbar*I*|1,1,j1=1,j2=1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JminusOp(Symbol("J")), JzKetCoupled(S(1), S(1), list(S(1), S(1))))))---"), r"---(sqrt(2)*hbar*|1,0,j1=1,j2=1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JminusOp(Symbol("J")), JxKetCoupled(Symbol("j"), Symbol("m"), list(j1, j2)))))---"), r"---(Sum(hbar*sqrt(j^2 + j - mi^2 + mi)*WignerD(j, mi, m, 0, pi/2, 0)*Sum(WignerD(j, mi1, mi - 1, 0, 3*pi/2, 0)*|j,mi1,j1=j1,j2=j2>, (mi1, -j, j)), (mi, -j, j)))---")
  expect_equal(.run(e, r"---(qapply(.pymul(JminusOp(Symbol("J")), JyKetCoupled(Symbol("j"), Symbol("m"), list(j1, j2)))))---"), r"---(Sum(hbar*sqrt(j^2 + j - mi^2 + mi)*WignerD(j, mi, m, 3*pi/2, -pi/2, pi/2)*Sum(WignerD(j, mi1, mi - 1, 3*pi/2, pi/2, pi/2)*|j,mi1,j1=j1,j2=j2>, (mi1, -j, j)), (mi, -j, j)))---")
  expect_equal(.run(e, r"---(qapply(.pymul(JminusOp(Symbol("J")), JzKetCoupled(Symbol("j"), Symbol("m"), list(j1, j2)))))---"), r"---(hbar*sqrt(j^2 + j - m^2 + m)*|j,m - 1,j1=j1,j2=j2>)---")
  .do(e, r"---(e1 <- qapply(.pymul(TensorProduct(JminusOp(Symbol("J")), S(1)), TensorProduct(JxKet(S(1), S(1)), JxKet(S(1), S(-1))))))---")
  .do(e, r"---(e2 <- ((.pymul(.pymul(hbar, sqrt(S(S(2)))), TensorProduct(JxKet(S(1), S(0)), JxKet(S(1), S(-1)))) / S(2)) + .pymul(hbar, TensorProduct(JxKet(S(1), S(1)), JxKet(S(1), S(-1))))))---")
  .do(e, r"---(e1 <- qapply(.pymul(TensorProduct(S(1), JminusOp(Symbol("J"))), TensorProduct(JxKet(S(1), S(1)), JxKet(S(1), S(-1))))))---")
  .do(e, r"---(e2 <- (.pymul((-hbar), TensorProduct(JxKet(S(1), S(1)), JxKet(S(1), S(-1)))) - (.pymul(.pymul(hbar, sqrt(S(S(2)))), TensorProduct(JxKet(S(1), S(1)), JxKet(S(1), S(0)))) / S(2))))---")
  .do(e, r"---(e1 <- qapply(.pymul(TensorProduct(JminusOp(Symbol("J")), S(1)), TensorProduct(JyKet(S(1), S(1)), JyKet(S(1), S(-1))))))---")
  .do(e, r"---(e2 <- ((.pymul(.pymul(hbar, sqrt(S(S(2)))), TensorProduct(JyKet(S(1), S(0)), JyKet(S(1), S(-1)))) / S(2)) - .pymul(.pymul(hbar, sym_I), TensorProduct(JyKet(S(1), S(1)), JyKet(S(1), S(-1))))))---")
  .do(e, r"---(e1 <- qapply(.pymul(TensorProduct(S(1), JminusOp(Symbol("J"))), TensorProduct(JyKet(S(1), S(1)), JyKet(S(1), S(-1))))))---")
  .do(e, r"---(e2 <- (.pymul(.pymul(hbar, sym_I), TensorProduct(JyKet(S(1), S(1)), JyKet(S(1), S(-1)))) + (.pymul(.pymul(hbar, sqrt(S(S(2)))), TensorProduct(JyKet(S(1), S(1)), JyKet(S(1), S(0)))) / S(2))))---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(JminusOp(Symbol("J")), S(1)), TensorProduct(JzKet(S(1), S(1)), JzKet(S(1), S(-1))))))---"), r"---(sqrt(2)*hbar*|1,0>|1,-1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(S(1), JminusOp(Symbol("J"))), TensorProduct(JzKet(S(1), S(1)), JzKet(S(1), S(-1))))))---"), r"---(0)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(JminusOp(Symbol("J")), S(1)), TensorProduct(JxKet(j1, m1), JxKet(j2, m2)))))---"), r"---(Sum(hbar*sqrt(j1^2 + j1 - mi^2 + mi)*WignerD(j1, mi, m1, 0, pi/2, 0)*Sum(WignerD(j1, mi1, mi - 1, 0, 3*pi/2, 0)*|j1,mi1>, (mi1, -j1, j1)), (mi, -j1, j1))x|j2,m2>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(S(1), JminusOp(Symbol("J"))), TensorProduct(JxKet(j1, m1), JxKet(j2, m2)))))---"), r"---(|j1,m1>Sum(hbar*sqrt(j2^2 + j2 - mi^2 + mi)*WignerD(j2, mi, m2, 0, pi/2, 0)*Sum(WignerD(j2, mi1, mi - 1, 0, 3*pi/2, 0)*|j2,mi1>, (mi1, -j2, j2)), (mi, -j2, j2)))---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(JminusOp(Symbol("J")), S(1)), TensorProduct(JyKet(j1, m1), JyKet(j2, m2)))))---"), r"---(Sum(hbar*sqrt(j1^2 + j1 - mi^2 + mi)*WignerD(j1, mi, m1, 3*pi/2, -pi/2, pi/2)*Sum(WignerD(j1, mi1, mi - 1, 3*pi/2, pi/2, pi/2)*|j1,mi1>, (mi1, -j1, j1)), (mi, -j1, j1))x|j2,m2>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(S(1), JminusOp(Symbol("J"))), TensorProduct(JyKet(j1, m1), JyKet(j2, m2)))))---"), r"---(|j1,m1>Sum(hbar*sqrt(j2^2 + j2 - mi^2 + mi)*WignerD(j2, mi, m2, 3*pi/2, -pi/2, pi/2)*Sum(WignerD(j2, mi1, mi - 1, 3*pi/2, pi/2, pi/2)*|j2,mi1>, (mi1, -j2, j2)), (mi, -j2, j2)))---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(JminusOp(Symbol("J")), S(1)), TensorProduct(JzKet(j1, m1), JzKet(j2, m2)))))---"), r"---(hbar*sqrt(j1^2 + j1 - m1^2 + m1)*|j1,m1 - 1>|j2,m2>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(S(1), JminusOp(Symbol("J"))), TensorProduct(JzKet(j1, m1), JzKet(j2, m2)))))---"), r"---(hbar*sqrt(j2^2 + j2 - m2^2 + m2)*|j1,m1>|j2,m2 - 1>)---")
})

test_that("test_spin: test_j2", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j1:5 m1:5"))---", r"---(j1 <- .tmp[[1]])---", r"---(j2 <- .tmp[[2]])---", r"---(j3 <- .tmp[[3]])---", r"---(j4 <- .tmp[[4]])---", r"---(m1 <- .tmp[[5]])---", r"---(m2 <- .tmp[[6]])---", r"---(m3 <- .tmp[[7]])---", r"---(m4 <- .tmp[[8]])---", r"---(.tmp <- sym_symbols("j12 j13 j24 j34 j123 j134 mi mi1 mp"))---", r"---(j12 <- .tmp[[1]])---", r"---(j13 <- .tmp[[2]])---", r"---(j24 <- .tmp[[3]])---", r"---(j34 <- .tmp[[4]])---", r"---(j123 <- .tmp[[5]])---", r"---(j134 <- .tmp[[6]])---", r"---(mi <- .tmp[[7]])---", r"---(mi1 <- .tmp[[8]])---", r"---(mp <- .tmp[[9]])---"), 'test_spin')
  expect_equal(.run(e, r"---(doit(Commutator(J2Op(Symbol("J")), JzOp(Symbol("J")))))---"), r"---(0)---")
  expect_equal(.run(e, r"---(qcall(J2Op(Symbol("J")), "matrix_element", S(1), S(1), S(1), S(1)))---"), r"---(2*hbar^2)---")
  expect_equal(.run(e, r"---(qapply(.pymul(J2Op(Symbol("J")), JxKet(S(1), S(1)))))---"), r"---(2*hbar^2*|1,1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(J2Op(Symbol("J")), JyKet(S(1), S(1)))))---"), r"---(2*hbar^2*|1,1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(J2Op(Symbol("J")), JzKet(S(1), S(1)))))---"), r"---(2*hbar^2*|1,1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(J2Op(Symbol("J")), JxKet(Symbol("j"), Symbol("m")))))---"), r"---(hbar^2*j^2*|j,m> + hbar^2*j*|j,m>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(J2Op(Symbol("J")), JyKet(Symbol("j"), Symbol("m")))))---"), r"---(hbar^2*j^2*|j,m> + hbar^2*j*|j,m>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(J2Op(Symbol("J")), JzKet(Symbol("j"), Symbol("m")))))---"), r"---(hbar^2*j^2*|j,m> + hbar^2*j*|j,m>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(J2Op(Symbol("J")), JxKetCoupled(S(1), S(1), list(S(1), S(1))))))---"), r"---(2*hbar^2*|1,1,j1=1,j2=1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(J2Op(Symbol("J")), JyKetCoupled(S(1), S(1), list(S(1), S(1))))))---"), r"---(2*hbar^2*|1,1,j1=1,j2=1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(J2Op(Symbol("J")), JzKetCoupled(S(1), S(1), list(S(1), S(1))))))---"), r"---(2*hbar^2*|1,1,j1=1,j2=1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(J2Op(Symbol("J")), JxKetCoupled(Symbol("j"), Symbol("m"), list(j1, j2)))))---"), r"---(hbar^2*j^2*|j,m,j1=j1,j2=j2> + hbar^2*j*|j,m,j1=j1,j2=j2>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(J2Op(Symbol("J")), JyKetCoupled(Symbol("j"), Symbol("m"), list(j1, j2)))))---"), r"---(hbar^2*j^2*|j,m,j1=j1,j2=j2> + hbar^2*j*|j,m,j1=j1,j2=j2>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(J2Op(Symbol("J")), JzKetCoupled(Symbol("j"), Symbol("m"), list(j1, j2)))))---"), r"---(hbar^2*j^2*|j,m,j1=j1,j2=j2> + hbar^2*j*|j,m,j1=j1,j2=j2>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(J2Op(Symbol("J")), S(1)), TensorProduct(JxKet(S(1), S(1)), JxKet(S(1), S(-1))))))---"), r"---(2*hbar^2*|1,1>|1,-1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(S(1), J2Op(Symbol("J"))), TensorProduct(JxKet(S(1), S(1)), JxKet(S(1), S(-1))))))---"), r"---(2*hbar^2*|1,1>|1,-1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(J2Op(Symbol("J")), S(1)), TensorProduct(JyKet(S(1), S(1)), JyKet(S(1), S(-1))))))---"), r"---(2*hbar^2*|1,1>|1,-1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(S(1), J2Op(Symbol("J"))), TensorProduct(JyKet(S(1), S(1)), JyKet(S(1), S(-1))))))---"), r"---(2*hbar^2*|1,1>|1,-1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(J2Op(Symbol("J")), S(1)), TensorProduct(JzKet(S(1), S(1)), JzKet(S(1), S(-1))))))---"), r"---(2*hbar^2*|1,1>|1,-1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(S(1), J2Op(Symbol("J"))), TensorProduct(JzKet(S(1), S(1)), JzKet(S(1), S(-1))))))---"), r"---(2*hbar^2*|1,1>|1,-1>)---")
})

test_that("test_spin: test_jx", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j1:5 m1:5"))---", r"---(j1 <- .tmp[[1]])---", r"---(j2 <- .tmp[[2]])---", r"---(j3 <- .tmp[[3]])---", r"---(j4 <- .tmp[[4]])---", r"---(m1 <- .tmp[[5]])---", r"---(m2 <- .tmp[[6]])---", r"---(m3 <- .tmp[[7]])---", r"---(m4 <- .tmp[[8]])---", r"---(.tmp <- sym_symbols("j12 j13 j24 j34 j123 j134 mi mi1 mp"))---", r"---(j12 <- .tmp[[1]])---", r"---(j13 <- .tmp[[2]])---", r"---(j24 <- .tmp[[3]])---", r"---(j34 <- .tmp[[4]])---", r"---(j123 <- .tmp[[5]])---", r"---(j134 <- .tmp[[6]])---", r"---(mi <- .tmp[[7]])---", r"---(mi1 <- .tmp[[8]])---", r"---(mp <- .tmp[[9]])---"), 'test_spin')
  expect_equal(.run(e, r"---(doit(Commutator(JxOp(Symbol("J")), JzOp(Symbol("J")))))---"), r"---(-hbar*I*Jy)---")
  expect_equal(.run(e, r"---(rewrite(JxOp(Symbol("J")), "plusminus"))---"), r"---((J- + J+)/2)---")
  expect_equal(.run(e, r"---(represent(JxOp(Symbol("J")), basis = JzOp(Symbol("J")), j = S(1)))---"), r"---(Matrix([[0, sqrt(2)*hbar/2, 0], [sqrt(2)*hbar/2, 0, sqrt(2)*hbar/2], [0, sqrt(2)*hbar/2, 0]]))---")
  expect_equal(.run(e, r"---(qapply(.pymul(JxOp(Symbol("J")), JxKet(S(1), S(1)))))---"), r"---(hbar*|1,1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JxOp(Symbol("J")), JyKet(S(1), S(1)))))---"), r"---(hbar*|1,1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JxOp(Symbol("J")), JzKet(S(1), S(1)))))---"), r"---(sqrt(2)*hbar*|1,0>/2)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JxOp(Symbol("J")), JxKet(Symbol("j"), Symbol("m")))))---"), r"---(hbar*m*|j,m>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JxOp(Symbol("J")), JyKet(Symbol("j"), Symbol("m")))))---"), r"---(Sum(hbar*mi*WignerD(j, mi, m, 0, 0, pi/2)*Sum(WignerD(j, mi1, mi, 3*pi/2, 0, 0)*|j,mi1>, (mi1, -j, j)), (mi, -j, j)))---")
  expect_equal(.run(e, r"---(qapply(.pymul(JxOp(Symbol("J")), JzKet(Symbol("j"), Symbol("m")))))---"), r"---(hbar*sqrt(j^2 + j - m^2 - m)*|j,m + 1>/2 + hbar*sqrt(j^2 + j - m^2 + m)*|j,m - 1>/2)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JxOp(Symbol("J")), JxKetCoupled(S(1), S(1), list(S(1), S(1))))))---"), r"---(hbar*|1,1,j1=1,j2=1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JxOp(Symbol("J")), JyKetCoupled(S(1), S(1), list(S(1), S(1))))))---"), r"---(hbar*|1,1,j1=1,j2=1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JxOp(Symbol("J")), JzKetCoupled(S(1), S(1), list(S(1), S(1))))))---"), r"---(sqrt(2)*hbar*|1,0,j1=1,j2=1>/2)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JxOp(Symbol("J")), JxKetCoupled(Symbol("j"), Symbol("m"), list(j1, j2)))))---"), r"---(hbar*m*|j,m,j1=j1,j2=j2>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JxOp(Symbol("J")), JyKetCoupled(Symbol("j"), Symbol("m"), list(j1, j2)))))---"), r"---(Sum(hbar*mi*WignerD(j, mi, m, 0, 0, pi/2)*Sum(WignerD(j, mi1, mi, 3*pi/2, 0, 0)*|j,mi1,j1=j1,j2=j2>, (mi1, -j, j)), (mi, -j, j)))---")
  expect_equal(.run(e, r"---(qapply(.pymul(JxOp(Symbol("J")), JzKetCoupled(Symbol("j"), Symbol("m"), list(j1, j2)))))---"), r"---(hbar*sqrt(j^2 + j - m^2 - m)*|j,m + 1,j1=j1,j2=j2>/2 + hbar*sqrt(j^2 + j - m^2 + m)*|j,m - 1,j1=j1,j2=j2>/2)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JxOp(Symbol("J")), TensorProduct(JxKet(S(1), S(1)), JxKet(S(1), S(1))))))---"), r"---(2*hbar*|1,1>|1,1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JxOp(Symbol("J")), TensorProduct(JyKet(S(1), S(1)), JyKet(S(1), S(1))))))---"), r"---(2*hbar*|1,1>|1,1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JxOp(Symbol("J")), TensorProduct(JzKet(S(1), S(1)), JzKet(S(1), S(1))))))---"), r"---(sqrt(2)*hbar*|1,0>|1,1>/2 + sqrt(2)*hbar*|1,1>|1,0>/2)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JxOp(Symbol("J")), TensorProduct(JxKet(S(1), S(1)), JxKet(S(1), S(-1))))))---"), r"---(0)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JxOp(Symbol("J")), TensorProduct(JxKet(j1, m1), JxKet(j2, m2)))))---"), r"---(hbar*m1*|j1,m1>|j2,m2> + hbar*m2*|j1,m1>|j2,m2>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JxOp(Symbol("J")), TensorProduct(JyKet(j1, m1), JyKet(j2, m2)))))---"), r"---(|j1,m1>Sum(hbar*mi*WignerD(j2, mi, m2, 0, 0, pi/2)*Sum(WignerD(j2, mi1, mi, 3*pi/2, 0, 0)*|j2,mi1>, (mi1, -j2, j2)), (mi, -j2, j2)) + Sum(hbar*mi*WignerD(j1, mi, m1, 0, 0, pi/2)*Sum(WignerD(j1, mi1, mi, 3*pi/2, 0, 0)*|j1,mi1>, (mi1, -j1, j1)), (mi, -j1, j1))x|j2,m2>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JxOp(Symbol("J")), TensorProduct(JzKet(j1, m1), JzKet(j2, m2)))))---"), r"---(hbar*sqrt(j1^2 + j1 - m1^2 - m1)*|j1,m1 + 1>|j2,m2>/2 + hbar*sqrt(j1^2 + j1 - m1^2 + m1)*|j1,m1 - 1>|j2,m2>/2 + hbar*sqrt(j2^2 + j2 - m2^2 - m2)*|j1,m1>|j2,m2 + 1>/2 + hbar*sqrt(j2^2 + j2 - m2^2 + m2)*|j1,m1>|j2,m2 - 1>/2)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(JxOp(Symbol("J")), S(1)), TensorProduct(JxKet(S(1), S(1)), JxKet(S(1), S(-1))))))---"), r"---(hbar*|1,1>|1,-1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(S(1), JxOp(Symbol("J"))), TensorProduct(JxKet(S(1), S(1)), JxKet(S(1), S(-1))))))---"), r"---(-hbar*|1,1>|1,-1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(JxOp(Symbol("J")), S(1)), TensorProduct(JyKet(S(1), S(1)), JyKet(S(1), S(-1))))))---"), r"---(hbar*|1,1>|1,-1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(S(1), JxOp(Symbol("J"))), TensorProduct(JyKet(S(1), S(1)), JyKet(S(1), S(-1))))))---"), r"---(-hbar*|1,1>|1,-1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(JxOp(Symbol("J")), S(1)), TensorProduct(JzKet(S(1), S(1)), JzKet(S(1), S(-1))))))---"), r"---(sqrt(2)*hbar*|1,0>|1,-1>/2)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(S(1), JxOp(Symbol("J"))), TensorProduct(JzKet(S(1), S(1)), JzKet(S(1), S(-1))))))---"), r"---(sqrt(2)*hbar*|1,1>|1,0>/2)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(JxOp(Symbol("J")), S(1)), TensorProduct(JxKet(j1, m1), JxKet(j2, m2)))))---"), r"---(hbar*m1*|j1,m1>|j2,m2>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(S(1), JxOp(Symbol("J"))), TensorProduct(JxKet(j1, m1), JxKet(j2, m2)))))---"), r"---(hbar*m2*|j1,m1>|j2,m2>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(JxOp(Symbol("J")), S(1)), TensorProduct(JyKet(j1, m1), JyKet(j2, m2)))))---"), r"---(Sum(hbar*mi*WignerD(j1, mi, m1, 0, 0, pi/2)*Sum(WignerD(j1, mi1, mi, 3*pi/2, 0, 0)*|j1,mi1>, (mi1, -j1, j1)), (mi, -j1, j1))x|j2,m2>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(S(1), JxOp(Symbol("J"))), TensorProduct(JyKet(j1, m1), JyKet(j2, m2)))))---"), r"---(|j1,m1>Sum(hbar*mi*WignerD(j2, mi, m2, 0, 0, pi/2)*Sum(WignerD(j2, mi1, mi, 3*pi/2, 0, 0)*|j2,mi1>, (mi1, -j2, j2)), (mi, -j2, j2)))---")
})

test_that("test_spin: test_jy", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j1:5 m1:5"))---", r"---(j1 <- .tmp[[1]])---", r"---(j2 <- .tmp[[2]])---", r"---(j3 <- .tmp[[3]])---", r"---(j4 <- .tmp[[4]])---", r"---(m1 <- .tmp[[5]])---", r"---(m2 <- .tmp[[6]])---", r"---(m3 <- .tmp[[7]])---", r"---(m4 <- .tmp[[8]])---", r"---(.tmp <- sym_symbols("j12 j13 j24 j34 j123 j134 mi mi1 mp"))---", r"---(j12 <- .tmp[[1]])---", r"---(j13 <- .tmp[[2]])---", r"---(j24 <- .tmp[[3]])---", r"---(j34 <- .tmp[[4]])---", r"---(j123 <- .tmp[[5]])---", r"---(j134 <- .tmp[[6]])---", r"---(mi <- .tmp[[7]])---", r"---(mi1 <- .tmp[[8]])---", r"---(mp <- .tmp[[9]])---"), 'test_spin')
  expect_equal(.run(e, r"---(doit(Commutator(JyOp(Symbol("J")), JzOp(Symbol("J")))))---"), r"---(hbar*I*Jx)---")
  expect_equal(.run(e, r"---(rewrite(JyOp(Symbol("J")), "plusminus"))---"), r"---(-I*(-J- + J+)/2)---")
  expect_equal(.run(e, r"---(represent(JyOp(Symbol("J")), basis = JzOp(Symbol("J"))))---"), r"---(Matrix([[0, -hbar*I/2], [hbar*I/2, 0]]))---")
  expect_equal(.run(e, r"---(qapply(.pymul(JyOp(Symbol("J")), JxKet(S(1), S(1)))))---"), r"---(hbar*|1,1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JyOp(Symbol("J")), JyKet(S(1), S(1)))))---"), r"---(hbar*|1,1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JyOp(Symbol("J")), JzKet(S(1), S(1)))))---"), r"---(sqrt(2)*hbar*I*|1,0>/2)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JyOp(Symbol("J")), JxKet(Symbol("j"), Symbol("m")))))---"), r"---(Sum(hbar*mi*WignerD(j, mi, m, 3*pi/2, 0, 0)*Sum(WignerD(j, mi1, mi, 0, 0, pi/2)*|j,mi1>, (mi1, -j, j)), (mi, -j, j)))---")
  expect_equal(.run(e, r"---(qapply(.pymul(JyOp(Symbol("J")), JyKet(Symbol("j"), Symbol("m")))))---"), r"---(hbar*m*|j,m>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JyOp(Symbol("J")), JzKet(Symbol("j"), Symbol("m")))))---"), r"---(-hbar*I*sqrt(j^2 + j - m^2 - m)*|j,m + 1>/2 + hbar*I*sqrt(j^2 + j - m^2 + m)*|j,m - 1>/2)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JyOp(Symbol("J")), JxKetCoupled(S(1), S(1), list(S(1), S(1))))))---"), r"---(hbar*|1,1,j1=1,j2=1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JyOp(Symbol("J")), JyKetCoupled(S(1), S(1), list(S(1), S(1))))))---"), r"---(hbar*|1,1,j1=1,j2=1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JyOp(Symbol("J")), JzKetCoupled(S(1), S(1), list(S(1), S(1))))))---"), r"---(sqrt(2)*hbar*I*|1,0,j1=1,j2=1>/2)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JyOp(Symbol("J")), JxKetCoupled(Symbol("j"), Symbol("m"), list(j1, j2)))))---"), r"---(Sum(hbar*mi*WignerD(j, mi, m, 3*pi/2, 0, 0)*Sum(WignerD(j, mi1, mi, 0, 0, pi/2)*|j,mi1,j1=j1,j2=j2>, (mi1, -j, j)), (mi, -j, j)))---")
  expect_equal(.run(e, r"---(qapply(.pymul(JyOp(Symbol("J")), JyKetCoupled(Symbol("j"), Symbol("m"), list(j1, j2)))))---"), r"---(hbar*m*|j,m,j1=j1,j2=j2>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JyOp(Symbol("J")), JzKetCoupled(Symbol("j"), Symbol("m"), list(j1, j2)))))---"), r"---(-hbar*I*sqrt(j^2 + j - m^2 - m)*|j,m + 1,j1=j1,j2=j2>/2 + hbar*I*sqrt(j^2 + j - m^2 + m)*|j,m - 1,j1=j1,j2=j2>/2)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JyOp(Symbol("J")), TensorProduct(JxKet(S(1), S(1)), JxKet(S(1), S(1))))))---"), r"---(2*hbar*|1,1>|1,1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JyOp(Symbol("J")), TensorProduct(JyKet(S(1), S(1)), JyKet(S(1), S(1))))))---"), r"---(2*hbar*|1,1>|1,1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JyOp(Symbol("J")), TensorProduct(JzKet(S(1), S(1)), JzKet(S(1), S(1))))))---"), r"---(sqrt(2)*hbar*I*|1,0>|1,1>/2 + sqrt(2)*hbar*I*|1,1>|1,0>/2)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JyOp(Symbol("J")), TensorProduct(JyKet(S(1), S(1)), JyKet(S(1), S(-1))))))---"), r"---(0)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JyOp(Symbol("J")), TensorProduct(JxKet(j1, m1), JxKet(j2, m2)))))---"), r"---(|j1,m1>Sum(hbar*mi*WignerD(j2, mi, m2, 3*pi/2, 0, 0)*Sum(WignerD(j2, mi1, mi, 0, 0, pi/2)*|j2,mi1>, (mi1, -j2, j2)), (mi, -j2, j2)) + Sum(hbar*mi*WignerD(j1, mi, m1, 3*pi/2, 0, 0)*Sum(WignerD(j1, mi1, mi, 0, 0, pi/2)*|j1,mi1>, (mi1, -j1, j1)), (mi, -j1, j1))x|j2,m2>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JyOp(Symbol("J")), TensorProduct(JyKet(j1, m1), JyKet(j2, m2)))))---"), r"---(hbar*m1*|j1,m1>|j2,m2> + hbar*m2*|j1,m1>|j2,m2>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JyOp(Symbol("J")), TensorProduct(JzKet(j1, m1), JzKet(j2, m2)))))---"), r"---(-hbar*I*sqrt(j1^2 + j1 - m1^2 - m1)*|j1,m1 + 1>|j2,m2>/2 + hbar*I*sqrt(j1^2 + j1 - m1^2 + m1)*|j1,m1 - 1>|j2,m2>/2 - hbar*I*sqrt(j2^2 + j2 - m2^2 - m2)*|j1,m1>|j2,m2 + 1>/2 + hbar*I*sqrt(j2^2 + j2 - m2^2 + m2)*|j1,m1>|j2,m2 - 1>/2)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(JyOp(Symbol("J")), S(1)), TensorProduct(JxKet(S(1), S(1)), JxKet(S(1), S(-1))))))---"), r"---(hbar*|1,1>|1,-1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(S(1), JyOp(Symbol("J"))), TensorProduct(JxKet(S(1), S(1)), JxKet(S(1), S(-1))))))---"), r"---(-hbar*|1,1>|1,-1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(JyOp(Symbol("J")), S(1)), TensorProduct(JyKet(S(1), S(1)), JyKet(S(1), S(-1))))))---"), r"---(hbar*|1,1>|1,-1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(S(1), JyOp(Symbol("J"))), TensorProduct(JyKet(S(1), S(1)), JyKet(S(1), S(-1))))))---"), r"---(-hbar*|1,1>|1,-1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(JyOp(Symbol("J")), S(1)), TensorProduct(JzKet(S(1), S(1)), JzKet(S(1), S(-1))))))---"), r"---(sqrt(2)*hbar*I*|1,0>|1,-1>/2)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(S(1), JyOp(Symbol("J"))), TensorProduct(JzKet(S(1), S(1)), JzKet(S(1), S(-1))))))---"), r"---(-sqrt(2)*hbar*I*|1,1>|1,0>/2)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(JyOp(Symbol("J")), S(1)), TensorProduct(JxKet(j1, m1), JxKet(j2, m2)))))---"), r"---(Sum(hbar*mi*WignerD(j1, mi, m1, 3*pi/2, 0, 0)*Sum(WignerD(j1, mi1, mi, 0, 0, pi/2)*|j1,mi1>, (mi1, -j1, j1)), (mi, -j1, j1))x|j2,m2>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(S(1), JyOp(Symbol("J"))), TensorProduct(JxKet(j1, m1), JxKet(j2, m2)))))---"), r"---(|j1,m1>Sum(hbar*mi*WignerD(j2, mi, m2, 3*pi/2, 0, 0)*Sum(WignerD(j2, mi1, mi, 0, 0, pi/2)*|j2,mi1>, (mi1, -j2, j2)), (mi, -j2, j2)))---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(JyOp(Symbol("J")), S(1)), TensorProduct(JyKet(j1, m1), JyKet(j2, m2)))))---"), r"---(hbar*m1*|j1,m1>|j2,m2>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(S(1), JyOp(Symbol("J"))), TensorProduct(JyKet(j1, m1), JyKet(j2, m2)))))---"), r"---(hbar*m2*|j1,m1>|j2,m2>)---")
})

test_that("test_spin: test_jz", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j1:5 m1:5"))---", r"---(j1 <- .tmp[[1]])---", r"---(j2 <- .tmp[[2]])---", r"---(j3 <- .tmp[[3]])---", r"---(j4 <- .tmp[[4]])---", r"---(m1 <- .tmp[[5]])---", r"---(m2 <- .tmp[[6]])---", r"---(m3 <- .tmp[[7]])---", r"---(m4 <- .tmp[[8]])---", r"---(.tmp <- sym_symbols("j12 j13 j24 j34 j123 j134 mi mi1 mp"))---", r"---(j12 <- .tmp[[1]])---", r"---(j13 <- .tmp[[2]])---", r"---(j24 <- .tmp[[3]])---", r"---(j34 <- .tmp[[4]])---", r"---(j123 <- .tmp[[5]])---", r"---(j134 <- .tmp[[6]])---", r"---(mi <- .tmp[[7]])---", r"---(mi1 <- .tmp[[8]])---", r"---(mp <- .tmp[[9]])---"), 'test_spin')
  expect_equal(.run(e, r"---(doit(Commutator(JzOp(Symbol("J")), JminusOp(Symbol("J")))))---"), r"---(-hbar*J-)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JzOp(Symbol("J")), JxKet(S(1), S(1)))))---"), r"---(-sqrt(2)*hbar*|1,0>/2)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JzOp(Symbol("J")), JyKet(S(1), S(1)))))---"), r"---(-sqrt(2)*hbar*I*|1,0>/2)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JzOp(Symbol("J")), JzKet(S(2), S(1)))))---"), r"---(hbar*|2,1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JzOp(Symbol("J")), JxKet(Symbol("j"), Symbol("m")))))---"), r"---(Sum(hbar*mi*WignerD(j, mi, m, 0, pi/2, 0)*Sum(WignerD(j, mi1, mi, 0, 3*pi/2, 0)*|j,mi1>, (mi1, -j, j)), (mi, -j, j)))---")
  expect_equal(.run(e, r"---(qapply(.pymul(JzOp(Symbol("J")), JyKet(Symbol("j"), Symbol("m")))))---"), r"---(Sum(hbar*mi*WignerD(j, mi, m, 3*pi/2, -pi/2, pi/2)*Sum(WignerD(j, mi1, mi, 3*pi/2, pi/2, pi/2)*|j,mi1>, (mi1, -j, j)), (mi, -j, j)))---")
  expect_equal(.run(e, r"---(qapply(.pymul(JzOp(Symbol("J")), JzKet(Symbol("j"), Symbol("m")))))---"), r"---(hbar*m*|j,m>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JzOp(Symbol("J")), JxKetCoupled(S(1), S(1), list(S(1), S(1))))))---"), r"---(-sqrt(2)*hbar*|1,0,j1=1,j2=1>/2)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JzOp(Symbol("J")), JyKetCoupled(S(1), S(1), list(S(1), S(1))))))---"), r"---(-sqrt(2)*hbar*I*|1,0,j1=1,j2=1>/2)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JzOp(Symbol("J")), JzKetCoupled(S(1), S(1), list(S(1), S(1))))))---"), r"---(hbar*|1,1,j1=1,j2=1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JzOp(Symbol("J")), JxKetCoupled(Symbol("j"), Symbol("m"), list(j1, j2)))))---"), r"---(Sum(hbar*mi*WignerD(j, mi, m, 0, pi/2, 0)*Sum(WignerD(j, mi1, mi, 0, 3*pi/2, 0)*|j,mi1,j1=j1,j2=j2>, (mi1, -j, j)), (mi, -j, j)))---")
  expect_equal(.run(e, r"---(qapply(.pymul(JzOp(Symbol("J")), JyKetCoupled(Symbol("j"), Symbol("m"), list(j1, j2)))))---"), r"---(Sum(hbar*mi*WignerD(j, mi, m, 3*pi/2, -pi/2, pi/2)*Sum(WignerD(j, mi1, mi, 3*pi/2, pi/2, pi/2)*|j,mi1,j1=j1,j2=j2>, (mi1, -j, j)), (mi, -j, j)))---")
  expect_equal(.run(e, r"---(qapply(.pymul(JzOp(Symbol("J")), JzKetCoupled(Symbol("j"), Symbol("m"), list(j1, j2)))))---"), r"---(hbar*m*|j,m,j1=j1,j2=j2>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JzOp(Symbol("J")), TensorProduct(JxKet(S(1), S(1)), JxKet(S(1), S(1))))))---"), r"---(-sqrt(2)*hbar*|1,0>|1,1>/2 - sqrt(2)*hbar*|1,1>|1,0>/2)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JzOp(Symbol("J")), TensorProduct(JyKet(S(1), S(1)), JyKet(S(1), S(1))))))---"), r"---(-sqrt(2)*hbar*I*|1,0>|1,1>/2 - sqrt(2)*hbar*I*|1,1>|1,0>/2)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JzOp(Symbol("J")), TensorProduct(JzKet(S(1), S(1)), JzKet(S(1), S(1))))))---"), r"---(2*hbar*|1,1>|1,1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JzOp(Symbol("J")), TensorProduct(JzKet(S(1), S(1)), JzKet(S(1), S(-1))))))---"), r"---(0)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JzOp(Symbol("J")), TensorProduct(JxKet(j1, m1), JxKet(j2, m2)))))---"), r"---(|j1,m1>Sum(hbar*mi*WignerD(j2, mi, m2, 0, pi/2, 0)*Sum(WignerD(j2, mi1, mi, 0, 3*pi/2, 0)*|j2,mi1>, (mi1, -j2, j2)), (mi, -j2, j2)) + Sum(hbar*mi*WignerD(j1, mi, m1, 0, pi/2, 0)*Sum(WignerD(j1, mi1, mi, 0, 3*pi/2, 0)*|j1,mi1>, (mi1, -j1, j1)), (mi, -j1, j1))x|j2,m2>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JzOp(Symbol("J")), TensorProduct(JyKet(j1, m1), JyKet(j2, m2)))))---"), r"---(|j1,m1>Sum(hbar*mi*WignerD(j2, mi, m2, 3*pi/2, -pi/2, pi/2)*Sum(WignerD(j2, mi1, mi, 3*pi/2, pi/2, pi/2)*|j2,mi1>, (mi1, -j2, j2)), (mi, -j2, j2)) + Sum(hbar*mi*WignerD(j1, mi, m1, 3*pi/2, -pi/2, pi/2)*Sum(WignerD(j1, mi1, mi, 3*pi/2, pi/2, pi/2)*|j1,mi1>, (mi1, -j1, j1)), (mi, -j1, j1))x|j2,m2>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(JzOp(Symbol("J")), TensorProduct(JzKet(j1, m1), JzKet(j2, m2)))))---"), r"---(hbar*m1*|j1,m1>|j2,m2> + hbar*m2*|j1,m1>|j2,m2>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(JzOp(Symbol("J")), S(1)), TensorProduct(JxKet(S(1), S(1)), JxKet(S(1), S(-1))))))---"), r"---(-sqrt(2)*hbar*|1,0>|1,-1>/2)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(S(1), JzOp(Symbol("J"))), TensorProduct(JxKet(S(1), S(1)), JxKet(S(1), S(-1))))))---"), r"---(-sqrt(2)*hbar*|1,1>|1,0>/2)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(JzOp(Symbol("J")), S(1)), TensorProduct(JyKet(S(1), S(1)), JyKet(S(1), S(-1))))))---"), r"---(-sqrt(2)*hbar*I*|1,0>|1,-1>/2)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(S(1), JzOp(Symbol("J"))), TensorProduct(JyKet(S(1), S(1)), JyKet(S(1), S(-1))))))---"), r"---(sqrt(2)*hbar*I*|1,1>|1,0>/2)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(JzOp(Symbol("J")), S(1)), TensorProduct(JzKet(S(1), S(1)), JzKet(S(1), S(-1))))))---"), r"---(hbar*|1,1>|1,-1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(S(1), JzOp(Symbol("J"))), TensorProduct(JzKet(S(1), S(1)), JzKet(S(1), S(-1))))))---"), r"---(-hbar*|1,1>|1,-1>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(JzOp(Symbol("J")), S(1)), TensorProduct(JxKet(j1, m1), JxKet(j2, m2)))))---"), r"---(Sum(hbar*mi*WignerD(j1, mi, m1, 0, pi/2, 0)*Sum(WignerD(j1, mi1, mi, 0, 3*pi/2, 0)*|j1,mi1>, (mi1, -j1, j1)), (mi, -j1, j1))x|j2,m2>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(S(1), JzOp(Symbol("J"))), TensorProduct(JxKet(j1, m1), JxKet(j2, m2)))))---"), r"---(|j1,m1>Sum(hbar*mi*WignerD(j2, mi, m2, 0, pi/2, 0)*Sum(WignerD(j2, mi1, mi, 0, 3*pi/2, 0)*|j2,mi1>, (mi1, -j2, j2)), (mi, -j2, j2)))---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(JzOp(Symbol("J")), S(1)), TensorProduct(JyKet(j1, m1), JyKet(j2, m2)))))---"), r"---(Sum(hbar*mi*WignerD(j1, mi, m1, 3*pi/2, -pi/2, pi/2)*Sum(WignerD(j1, mi1, mi, 3*pi/2, pi/2, pi/2)*|j1,mi1>, (mi1, -j1, j1)), (mi, -j1, j1))x|j2,m2>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(S(1), JzOp(Symbol("J"))), TensorProduct(JyKet(j1, m1), JyKet(j2, m2)))))---"), r"---(|j1,m1>Sum(hbar*mi*WignerD(j2, mi, m2, 3*pi/2, -pi/2, pi/2)*Sum(WignerD(j2, mi1, mi, 3*pi/2, pi/2, pi/2)*|j2,mi1>, (mi1, -j2, j2)), (mi, -j2, j2)))---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(JzOp(Symbol("J")), S(1)), TensorProduct(JzKet(j1, m1), JzKet(j2, m2)))))---"), r"---(hbar*m1*|j1,m1>|j2,m2>)---")
  expect_equal(.run(e, r"---(qapply(.pymul(TensorProduct(S(1), JzOp(Symbol("J"))), TensorProduct(JzKet(j1, m1), JzKet(j2, m2)))))---"), r"---(hbar*m2*|j1,m1>|j2,m2>)---")
})

test_that("test_spin: test_rotation", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j1:5 m1:5"))---", r"---(j1 <- .tmp[[1]])---", r"---(j2 <- .tmp[[2]])---", r"---(j3 <- .tmp[[3]])---", r"---(j4 <- .tmp[[4]])---", r"---(m1 <- .tmp[[5]])---", r"---(m2 <- .tmp[[6]])---", r"---(m3 <- .tmp[[7]])---", r"---(m4 <- .tmp[[8]])---", r"---(.tmp <- sym_symbols("j12 j13 j24 j34 j123 j134 mi mi1 mp"))---", r"---(j12 <- .tmp[[1]])---", r"---(j13 <- .tmp[[2]])---", r"---(j24 <- .tmp[[3]])---", r"---(j34 <- .tmp[[4]])---", r"---(j123 <- .tmp[[5]])---", r"---(j134 <- .tmp[[6]])---", r"---(mi <- .tmp[[7]])---", r"---(mi1 <- .tmp[[8]])---", r"---(mp <- .tmp[[9]])---"), 'test_spin')
  .do(e, r"---(.tmp <- sym_symbols("a b g"))---")
  .do(e, r"---(a <- .tmp[[1]])---")
  .do(e, r"---(b <- .tmp[[2]])---")
  .do(e, r"---(g <- .tmp[[3]])---")
  .do(e, r"---(.tmp <- sym_symbols("j m"))---")
  .do(e, r"---(j <- .tmp[[1]])---")
  .do(e, r"---(m <- .tmp[[2]])---")
  .do(e, r"---(answ <- list((((JxKet(S(1), S(-1)) / S(2)) - (.pymul(sqrt(S(S(2))), JxKet(S(1), S(0))) / S(2))) + (JxKet(S(1), S(1)) / S(2))), (((JyKet(S(1), S(-1)) / S(2)) - (.pymul(sqrt(S(S(2))), JyKet(S(1), S(0))) / S(2))) + (JyKet(S(1), S(1)) / S(2))), (((JzKet(S(1), S(-1)) / S(2)) - (.pymul(sqrt(S(S(2))), JzKet(S(1), S(0))) / S(2))) + (JzKet(S(1), S(1)) / S(2)))))---")
  .do(e, r"---(fun <- lapply(.qlist(list("JxKet", "JyKet", "JzKet")), function(state) .qcallobj(state, 1, 1)))---")
  expect_equal(.run(e, r"---((!.qbool(answ)))---"), r"---(False)---")
  .do(e, r"---(arg <- .pymul(Rotation(a, b, g), .qidx(fun, 0)))---")
  expect_equal(.run(e, r"---(qapply(arg))---"), r"---(-exp(-I*a)*exp(I*g)*cos(b)*|1,-1>/2 + exp(-I*a)*exp(I*g)*|1,-1>/2 - sqrt(2)*exp(-I*a)*sin(b)*|1,0>/2 + exp(-I*a)*exp(-I*g)*cos(b)*|1,1>/2 + exp(-I*a)*exp(-I*g)*|1,1>/2)---")
  expect_equal(.run(e, r"---(sstr(qapply(.pymul(Rotation(a, b, g), JzKet(j, m)), dummy = FALSE)))---"), r"---(Sum(WignerD(j, m, mp, a, b, g)*|j,mp>, (mp, -j, j)))---")
  .do(e, r"---(ans <- list((((JxKetCoupled(S(1), S(-1), list(S(1), S(1))) / S(2)) - (.pymul(sqrt(S(S(2))), JxKetCoupled(S(1), S(0), list(S(1), S(1)))) / S(2))) + (JxKetCoupled(S(1), S(1), list(S(1), S(1))) / S(2))), (((JyKetCoupled(S(1), S(-1), list(S(1), S(1))) / S(2)) - (.pymul(sqrt(S(S(2))), JyKetCoupled(S(1), S(0), list(S(1), S(1)))) / S(2))) + (JyKetCoupled(S(1), S(1), list(S(1), S(1))) / S(2))), (((JzKetCoupled(S(1), S(-1), list(S(1), S(1))) / S(2)) - (.pymul(sqrt(S(S(2))), JzKetCoupled(S(1), S(0), list(S(1), S(1)))) / S(2))) + (JzKetCoupled(S(1), S(1), list(S(1), S(1))) / S(2)))))---")
  .do(e, r"---(fun <- lapply(.qlist(list("JxKetCoupled", "JyKetCoupled", "JzKetCoupled")), function(state) .qcallobj(state, 1, 1, list(S(1), S(1)))))---")
  expect_equal(.run(e, r"---((!.qbool(ans)))---"), r"---(False)---")
  .do(e, r"---(arg <- .pymul(Rotation(a, b, g), .qidx(fun, 0)))---")
  expect_equal(.run(e, r"---(qapply(arg))---"), r"---(-exp(-I*a)*exp(I*g)*cos(b)*|1,-1,j1=1,j2=1>/2 + exp(-I*a)*exp(I*g)*|1,-1,j1=1,j2=1>/2 - sqrt(2)*exp(-I*a)*sin(b)*|1,0,j1=1,j2=1>/2 + exp(-I*a)*exp(-I*g)*cos(b)*|1,1,j1=1,j2=1>/2 + exp(-I*a)*exp(-I*g)*|1,1,j1=1,j2=1>/2)---")
  expect_equal(.run(e, r"---(sstr(qapply(.pymul(Rotation(a, b, g), JzKetCoupled(j, m, list(j1, j2))), dummy = FALSE)))---"), r"---(Sum(WignerD(j, m, mp, a, b, g)*|j,mp,j1=j1,j2=j2>, (mp, -j, j)))---")
})

test_that("test_spin: test_jzket", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j1:5 m1:5"))---", r"---(j1 <- .tmp[[1]])---", r"---(j2 <- .tmp[[2]])---", r"---(j3 <- .tmp[[3]])---", r"---(j4 <- .tmp[[4]])---", r"---(m1 <- .tmp[[5]])---", r"---(m2 <- .tmp[[6]])---", r"---(m3 <- .tmp[[7]])---", r"---(m4 <- .tmp[[8]])---", r"---(.tmp <- sym_symbols("j12 j13 j24 j34 j123 j134 mi mi1 mp"))---", r"---(j12 <- .tmp[[1]])---", r"---(j13 <- .tmp[[2]])---", r"---(j24 <- .tmp[[3]])---", r"---(j34 <- .tmp[[4]])---", r"---(j123 <- .tmp[[5]])---", r"---(j134 <- .tmp[[6]])---", r"---(mi <- .tmp[[7]])---", r"---(mi1 <- .tmp[[8]])---", r"---(mp <- .tmp[[9]])---"), 'test_spin')
  .do(e, r"---(.tmp <- sym_symbols("j m"))---")
  .do(e, r"---(j <- .tmp[[1]])---")
  .do(e, r"---(m <- .tmp[[2]])---")
  expect_equal(.run(e, r"---(JzKet(Rational(S(2), S(3)), Rational(S(-1), S(3))))---"), r"---(ERR ValueError: j must be integer or half-integer, got: 2/3)---")
  expect_equal(.run(e, r"---(JzKet(Rational(S(2), S(3)), m))---"), r"---(ERR ValueError: j must be integer or half-integer, got: 2/3)---")
  expect_equal(.run(e, r"---(JzKet(S(-1), S(1)))---"), r"---(ERR ValueError: j must be >= 0, got: -1)---")
  expect_equal(.run(e, r"---(JzKet(S(-1), m))---"), r"---(ERR ValueError: j must be >= 0, got: -1)---")
  expect_equal(.run(e, r"---(JzKet(j, Rational(S(-1), S(3))))---"), r"---(ERR ValueError: m must be integer or half-integer, got: -1/3)---")
  expect_equal(.run(e, r"---(JzKet(S(1), S(2)))---"), r"---(ERR ValueError: Allowed values for m are -j <= m <= j, got j, m: 1, 2)---")
  expect_equal(.run(e, r"---(JzKet(S(1), S(-2)))---"), r"---(ERR ValueError: Allowed values for m are -j <= m <= j, got j, m: 1, -2)---")
  expect_equal(.run(e, r"---(JzKet(S(1), S_Half))---"), r"---(ERR ValueError: Both j and m must be integer or half-integer, got j, m: 1, 1/2)---")
})

test_that("test_spin: test_jzketcoupled", {
  e <- .new(c(r"---(.tmp <- sym_symbols("j1:5 m1:5"))---", r"---(j1 <- .tmp[[1]])---", r"---(j2 <- .tmp[[2]])---", r"---(j3 <- .tmp[[3]])---", r"---(j4 <- .tmp[[4]])---", r"---(m1 <- .tmp[[5]])---", r"---(m2 <- .tmp[[6]])---", r"---(m3 <- .tmp[[7]])---", r"---(m4 <- .tmp[[8]])---", r"---(.tmp <- sym_symbols("j12 j13 j24 j34 j123 j134 mi mi1 mp"))---", r"---(j12 <- .tmp[[1]])---", r"---(j13 <- .tmp[[2]])---", r"---(j24 <- .tmp[[3]])---", r"---(j34 <- .tmp[[4]])---", r"---(j123 <- .tmp[[5]])---", r"---(j134 <- .tmp[[6]])---", r"---(mi <- .tmp[[7]])---", r"---(mi1 <- .tmp[[8]])---", r"---(mp <- .tmp[[9]])---"), 'test_spin')
  .do(e, r"---(.tmp <- sym_symbols("j m"))---")
  .do(e, r"---(j <- .tmp[[1]])---")
  .do(e, r"---(m <- .tmp[[2]])---")
  expect_equal(.run(e, r"---(JzKetCoupled(Rational(S(2), S(3)), Rational(S(-1), S(3)), list(S(1))))---"), r"---(ERR ValueError: j must be integer or half-integer, got: 2/3)---")
  expect_equal(.run(e, r"---(JzKetCoupled(Rational(S(2), S(3)), m, list(S(1))))---"), r"---(ERR ValueError: j must be integer or half-integer, got: 2/3)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(-1), S(1), list(S(1))))---"), r"---(ERR ValueError: j must be >= 0, got: -1)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(-1), m, list(S(1))))---"), r"---(ERR ValueError: j must be >= 0, got: -1)---")
  expect_equal(.run(e, r"---(JzKetCoupled(j, Rational(S(-1), S(3)), list(S(1))))---"), r"---(ERR ValueError: m must be integer or half-integer, got: -1/3)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(2), list(S(1))))---"), r"---(ERR ValueError: Allowed values for m are -j <= m <= j, got j, m: 1, 2)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(-2), list(S(1))))---"), r"---(ERR ValueError: Allowed values for m are -j <= m <= j, got j, m: 1, -2)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S_Half, list(S(1))))---"), r"---(ERR ValueError: Both j and m must be integer or half-integer, got j, m: 1, 1/2)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(1), S(1)))---"), r"---(ERR TypeError: object of type 'int' has no len())---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(1), list(S(1)), S(1)))---"), r"---(ERR TypeError: jcoupling must be Tuple, list or tuple, got int)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(1), list(S(1), S(1)), list(S(1))))---"), r"---(ERR TypeError: All elements of jcoupling must be list, tuple or Tuple)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(1), list(S(1), S(1), S(1)), list(S(1), S(2), S(1)), list(S(1), S(3), S(1))))---"), r"---(ERR TypeError: CoupledSpinState only takes 3 or 4 arguments, got: 5)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(1), list(S(1)), list(list(S(1), S(2), S(1)))))---"), r"---(ERR ValueError: jcoupling must have length of 0, got 1)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(1), list(S(1), S(1)), list(list(S(1), S(2)))))---"), r"---(ERR ValueError: All elements of jcoupling must have length 3)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(1), list(Rational(S(1), S(3)), Rational(S(2), S(3)))))---"), r"---(ERR ValueError: All elements of jn must be integer or half-integer, got: (1/3, 2/3))---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(1), list(S(1), S(1)), list(list(S_Half, S(1), S(2)))))---"), r"---(ERR ValueError: Indices in jcoupling must be integers)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(1), list(S(1), S(1)), list(list(S(1), S_Half, S(2)))))---"), r"---(ERR ValueError: Indices in jcoupling must be integers)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(1), list(S(1), S(1)), list(list(S(0), S(2), S(1)))))---"), r"---(ERR ValueError: Indices must be between 1 and the number of coupled spin spaces)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(1), list(S(1), S(1)), list(list(S(3), S(2), S(1)))))---"), r"---(ERR ValueError: Indices must be between 1 and the number of coupled spin spaces)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(1), list(S(1), S(1)), list(list(S(1), S(0), S(1)))))---"), r"---(ERR ValueError: Indices must be between 1 and the number of coupled spin spaces)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(1), list(S(1), S(1)), list(list(S(1), S(3), S(1)))))---"), r"---(ERR ValueError: Indices must be between 1 and the number of coupled spin spaces)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(1), list(S(1), S(1), S(1)), list(list(S(1), S(2), (S(S(4)) / S(3))), list(S(1), S(3), S(1)))))---"), r"---(ERR ValueError: All coupled j values in coupling scheme must be integer or half-integer)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(1), list(S(1), S(5))))---"), r"---(ERR ValueError: All couplings must have |j1+j2| <= j3, in coupling number 1 got j1,j2,j3: 1,5,1)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(5), S(1), list(S(1), S(1))))---"), r"---(ERR ValueError: All couplings must have j1+j2 >= j3, in coupling number 1 got j1,j2,j3: 1,1,5)---")
  expect_equal(.run(e, r"---(JzKetCoupled(S(1), S(1), list(S(1), S(1)), list(list(S(1), S(2), S(2)))))---"), r"---(ERR ValueError: Last j value coupled together must be the final j of the state)---")
})

test_that("test_state: test_ket", {
  e <- .new(c(r"---(.tmp <- sym_symbols("x,y,t"))---", r"---(x <- .tmp[[1]])---", r"---(y <- .tmp[[2]])---", r"---(v_t <- .tmp[[3]])---"), 'test_state')
  .do(e, r"---(k <- Ket("0"))---")
  expect_equal(.run(e, r"---(qisinstance(k, "Ket"))---"), r"---(True)---")
  expect_equal(.run(e, r"---(qisinstance(k, "KetBase"))---"), r"---(True)---")
  expect_equal(.run(e, r"---(qisinstance(k, "StateBase"))---"), r"---(True)---")
  expect_equal(.run(e, r"---(qisinstance(k, "QExpr"))---"), r"---(True)---")
  expect_equal(.run(e, r"---(qattr(k, "label"))---"), r"---([0])---")
  expect_equal(.run(e, r"---(qattr(k, "hilbert_space"))---"), r"---(H)---")
  expect_equal(.run(e, r"---(qattr(k, "is_commutative"))---"), r"---(False)---")
  .do(e, r"---(k <- Ket("pi"))---")
  expect_equal(.run(e, r"---(qattr(k, "label"))---"), r"---([pi])---")
  .do(e, r"---(k <- Ket(x, y))---")
  expect_equal(.run(e, r"---(qattr(k, "label"))---"), r"---([x, y])---")
  expect_equal(.run(e, r"---(qattr(k, "hilbert_space"))---"), r"---(H)---")
  expect_equal(.run(e, r"---(qattr(k, "is_commutative"))---"), r"---(False)---")
  expect_equal(.run(e, r"---(qcall(k, "dual_class"))---"), r"---(Bra)---")
  expect_equal(.run(e, r"---(qattr(k, "dual"))---"), r"---(<xy|)---")
  expect_equal(.run(e, r"---(subs(k, x, y))---"), r"---(|yy>)---")
  .do(e, r"---(k <- CustomKet())---")
  expect_equal(.run(e, r"---(k)---"), r"---(|test>)---")
  .do(e, r"---(k <- CustomKetMultipleLabels())---")
  expect_equal(.run(e, r"---(k)---"), r"---(|rthetaphi>)---")
  expect_equal(.run(e, r"---(Ket())---"), r"---(|psi>)---")
})

