test_that("test_state: test_time_dep_ket", {
  e <- .new(c(r"---(.tmp <- sym_symbols("x,y,t"))---", r"---(x <- .tmp[[1]])---", r"---(y <- .tmp[[2]])---", r"---(v_t <- .tmp[[3]])---"), 'test_state')
  .do(e, r"---(k <- TimeDepKet(S(0), v_t))---")
  expect_equal(.run(e, r"---(qisinstance(k, "TimeDepKet"))---"), r"---(True)---")
  expect_equal(.run(e, r"---(qisinstance(k, "KetBase"))---"), r"---(True)---")
  expect_equal(.run(e, r"---(qisinstance(k, "StateBase"))---"), r"---(True)---")
  expect_equal(.run(e, r"---(qisinstance(k, "QExpr"))---"), r"---(True)---")
  expect_equal(.run(e, r"---(qattr(k, "label"))---"), r"---([0])---")
  expect_equal(.run(e, r"---(qattr(k, "args"))---"), r"---([0, t])---")
  expect_equal(.run(e, r"---(qattr(k, "time"))---"), r"---(t)---")
  expect_equal(.run(e, r"---(qcall(k, "dual_class"))---"), r"---(TimeDepBra)---")
  expect_equal(.run(e, r"---(qattr(k, "dual"))---"), r"---(<0;t|)---")
  expect_equal(.run(e, r"---(subs(k, v_t, S(2)))---"), r"---(|0;2>)---")
  .do(e, r"---(k <- TimeDepKet(x, 0.5))---")
  expect_equal(.run(e, r"---(qattr(k, "label"))---"), r"---([x])---")
  expect_equal(.run(e, r"---(qattr(k, "args"))---"), r"---([x, 0.500000000000000])---")
  .do(e, r"---(k <- CustomTimeDepKet())---")
  expect_equal(.run(e, r"---(qattr(k, "label"))---"), r"---([test])---")
  expect_equal(.run(e, r"---(qattr(k, "time"))---"), r"---(t)---")
  expect_equal(.run(e, r"---(k)---"), r"---(|test;t>)---")
  .do(e, r"---(k <- CustomTimeDepKetMultipleLabels())---")
  expect_equal(.run(e, r"---(qattr(k, "label"))---"), r"---([r, theta, phi])---")
  expect_equal(.run(e, r"---(qattr(k, "time"))---"), r"---(t)---")
  expect_equal(.run(e, r"---(k)---"), r"---(|rthetaphi;t>)---")
  expect_equal(.run(e, r"---(TimeDepKet())---"), r"---(|psi;t>)---")
})

